namespace py = pybind11;

using cdouble = std::complex<double>;

#ifdef __APPLE__
extern "C" void zgesvd_(
    char* jobu,
    char* jobvt,
    int* m,
    int* n,
    cdouble* a,
    int* lda,
    double* s,
    cdouble* u,
    int* ldu,
    cdouble* vt,
    int* ldvt,
    cdouble* work,
    int* lwork,
    double* rwork,
    int* info
);
#endif

static double wall_seconds() {
    using clock = std::chrono::steady_clock;
    return std::chrono::duration<double>(clock::now().time_since_epoch()).count();
}

static py::object tuple_from_sequence_object(const py::object& value);

static std::string py_handle_identity(py::handle obj) {
    return std::to_string(reinterpret_cast<std::uintptr_t>(obj.ptr()));
}

struct Block {
    const cdouble* data;
    ssize_t rows;
    ssize_t cols;
    ssize_t row_stride;
    ssize_t col_stride;
    ssize_t in_start;
    ssize_t out_start;
};

struct SparseBlock {
    const long long* rows;
    const long long* cols;
    const cdouble* values;
    ssize_t nnz;
    ssize_t in_start;
    ssize_t out_start;
};

static double norm2(const std::vector<cdouble>& v) {
    double s = 0.0;
    for (const auto& x : v) {
        s += std::norm(x);
    }
    return std::sqrt(s);
}

static cdouble dotc(const std::vector<cdouble>& a, const std::vector<cdouble>& b) {
    cdouble s = 0.0;
    const ssize_t n = static_cast<ssize_t>(a.size());
    for (ssize_t i = 0; i < n; ++i) {
        s += std::conj(a[i]) * b[i];
    }
    return s;
}

static void axpy(std::vector<cdouble>& y, cdouble a, const std::vector<cdouble>& x) {
    const ssize_t n = static_cast<ssize_t>(y.size());
    for (ssize_t i = 0; i < n; ++i) {
        y[i] += a * x[i];
    }
}

static std::vector<cdouble> matvec_blocks(
    const std::vector<Block>& blocks,
    const std::vector<cdouble>& x,
    ssize_t dim
) {
    std::vector<cdouble> out(static_cast<size_t>(dim), cdouble(0.0, 0.0));
    for (const auto& block : blocks) {
        for (ssize_t row = 0; row < block.rows; ++row) {
            cdouble total = 0.0;
            const cdouble* row_ptr = block.data + row * block.row_stride;
            for (ssize_t col = 0; col < block.cols; ++col) {
                total += row_ptr[col * block.col_stride] * x[static_cast<size_t>(block.in_start + col)];
            }
            out[static_cast<size_t>(block.out_start + row)] += total;
        }
    }
    return out;
}

static py::tuple lapack_svd(py::object matrix_obj) {
#ifndef __APPLE__
    throw std::runtime_error("lapack_svd is only enabled on macOS Accelerate builds");
#else
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> matrix =
        py::array_t<cdouble, py::array::c_style | py::array::forcecast>::ensure(matrix_obj);
    if (!matrix) {
        throw std::runtime_error("lapack_svd expects a dense matrix");
    }
    if (matrix.ndim() != 2) {
        throw std::runtime_error("lapack_svd expects a rank-2 matrix");
    }
    const int m = static_cast<int>(matrix.shape(0));
    const int n = static_cast<int>(matrix.shape(1));
    const int k = std::min(m, n);
    py::array_t<cdouble> u_out({m, k});
    py::array_t<double> s_out({k});
    py::array_t<cdouble> vt_out({k, n});
    if (m == 0 || n == 0) {
        return py::make_tuple(u_out, s_out, vt_out);
    }
    const int lda = std::max(1, m);
    const int ldu = std::max(1, m);
    const int ldvt = std::max(1, k);
    std::vector<cdouble> a(static_cast<size_t>(lda) * static_cast<size_t>(n));
    auto mat = matrix.unchecked<2>();
    for (int row = 0; row < m; ++row) {
        for (int col = 0; col < n; ++col) {
            a[static_cast<size_t>(row) + static_cast<size_t>(col) * static_cast<size_t>(lda)] =
                mat(row, col);
        }
    }
    std::vector<double> s(static_cast<size_t>(k));
    std::vector<cdouble> u(static_cast<size_t>(ldu) * static_cast<size_t>(k));
    std::vector<cdouble> vt(static_cast<size_t>(ldvt) * static_cast<size_t>(n));
    std::vector<double> rwork(static_cast<size_t>(std::max(1, 5 * k)));
    char jobu = 'S';
    char jobvt = 'S';
    int m_arg = m;
    int n_arg = n;
    int lda_arg = lda;
    int ldu_arg = ldu;
    int ldvt_arg = ldvt;
    int info = 0;
    int lwork = -1;
    cdouble work_query;
    zgesvd_(
        &jobu,
        &jobvt,
        &m_arg,
        &n_arg,
        a.data(),
        &lda_arg,
        s.data(),
        u.data(),
        &ldu_arg,
        vt.data(),
        &ldvt_arg,
        &work_query,
        &lwork,
        rwork.data(),
        &info
    );
    if (info != 0) {
        throw std::runtime_error("zgesvd workspace query failed");
    }
    lwork = std::max(1, static_cast<int>(std::real(work_query)));
    std::vector<cdouble> work(static_cast<size_t>(lwork));
    zgesvd_(
        &jobu,
        &jobvt,
        &m_arg,
        &n_arg,
        a.data(),
        &lda_arg,
        s.data(),
        u.data(),
        &ldu_arg,
        vt.data(),
        &ldvt_arg,
        work.data(),
        &lwork,
        rwork.data(),
        &info
    );
    if (info != 0) {
        throw std::runtime_error("zgesvd failed to converge");
    }
    auto u_view = u_out.mutable_unchecked<2>();
    auto s_view = s_out.mutable_unchecked<1>();
    auto vt_view = vt_out.mutable_unchecked<2>();
    for (int col = 0; col < k; ++col) {
        s_view(col) = s[static_cast<size_t>(col)];
        for (int row = 0; row < m; ++row) {
            u_view(row, col) =
                u[static_cast<size_t>(row) + static_cast<size_t>(col) * static_cast<size_t>(ldu)];
        }
    }
    for (int col = 0; col < n; ++col) {
        for (int row = 0; row < k; ++row) {
            vt_view(row, col) =
                vt[static_cast<size_t>(row) + static_cast<size_t>(col) * static_cast<size_t>(ldvt)];
        }
    }
    return py::make_tuple(u_out, s_out, vt_out);
#endif
}

struct AbelianTwoSiteEntry {
    long long q_left;
    long long q_phys_left;
    long long q_right;
    long long q_phys_right;
    long long q_mid;
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> block;
    ssize_t d0;
    ssize_t d1;
    ssize_t d2;
    ssize_t d3;
};

struct AbelianSectorSvdStore {
    py::array_t<cdouble> u;
    py::array_t<double> s;
    py::array_t<cdouble> vt;
    std::vector<std::pair<long long, long long>> rows;
    std::vector<std::pair<long long, long long>> cols;
    std::map<std::pair<long long, long long>, ssize_t> row_starts;
    std::map<std::pair<long long, long long>, ssize_t> col_starts;
    std::map<std::pair<long long, long long>, std::array<ssize_t, 2>> row_dims;
    std::map<std::pair<long long, long long>, std::array<ssize_t, 2>> col_dims;
};

struct AbelianSingularEntry {
    double value;
    long long q_mid;
    ssize_t index;
};

static long long py_int_sector(py::handle value) {
    try {
        return py::cast<long long>(value);
    } catch (const py::cast_error&) {
        throw std::runtime_error(
            "native Abelian two-site SVD currently supports integer sector labels only"
        );
    }
}

static std::vector<std::pair<ssize_t, ssize_t>> cluster_descending_values(
    const std::vector<double>& values,
    double rtol = 1.0e-10,
    double atol = 1.0e-12
) {
    std::vector<std::pair<ssize_t, ssize_t>> clusters;
    const ssize_t n = static_cast<ssize_t>(values.size());
    ssize_t start = 0;
    while (start < n) {
        ssize_t stop = start + 1;
        const double reference = std::abs(values[static_cast<size_t>(start)]);
        while (stop < n) {
            const double current = std::abs(values[static_cast<size_t>(stop)]);
            const double tol = std::max(atol, rtol * std::max(reference, current));
            if (std::abs(values[static_cast<size_t>(stop)] - values[static_cast<size_t>(start)]) > tol) {
                break;
            }
            ++stop;
        }
        clusters.emplace_back(start, stop);
        start = stop;
    }
    return clusters;
}

static void fix_phase_inplace(std::vector<cdouble>& vec) {
    if (vec.empty()) {
        return;
    }
    ssize_t best = 0;
    double best_abs = 0.0;
    for (ssize_t i = 0; i < static_cast<ssize_t>(vec.size()); ++i) {
        const double mag = std::abs(vec[static_cast<size_t>(i)]);
        if (mag > best_abs) {
            best_abs = mag;
            best = i;
        }
    }
    if (best_abs <= 0.0) {
        return;
    }
    const cdouble phase = std::conj(vec[static_cast<size_t>(best)]) / best_abs;
    for (auto& value : vec) {
        value *= phase;
    }
}

static std::vector<cdouble> canonical_subspace_rotation(
    const py::detail::unchecked_reference<cdouble, 2>& u,
    ssize_t start,
    ssize_t stop
) {
    const ssize_t rows = u.shape(0);
    const ssize_t ncol = stop - start;
    std::vector<cdouble> rotation(static_cast<size_t>(ncol * ncol), cdouble(0.0, 0.0));
    if (ncol <= 1) {
        if (ncol == 1) {
            rotation[0] = 1.0;
        }
        return rotation;
    }
    const double tol = 100.0 * std::numeric_limits<double>::epsilon() *
        static_cast<double>(std::max<ssize_t>(1, ncol));
    std::vector<std::vector<cdouble>> vectors;
    vectors.reserve(static_cast<size_t>(ncol));
    for (ssize_t row = 0; row < rows; ++row) {
        std::vector<cdouble> candidate(static_cast<size_t>(ncol));
        for (ssize_t col = 0; col < ncol; ++col) {
            candidate[static_cast<size_t>(col)] =
                std::conj(u(row, start + col));
        }
        for (int repeat = 0; repeat < 2; ++repeat) {
            for (const auto& basis : vectors) {
                cdouble projection = 0.0;
                for (ssize_t col = 0; col < ncol; ++col) {
                    projection += std::conj(basis[static_cast<size_t>(col)]) *
                        candidate[static_cast<size_t>(col)];
                }
                for (ssize_t col = 0; col < ncol; ++col) {
                    candidate[static_cast<size_t>(col)] -=
                        basis[static_cast<size_t>(col)] * projection;
                }
            }
        }
        double norm_sq = 0.0;
        for (const auto& value : candidate) {
            norm_sq += std::norm(value);
        }
        const double norm = std::sqrt(norm_sq);
        if (norm <= tol) {
            continue;
        }
        for (auto& value : candidate) {
            value /= norm;
        }
        fix_phase_inplace(candidate);
        vectors.push_back(std::move(candidate));
        if (static_cast<ssize_t>(vectors.size()) == ncol) {
            break;
        }
    }
    if (static_cast<ssize_t>(vectors.size()) != ncol) {
        std::fill(rotation.begin(), rotation.end(), cdouble(0.0, 0.0));
        for (ssize_t col = 0; col < ncol; ++col) {
            rotation[static_cast<size_t>(col * ncol + col)] = 1.0;
        }
        return rotation;
    }
    for (ssize_t col = 0; col < ncol; ++col) {
        for (ssize_t row = 0; row < ncol; ++row) {
            rotation[static_cast<size_t>(row * ncol + col)] =
                vectors[static_cast<size_t>(col)][static_cast<size_t>(row)];
        }
    }
    return rotation;
}

static void canonicalize_svd_pair_cpp(
    py::array_t<cdouble>& u_arr,
    py::array_t<double>& s_arr,
    py::array_t<cdouble>& vt_arr
) {
    auto u = u_arr.mutable_unchecked<2>();
    auto s = s_arr.unchecked<1>();
    auto vt = vt_arr.mutable_unchecked<2>();
    const ssize_t m = u.shape(0);
    const ssize_t k = s.shape(0);
    const ssize_t n = vt.shape(1);
    if (k == 0) {
        return;
    }
    std::vector<double> values(static_cast<size_t>(k));
    for (ssize_t i = 0; i < k; ++i) {
        values[static_cast<size_t>(i)] = s(i);
    }
    for (const auto& cluster : cluster_descending_values(values)) {
        const ssize_t start = cluster.first;
        const ssize_t stop = cluster.second;
        const ssize_t ncol = stop - start;
        if (ncol <= 1) {
            continue;
        }
        std::vector<cdouble> rotation = canonical_subspace_rotation(u, start, stop);
        std::vector<cdouble> u_old(static_cast<size_t>(m * ncol));
        std::vector<cdouble> vt_old(static_cast<size_t>(ncol * n));
        for (ssize_t row = 0; row < m; ++row) {
            for (ssize_t col = 0; col < ncol; ++col) {
                u_old[static_cast<size_t>(row * ncol + col)] = u(row, start + col);
            }
        }
        for (ssize_t row = 0; row < ncol; ++row) {
            for (ssize_t col = 0; col < n; ++col) {
                vt_old[static_cast<size_t>(row * n + col)] = vt(start + row, col);
            }
        }
        for (ssize_t row = 0; row < m; ++row) {
            for (ssize_t col = 0; col < ncol; ++col) {
                cdouble total = 0.0;
                for (ssize_t inner = 0; inner < ncol; ++inner) {
                    total += u_old[static_cast<size_t>(row * ncol + inner)] *
                        rotation[static_cast<size_t>(inner * ncol + col)];
                }
                u(row, start + col) = total;
            }
        }
        for (ssize_t row = 0; row < ncol; ++row) {
            for (ssize_t col = 0; col < n; ++col) {
                cdouble total = 0.0;
                for (ssize_t inner = 0; inner < ncol; ++inner) {
                    total += std::conj(rotation[static_cast<size_t>(inner * ncol + row)]) *
                        vt_old[static_cast<size_t>(inner * n + col)];
                }
                vt(start + row, col) = total;
            }
        }
    }
    const ssize_t limit = std::min(u.shape(1), vt.shape(0));
    for (ssize_t col = 0; col < limit; ++col) {
        ssize_t best = 0;
        double best_abs = 0.0;
        for (ssize_t row = 0; row < m; ++row) {
            const double mag = std::abs(u(row, col));
            if (mag > best_abs) {
                best_abs = mag;
                best = row;
            }
        }
        if (best_abs <= 0.0) {
            continue;
        }
        const cdouble phase = std::conj(u(best, col)) / best_abs;
        for (ssize_t row = 0; row < m; ++row) {
            u(row, col) *= phase;
        }
        const cdouble vt_phase = std::conj(phase);
        for (ssize_t vcol = 0; vcol < n; ++vcol) {
            vt(col, vcol) *= vt_phase;
        }
    }
}

static py::tuple abelian_two_site_svd_from_permuted_data_cpp(
    py::object data_obj,
    py::object m_max_obj = py::none()
) {
#ifndef __APPLE__
    throw std::runtime_error(
        "native Abelian two-site SVD is only enabled on macOS Accelerate builds"
    );
#else
    std::vector<AbelianTwoSiteEntry> entries;
    std::map<long long, std::vector<ssize_t>> by_mid;
    std::map<long long, std::map<std::pair<long long, long long>, std::array<ssize_t, 2>>> row_dims_by_mid;
    std::map<long long, std::map<std::pair<long long, long long>, std::array<ssize_t, 2>>> col_dims_by_mid;

    entries.reserve(static_cast<size_t>(py::len(data_obj)));
    py::object items_obj = data_obj.attr("items")();
    for (py::handle item_handle : items_obj) {
        py::tuple item = py::reinterpret_borrow<py::tuple>(item_handle);
        if (py::len(item) != 2) {
            throw std::runtime_error("native Abelian two-site SVD mapping items must be pairs");
        }
        py::tuple key = py::reinterpret_borrow<py::tuple>(item[0]);
        if (py::len(key) != 4 && py::len(key) != 5) {
            throw std::runtime_error("native Abelian two-site SVD expects rank-4 or packed rank-5 keys");
        }
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> block =
            py::array_t<cdouble, py::array::c_style | py::array::forcecast>::ensure(item[1]);
        if (!block || block.ndim() != 4) {
            throw std::runtime_error("native Abelian two-site SVD expects rank-4 dense blocks");
        }
        const long long q_left = py_int_sector(key[0]);
        const long long q_phys_left = py_int_sector(key[1]);
        const long long q_right = py_int_sector(key[2]);
        const long long q_phys_right = py_int_sector(key[3]);
        AbelianTwoSiteEntry entry{
            q_left,
            q_phys_left,
            q_right,
            q_phys_right,
            py::len(key) == 5 ? py_int_sector(key[4]) : q_left + q_phys_left,
            block,
            block.shape(0),
            block.shape(1),
            block.shape(2),
            block.shape(3),
        };
        const ssize_t index = static_cast<ssize_t>(entries.size());
        entries.push_back(std::move(entry));
        const auto& stored = entries.back();
        by_mid[stored.q_mid].push_back(index);
        row_dims_by_mid[stored.q_mid].emplace(
            std::make_pair(stored.q_left, stored.q_phys_left),
            std::array<ssize_t, 2>{stored.d0, stored.d1}
        );
        col_dims_by_mid[stored.q_mid].emplace(
            std::make_pair(stored.q_right, stored.q_phys_right),
            std::array<ssize_t, 2>{stored.d2, stored.d3}
        );
    }

    py::dict final_u;
    py::dict final_v;
    py::dict final_s;
    py::list bond_qns;
    py::dict stats;
    stats[py::str("sectors")] = py::int_(0);
    stats[py::str("rows")] = py::int_(0);
    stats[py::str("cols")] = py::int_(0);
    stats[py::str("entries")] = py::int_(static_cast<ssize_t>(entries.size()));
    if (entries.empty()) {
        return py::make_tuple(final_u, final_v, final_s, bond_qns, 0.0, 0, stats);
    }

    std::map<long long, AbelianSectorSvdStore> stores;
    std::vector<AbelianSingularEntry> singular_entries;
    ssize_t total_rows = 0;
    ssize_t total_cols = 0;

    for (const auto& grouped : by_mid) {
        const long long q_mid = grouped.first;
        AbelianSectorSvdStore store;
        for (const auto& item : row_dims_by_mid[q_mid]) {
            store.rows.push_back(item.first);
            store.row_dims[item.first] = item.second;
        }
        for (const auto& item : col_dims_by_mid[q_mid]) {
            store.cols.push_back(item.first);
            store.col_dims[item.first] = item.second;
        }
        ssize_t r_dim = 0;
        for (const auto& row : store.rows) {
            store.row_starts[row] = r_dim;
            const auto dims = store.row_dims[row];
            r_dim += dims[0] * dims[1];
        }
        ssize_t c_dim = 0;
        for (const auto& col : store.cols) {
            store.col_starts[col] = c_dim;
            const auto dims = store.col_dims[col];
            c_dim += dims[0] * dims[1];
        }
        total_rows += r_dim;
        total_cols += c_dim;
        py::array_t<cdouble> matrix({r_dim, c_dim});
        auto mat = matrix.mutable_unchecked<2>();
        for (ssize_t row = 0; row < r_dim; ++row) {
            for (ssize_t col = 0; col < c_dim; ++col) {
                mat(row, col) = cdouble(0.0, 0.0);
            }
        }
        for (const ssize_t entry_index : grouped.second) {
            const auto& entry = entries[static_cast<size_t>(entry_index)];
            const auto row_key = std::make_pair(entry.q_left, entry.q_phys_left);
            const auto col_key = std::make_pair(entry.q_right, entry.q_phys_right);
            const ssize_t r0 = store.row_starts[row_key];
            const ssize_t c0 = store.col_starts[col_key];
            auto block = entry.block.unchecked<4>();
            for (ssize_t i0 = 0; i0 < entry.d0; ++i0) {
                for (ssize_t i1 = 0; i1 < entry.d1; ++i1) {
                    const ssize_t row = r0 + i0 * entry.d1 + i1;
                    for (ssize_t i2 = 0; i2 < entry.d2; ++i2) {
                        for (ssize_t i3 = 0; i3 < entry.d3; ++i3) {
                            const ssize_t col = c0 + i2 * entry.d3 + i3;
                            mat(row, col) = block(i0, i1, i2, i3);
                        }
                    }
                }
            }
        }
        py::tuple svd = lapack_svd(matrix);
        store.u = svd[0].cast<py::array_t<cdouble>>();
        store.s = svd[1].cast<py::array_t<double>>();
        store.vt = svd[2].cast<py::array_t<cdouble>>();
        canonicalize_svd_pair_cpp(store.u, store.s, store.vt);
        auto s_view = store.s.unchecked<1>();
        for (ssize_t i = 0; i < s_view.shape(0); ++i) {
            singular_entries.push_back(AbelianSingularEntry{s_view(i), q_mid, i});
        }
        stores[q_mid] = std::move(store);
    }

    std::sort(
        singular_entries.begin(),
        singular_entries.end(),
        [](const AbelianSingularEntry& a, const AbelianSingularEntry& b) {
            if (a.value != b.value) {
                return a.value > b.value;
            }
            if (a.q_mid != b.q_mid) {
                return a.q_mid < b.q_mid;
            }
            return a.index < b.index;
        }
    );
    std::vector<double> singular_values;
    singular_values.reserve(singular_entries.size());
    for (const auto& entry : singular_entries) {
        singular_values.push_back(entry.value);
    }
    for (const auto& cluster : cluster_descending_values(singular_values)) {
        std::sort(
            singular_entries.begin() + cluster.first,
            singular_entries.begin() + cluster.second,
            [](const AbelianSingularEntry& a, const AbelianSingularEntry& b) {
                if (a.q_mid != b.q_mid) {
                    return a.q_mid < b.q_mid;
                }
                return a.index < b.index;
            }
        );
    }

    double full_sq_norm = 0.0;
    for (const auto& entry : singular_entries) {
        full_sq_norm += entry.value * entry.value;
    }
    if (!m_max_obj.is_none()) {
        const ssize_t keep_limit = std::max<ssize_t>(0, py::cast<ssize_t>(m_max_obj));
        if (keep_limit < static_cast<ssize_t>(singular_entries.size())) {
            singular_entries.resize(static_cast<size_t>(keep_limit));
        }
    }
    std::map<long long, std::vector<ssize_t>> kept;
    double kept_sq_norm = 0.0;
    for (const auto& entry : singular_entries) {
        kept[entry.q_mid].push_back(entry.index);
        kept_sq_norm += entry.value * entry.value;
    }
    double trunc_err = 0.0;
    if (full_sq_norm > 1.0e-12) {
        trunc_err = 1.0 - kept_sq_norm / full_sq_norm;
    }

    ssize_t kept_states = 0;
    for (auto& item : kept) {
        const long long q_mid = item.first;
        auto& idxs = item.second;
        std::sort(idxs.begin(), idxs.end());
        kept_states += static_cast<ssize_t>(idxs.size());
        auto& store = stores[q_mid];
        auto u = store.u.unchecked<2>();
        auto s = store.s.unchecked<1>();
        auto vt = store.vt.unchecked<2>();
        const ssize_t nkeep = static_cast<ssize_t>(idxs.size());

        py::array_t<double> diag({nkeep, nkeep});
        auto diag_view = diag.mutable_unchecked<2>();
        for (ssize_t row = 0; row < nkeep; ++row) {
            for (ssize_t col = 0; col < nkeep; ++col) {
                diag_view(row, col) = row == col ? s(idxs[static_cast<size_t>(row)]) : 0.0;
            }
        }
        final_s[py::int_(q_mid)] = diag;
        for (ssize_t i = 0; i < nkeep; ++i) {
            bond_qns.append(py::int_(q_mid));
        }

        for (const auto& row_key : store.rows) {
            const auto dims = store.row_dims[row_key];
            const ssize_t d0 = dims[0];
            const ssize_t d1 = dims[1];
            const ssize_t r0 = store.row_starts[row_key];
            py::array_t<cdouble> out({d0, d1, nkeep});
            auto out_view = out.mutable_unchecked<3>();
            for (ssize_t i0 = 0; i0 < d0; ++i0) {
                for (ssize_t i1 = 0; i1 < d1; ++i1) {
                    const ssize_t source_row = r0 + i0 * d1 + i1;
                    for (ssize_t j = 0; j < nkeep; ++j) {
                        out_view(i0, i1, j) = u(source_row, idxs[static_cast<size_t>(j)]);
                    }
                }
            }
            final_u[py::make_tuple(
                py::int_(row_key.first),
                py::int_(row_key.second),
                py::int_(q_mid)
            )] = out;
        }

        for (const auto& col_key : store.cols) {
            const auto dims = store.col_dims[col_key];
            const ssize_t d2 = dims[0];
            const ssize_t d3 = dims[1];
            const ssize_t c0 = store.col_starts[col_key];
            py::array_t<cdouble> out({nkeep, d2, d3});
            auto out_view = out.mutable_unchecked<3>();
            for (ssize_t j = 0; j < nkeep; ++j) {
                const ssize_t source_row = idxs[static_cast<size_t>(j)];
                for (ssize_t i2 = 0; i2 < d2; ++i2) {
                    for (ssize_t i3 = 0; i3 < d3; ++i3) {
                        const ssize_t source_col = c0 + i2 * d3 + i3;
                        out_view(j, i2, i3) = vt(source_row, source_col);
                    }
                }
            }
            final_v[py::make_tuple(
                py::int_(q_mid),
                py::int_(col_key.first),
                py::int_(col_key.second)
            )] = out;
        }
    }

    stats[py::str("sectors")] = py::int_(static_cast<ssize_t>(by_mid.size()));
    stats[py::str("rows")] = py::int_(total_rows);
    stats[py::str("cols")] = py::int_(total_cols);
    stats[py::str("kept_states")] = py::int_(kept_states);
    return py::make_tuple(
        final_u,
        final_v,
        final_s,
        bond_qns,
        trunc_err,
        kept_states,
        stats
    );
#endif
}

static py::tuple abelian_split_two_site_svd_data_cpp(
    py::object data_obj,
    const std::string& direction,
    py::object m_max_obj = py::none()
) {
#ifndef __APPLE__
    throw std::runtime_error(
        "native Abelian two-site split is only enabled on macOS Accelerate builds"
    );
#else
    if (direction != "right" && direction != "left") {
        throw std::runtime_error("native Abelian two-site split direction must be 'right' or 'left'");
    }

    py::dict permuted;
    py::object items_obj = data_obj.attr("items")();
    for (py::handle item_handle : items_obj) {
        py::tuple item = py::reinterpret_borrow<py::tuple>(item_handle);
        if (py::len(item) != 2) {
            throw std::runtime_error("native Abelian split mapping items must be pairs");
        }
        py::tuple key = py::reinterpret_borrow<py::tuple>(item[0]);
        if (py::len(key) != 4 && py::len(key) != 5) {
            throw std::runtime_error("native Abelian split expects rank-4 or packed rank-5 keys");
        }
        const long long q_left = py_int_sector(key[0]);
        const long long q_right = py_int_sector(key[1]);
        const long long q_phys_left = py_int_sector(key[2]);
        const long long q_phys_right = py_int_sector(key[3]);
        const long long q_mid =
            py::len(key) == 5 ? py_int_sector(key[4]) : q_left + q_phys_left;
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> block =
            py::array_t<cdouble, py::array::c_style | py::array::forcecast>::ensure(item[1]);
        if (!block || block.ndim() != 4) {
            throw std::runtime_error("native Abelian split expects rank-4 dense blocks");
        }
        const ssize_t d0 = block.shape(0);
        const ssize_t d1 = block.shape(1);
        const ssize_t d2 = block.shape(2);
        const ssize_t d3 = block.shape(3);
        py::array_t<cdouble> out({d0, d2, d1, d3});
        auto in_view = block.unchecked<4>();
        auto out_view = out.mutable_unchecked<4>();
        for (ssize_t i0 = 0; i0 < d0; ++i0) {
            for (ssize_t i1 = 0; i1 < d1; ++i1) {
                for (ssize_t i2 = 0; i2 < d2; ++i2) {
                    for (ssize_t i3 = 0; i3 < d3; ++i3) {
                        out_view(i0, i2, i1, i3) = in_view(i0, i1, i2, i3);
                    }
                }
            }
        }
        permuted[py::make_tuple(
            py::int_(q_left),
            py::int_(q_phys_left),
            py::int_(q_right),
            py::int_(q_phys_right),
            py::int_(q_mid)
        )] = out;
    }

    py::tuple svd = abelian_two_site_svd_from_permuted_data_cpp(permuted, m_max_obj);
    py::dict u_data = svd[0].cast<py::dict>();
    py::dict v_data = svd[1].cast<py::dict>();
    py::dict s_data = svd[2].cast<py::dict>();
    py::list bond_qns = svd[3].cast<py::list>();
    py::object trunc = svd[4];
    py::object kept = svd[5];
    py::dict stats = svd[6].cast<py::dict>();
    py::dict a_data;
    py::dict b_data;
    const bool move_right = direction == "right";

    for (auto item : u_data) {
        py::tuple key = py::reinterpret_borrow<py::tuple>(item.first);
        const long long q_left = py_int_sector(key[0]);
        const long long q_phys_left = py_int_sector(key[1]);
        const long long q_mid = py_int_sector(key[2]);
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> block =
            py::array_t<cdouble, py::array::c_style | py::array::forcecast>::ensure(item.second);
        if (!block || block.ndim() != 3) {
            throw std::runtime_error("native Abelian split expected rank-3 U block");
        }
        py::array_t<double, py::array::c_style | py::array::forcecast> singular =
            py::array_t<double, py::array::c_style | py::array::forcecast>::ensure(
                s_data[py::int_(q_mid)]
            );
        if (!singular || singular.ndim() != 2) {
            throw std::runtime_error("native Abelian split expected rank-2 singular block");
        }
        const ssize_t d0 = block.shape(0);
        const ssize_t d1 = block.shape(1);
        const ssize_t nkeep = block.shape(2);
        py::array_t<cdouble> out({d0, nkeep, d1});
        auto in_view = block.unchecked<3>();
        auto s_view = singular.unchecked<2>();
        auto out_view = out.mutable_unchecked<3>();
        for (ssize_t i0 = 0; i0 < d0; ++i0) {
            for (ssize_t i1 = 0; i1 < d1; ++i1) {
                for (ssize_t j = 0; j < nkeep; ++j) {
                    const double scale = move_right ? 1.0 : s_view(j, j);
                    out_view(i0, j, i1) = in_view(i0, i1, j) * scale;
                }
            }
        }
        a_data[py::make_tuple(
            py::int_(q_left),
            py::int_(q_mid),
            py::int_(q_phys_left)
        )] = out;
    }

    for (auto item : v_data) {
        py::tuple key = py::reinterpret_borrow<py::tuple>(item.first);
        const long long q_mid = py_int_sector(key[0]);
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> block =
            py::array_t<cdouble, py::array::c_style | py::array::forcecast>::ensure(item.second);
        if (!block || block.ndim() != 3) {
            throw std::runtime_error("native Abelian split expected rank-3 V block");
        }
        if (!move_right) {
            b_data[item.first] = block;
            continue;
        }
        py::array_t<double, py::array::c_style | py::array::forcecast> singular =
            py::array_t<double, py::array::c_style | py::array::forcecast>::ensure(
                s_data[py::int_(q_mid)]
            );
        if (!singular || singular.ndim() != 2) {
            throw std::runtime_error("native Abelian split expected rank-2 singular block");
        }
        const ssize_t nkeep = block.shape(0);
        const ssize_t d1 = block.shape(1);
        const ssize_t d2 = block.shape(2);
        py::array_t<cdouble> out({nkeep, d1, d2});
        auto in_view = block.unchecked<3>();
        auto s_view = singular.unchecked<2>();
        auto out_view = out.mutable_unchecked<3>();
        for (ssize_t j = 0; j < nkeep; ++j) {
            const double scale = s_view(j, j);
            for (ssize_t i1 = 0; i1 < d1; ++i1) {
                for (ssize_t i2 = 0; i2 < d2; ++i2) {
                    out_view(j, i1, i2) = scale * in_view(j, i1, i2);
                }
            }
        }
        b_data[item.first] = out;
    }

    stats[py::str("split_direction")] = py::str(direction);
    return py::make_tuple(
        a_data,
        b_data,
        s_data,
        bond_qns,
        trunc,
        kept,
        stats
    );
#endif
}

static py::tuple abelian_split_flat_two_site_svd_data_cpp(
    py::object vec_obj,
    py::object layout_obj,
    const std::string& direction,
    py::object m_max_obj = py::none()
) {
#ifndef __APPLE__
    throw std::runtime_error(
        "native Abelian flat two-site split is only enabled on macOS Accelerate builds"
    );
#else
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> vec =
        py::array_t<cdouble, py::array::c_style | py::array::forcecast>::ensure(vec_obj);
    if (!vec || vec.ndim() != 1) {
        throw std::runtime_error("native Abelian flat split expects a rank-1 vector");
    }
    auto vec_view = vec.unchecked<1>();
    py::dict data;
    ssize_t pos = 0;
    ssize_t blocks = 0;
    for (py::handle item_handle : layout_obj) {
        py::tuple item = py::reinterpret_borrow<py::tuple>(item_handle);
        if (py::len(item) != 2) {
            throw std::runtime_error("native Abelian flat split layout items must be pairs");
        }
        py::tuple key = py::reinterpret_borrow<py::tuple>(item[0]);
        py::tuple shape = py::reinterpret_borrow<py::tuple>(item[1]);
        if ((py::len(key) != 4 && py::len(key) != 5) || py::len(shape) != 4) {
            throw std::runtime_error(
                "native Abelian flat split expects rank-4 keys/shapes or packed rank-5 keys"
            );
        }
        const ssize_t d0 = py::cast<ssize_t>(shape[0]);
        const ssize_t d1 = py::cast<ssize_t>(shape[1]);
        const ssize_t d2 = py::cast<ssize_t>(shape[2]);
        const ssize_t d3 = py::cast<ssize_t>(shape[3]);
        const ssize_t n = d0 * d1 * d2 * d3;
        if (pos + n > vec_view.shape(0)) {
            throw std::runtime_error("native Abelian flat split layout exceeds vector length");
        }
        py::array_t<cdouble> block({d0, d1, d2, d3});
        auto block_view = block.mutable_unchecked<4>();
        ssize_t offset = 0;
        for (ssize_t i0 = 0; i0 < d0; ++i0) {
            for (ssize_t i1 = 0; i1 < d1; ++i1) {
                for (ssize_t i2 = 0; i2 < d2; ++i2) {
                    for (ssize_t i3 = 0; i3 < d3; ++i3) {
                        block_view(i0, i1, i2, i3) = vec_view(pos + offset);
                        ++offset;
                    }
                }
            }
        }
        data[key] = block;
        pos += n;
        ++blocks;
    }
    if (pos != vec_view.shape(0)) {
        throw std::runtime_error("native Abelian flat split vector has trailing entries");
    }
    py::tuple result = abelian_split_two_site_svd_data_cpp(data, direction, m_max_obj);
    py::dict stats = result[6].cast<py::dict>();
    stats[py::str("flat_blocks")] = py::int_(blocks);
    stats[py::str("flat_dim")] = py::int_(vec_view.shape(0));
    return result;
#endif
}

struct SiteMergeBlock {
    long long q0;
    long long q1;
    long long q2;
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> arr;
    ssize_t d0;
    ssize_t d1;
    ssize_t d2;
};

static SiteMergeBlock parse_site_merge_block(py::handle key_handle, py::handle value_handle) {
    py::tuple key = py::reinterpret_borrow<py::tuple>(key_handle);
    if (py::len(key) != 3) {
        throw std::runtime_error("native Abelian site merge expects rank-3 block keys");
    }
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> arr =
        py::array_t<cdouble, py::array::c_style | py::array::forcecast>::ensure(value_handle);
    if (!arr || arr.ndim() != 3) {
        throw std::runtime_error("native Abelian site merge expects rank-3 block arrays");
    }
    SiteMergeBlock block;
    block.q0 = py::cast<long long>(key[0]);
    block.q1 = py::cast<long long>(key[1]);
    block.q2 = py::cast<long long>(key[2]);
    block.arr = arr;
    block.d0 = arr.shape(0);
    block.d1 = arr.shape(1);
    block.d2 = arr.shape(2);
    return block;
}

static py::tuple abelian_merge_adjacent_site_tensors_data_cpp(
    py::object left_obj,
    py::object right_obj
) {
    std::vector<SiteMergeBlock> left_blocks;
    std::vector<SiteMergeBlock> right_blocks;
    left_blocks.reserve(static_cast<size_t>(py::len(left_obj)));
    right_blocks.reserve(static_cast<size_t>(py::len(right_obj)));

    for (py::handle item_handle : left_obj.attr("items")()) {
        py::tuple item = py::reinterpret_borrow<py::tuple>(item_handle);
        left_blocks.push_back(parse_site_merge_block(item[0], item[1]));
    }
    for (py::handle item_handle : right_obj.attr("items")()) {
        py::tuple item = py::reinterpret_borrow<py::tuple>(item_handle);
        right_blocks.push_back(parse_site_merge_block(item[0], item[1]));
    }

    std::unordered_map<long long, std::vector<size_t>> right_by_middle;
    right_by_middle.reserve(right_blocks.size());
    for (size_t idx = 0; idx < right_blocks.size(); ++idx) {
        right_by_middle[right_blocks[idx].q0].push_back(idx);
    }

    std::map<std::array<long long, 4>, py::array_t<cdouble>> out_blocks;
    ssize_t pairs = 0;
    ssize_t multiply_inner_dim = 0;
    for (const auto& left : left_blocks) {
        auto found_rights = right_by_middle.find(left.q1);
        if (found_rights == right_by_middle.end()) {
            continue;
        }
        auto left_view = left.arr.unchecked<3>();
        for (size_t right_idx : found_rights->second) {
            const auto& right = right_blocks[right_idx];
            if (left.d1 != right.d0) {
                throw std::runtime_error(
                    "native Abelian site merge found mismatched middle block dimensions"
                );
            }
            const std::array<long long, 4> out_key = {
                left.q0,
                right.q1,
                left.q2,
                right.q2,
            };
            auto out_found = out_blocks.find(out_key);
            if (out_found == out_blocks.end()) {
                py::array_t<cdouble> out({left.d0, right.d1, left.d2, right.d2});
                auto out_view = out.mutable_unchecked<4>();
                for (ssize_t i0 = 0; i0 < left.d0; ++i0) {
                    for (ssize_t i1 = 0; i1 < right.d1; ++i1) {
                        for (ssize_t i2 = 0; i2 < left.d2; ++i2) {
                            for (ssize_t i3 = 0; i3 < right.d2; ++i3) {
                                out_view(i0, i1, i2, i3) = cdouble(0.0, 0.0);
                            }
                        }
                    }
                }
                out_found = out_blocks.emplace(out_key, out).first;
            } else if (
                out_found->second.shape(0) != left.d0 ||
                out_found->second.shape(1) != right.d1 ||
                out_found->second.shape(2) != left.d2 ||
                out_found->second.shape(3) != right.d2
            ) {
                throw std::runtime_error(
                    "native Abelian site merge found duplicate output key with different shape"
                );
            }

            auto right_view = right.arr.unchecked<3>();
            auto out_view = out_found->second.mutable_unchecked<4>();
            for (ssize_t i0 = 0; i0 < left.d0; ++i0) {
                for (ssize_t mid = 0; mid < left.d1; ++mid) {
                    for (ssize_t i2 = 0; i2 < left.d2; ++i2) {
                        const cdouble left_value = left_view(i0, mid, i2);
                        for (ssize_t i1 = 0; i1 < right.d1; ++i1) {
                            for (ssize_t i3 = 0; i3 < right.d2; ++i3) {
                                out_view(i0, i1, i2, i3) +=
                                    left_value * right_view(mid, i1, i3);
                            }
                        }
                    }
                }
            }
            ++pairs;
            multiply_inner_dim += left.d1;
        }
    }

    py::dict out;
    for (auto& item : out_blocks) {
        py::tuple key(4);
        key[0] = py::int_(item.first[0]);
        key[1] = py::int_(item.first[1]);
        key[2] = py::int_(item.first[2]);
        key[3] = py::int_(item.first[3]);
        out[key] = item.second;
    }

    py::dict stats;
    stats[py::str("left_blocks")] = py::int_(left_blocks.size());
    stats[py::str("right_blocks")] = py::int_(right_blocks.size());
    stats[py::str("middle_groups")] = py::int_(right_by_middle.size());
    stats[py::str("pairs")] = py::int_(pairs);
    stats[py::str("out_blocks")] = py::int_(out_blocks.size());
    stats[py::str("inner_dim")] = py::int_(multiply_inner_dim);
    return py::make_tuple(out, stats);
}

static py::array_t<cdouble> abelian_flatten_data_to_layout_cpp(
    py::object data_obj,
    py::object layout_obj
) {
    py::dict data = py::reinterpret_borrow<py::dict>(data_obj);
    ssize_t total = 0;
    std::vector<std::pair<py::object, std::vector<ssize_t>>> items;
    const ssize_t n_items = static_cast<ssize_t>(py::len(layout_obj));
    items.reserve(static_cast<size_t>(n_items));
    for (py::handle item_handle : layout_obj) {
        py::tuple item = py::reinterpret_borrow<py::tuple>(item_handle);
        if (py::len(item) != 2) {
            throw std::runtime_error("flatten layout items must be (key, shape) pairs");
        }
        py::object key = py::reinterpret_borrow<py::object>(item[0]);
        py::sequence shape_obj = py::reinterpret_borrow<py::sequence>(item[1]);
        std::vector<ssize_t> shape;
        shape.reserve(static_cast<size_t>(py::len(shape_obj)));
        ssize_t n = 1;
        for (py::handle dim_handle : shape_obj) {
            const ssize_t dim = py::cast<ssize_t>(dim_handle);
            if (dim < 0) {
                throw std::runtime_error("flatten layout contains a negative dimension");
            }
            shape.push_back(dim);
            n *= dim;
        }
        total += n;
        items.emplace_back(key, std::move(shape));
    }

    py::array_t<cdouble> out({total});
    auto out_view = out.mutable_unchecked<1>();
    ssize_t pos = 0;
    for (const auto& item : items) {
        const py::object& key = item.first;
        const std::vector<ssize_t>& shape = item.second;
        ssize_t n = 1;
        for (ssize_t dim : shape) {
            n *= dim;
        }
        if (!data.contains(key)) {
            for (ssize_t idx = 0; idx < n; ++idx) {
                out_view(pos + idx) = cdouble(0.0, 0.0);
            }
            pos += n;
            continue;
        }
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> block =
            py::array_t<cdouble, py::array::c_style | py::array::forcecast>::ensure(data[key]);
        if (!block) {
            throw std::runtime_error("flatten data block is not array-like");
        }
        if (block.ndim() != static_cast<ssize_t>(shape.size())) {
            throw std::runtime_error("flatten data block rank does not match layout shape");
        }
        for (ssize_t axis = 0; axis < block.ndim(); ++axis) {
            if (block.shape(axis) != shape[static_cast<size_t>(axis)]) {
                throw std::runtime_error("flatten data block shape does not match layout");
            }
        }
        auto info = block.request();
        const cdouble* ptr = static_cast<const cdouble*>(info.ptr);
        for (ssize_t idx = 0; idx < n; ++idx) {
            out_view(pos + idx) = ptr[idx];
        }
        pos += n;
    }
    return out;
}

static double abelian_block_data_norm_cpp(py::object data_obj) {
    py::dict data = py::reinterpret_borrow<py::dict>(data_obj);
    long double total = 0.0L;
    for (auto item : data) {
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> block =
            py::array_t<cdouble, py::array::c_style | py::array::forcecast>::ensure(item.second);
        if (!block) {
            throw std::runtime_error("norm data block is not array-like");
        }
        auto info = block.request();
        const cdouble* ptr = static_cast<const cdouble*>(info.ptr);
        const ssize_t n = static_cast<ssize_t>(info.size);
        for (ssize_t idx = 0; idx < n; ++idx) {
            total += static_cast<long double>(std::norm(ptr[idx]));
        }
    }
    return std::sqrt(static_cast<double>(total));
}

static py::dict abelian_scale_block_data_cpp(py::object data_obj, cdouble scalar) {
    py::dict data = py::reinterpret_borrow<py::dict>(data_obj);
    py::dict out;
    for (auto item : data) {
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> block =
            py::array_t<cdouble, py::array::c_style | py::array::forcecast>::ensure(item.second);
        if (!block) {
            throw std::runtime_error("scale data block is not array-like");
        }
        auto info = block.request();
        std::vector<ssize_t> shape;
        shape.reserve(static_cast<size_t>(block.ndim()));
        for (ssize_t axis = 0; axis < block.ndim(); ++axis) {
            shape.push_back(block.shape(axis));
        }
        py::array_t<cdouble> scaled(shape);
        auto out_info = scaled.request();
        const cdouble* in_ptr = static_cast<const cdouble*>(info.ptr);
        cdouble* out_ptr = static_cast<cdouble*>(out_info.ptr);
        const ssize_t n = static_cast<ssize_t>(info.size);
        for (ssize_t idx = 0; idx < n; ++idx) {
            out_ptr[idx] = scalar * in_ptr[idx];
        }
        out[item.first] = scaled;
    }
    return out;
}

static py::tuple abelian_merge_normalize_adjacent_site_tensors_data_cpp(
    py::object left_obj,
    py::object right_obj
) {
    py::tuple merged = abelian_merge_adjacent_site_tensors_data_cpp(left_obj, right_obj);
    py::dict data = py::reinterpret_borrow<py::dict>(merged[0]);
    py::dict stats = py::reinterpret_borrow<py::dict>(merged[1]);
    const double norm = abelian_block_data_norm_cpp(data);
    ssize_t scaled_blocks = 0;
    if (norm > 0.0) {
        const cdouble scale = cdouble(1.0 / norm, 0.0);
        for (auto item : data) {
            py::array_t<cdouble, py::array::c_style | py::array::forcecast> block =
                py::array_t<cdouble, py::array::c_style | py::array::forcecast>::ensure(item.second);
            if (!block) {
                throw std::runtime_error("normalized merge data block is not array-like");
            }
            auto info = block.request();
            cdouble* ptr = static_cast<cdouble*>(info.ptr);
            const ssize_t n = static_cast<ssize_t>(info.size);
            for (ssize_t idx = 0; idx < n; ++idx) {
                ptr[idx] *= scale;
            }
            ++scaled_blocks;
        }
    }
    stats[py::str("norm")] = py::float_(norm);
    stats[py::str("normalized")] = py::bool_(norm > 0.0);
    stats[py::str("scaled_blocks")] = py::int_(scaled_blocks);
    return py::make_tuple(data, py::float_(norm), stats);
}

static py::tuple abelian_merge_normalize_flatten_adjacent_site_tensors_data_cpp(
    py::object left_obj,
    py::object right_obj
) {
    py::tuple merged = abelian_merge_normalize_adjacent_site_tensors_data_cpp(
        left_obj,
        right_obj
    );
    py::dict data = py::reinterpret_borrow<py::dict>(merged[0]);
    const double norm = py::cast<double>(merged[1]);
    py::dict stats = py::reinterpret_borrow<py::dict>(merged[2]);

    py::list layout_items;
    std::vector<py::array_t<cdouble, py::array::c_style | py::array::forcecast>> blocks;
    blocks.reserve(static_cast<size_t>(py::len(data)));
    ssize_t total = 0;
    for (auto item : data) {
        py::object key = py::reinterpret_borrow<py::object>(item.first);
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> block =
            py::array_t<cdouble, py::array::c_style | py::array::forcecast>::ensure(item.second);
        if (!block) {
            throw std::runtime_error("normalized merge flatten data block is not array-like");
        }
        py::tuple shape(static_cast<size_t>(block.ndim()));
        ssize_t n = 1;
        for (ssize_t axis = 0; axis < block.ndim(); ++axis) {
            const ssize_t dim = block.shape(axis);
            shape[axis] = py::int_(dim);
            n *= dim;
        }
        total += n;
        layout_items.append(py::make_tuple(key, shape));
        blocks.push_back(block);
    }

    py::array_t<cdouble> flat({total});
    auto flat_view = flat.mutable_unchecked<1>();
    ssize_t pos = 0;
    for (auto& block : blocks) {
        auto info = block.request();
        const cdouble* ptr = static_cast<const cdouble*>(info.ptr);
        const ssize_t n = static_cast<ssize_t>(info.size);
        for (ssize_t idx = 0; idx < n; ++idx) {
            flat_view(pos + idx) = ptr[idx];
        }
        pos += n;
    }

    stats[py::str("flat_dim")] = py::int_(total);
    stats[py::str("layout_blocks")] = py::int_(blocks.size());
    return py::make_tuple(
        data,
        py::float_(norm),
        tuple_from_sequence_object(layout_items),
        flat,
        stats
    );
}

static std::vector<cdouble> matvec_sparse_blocks(
    const std::vector<SparseBlock>& blocks,
    const std::vector<cdouble>& x,
    ssize_t dim
) {
    std::vector<cdouble> out(static_cast<size_t>(dim), cdouble(0.0, 0.0));
    for (const auto& block : blocks) {
        for (ssize_t i = 0; i < block.nnz; ++i) {
            const ssize_t row = static_cast<ssize_t>(block.rows[i]);
            const ssize_t col = static_cast<ssize_t>(block.cols[i]);
            out[static_cast<size_t>(block.out_start + row)] +=
                block.values[i] * x[static_cast<size_t>(block.in_start + col)];
        }
    }
    return out;
}

py::array_t<cdouble> block_table_matvec(
    py::sequence py_blocks,
    py::array_t<long long, py::array::c_style | py::array::forcecast> py_in_starts,
    py::array_t<long long, py::array::c_style | py::array::forcecast> py_out_starts,
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_vec,
    ssize_t dim_arg
) {
    auto in_starts = py_in_starts.unchecked<1>();
    auto out_starts = py_out_starts.unchecked<1>();
    auto vec_arr = py_vec.unchecked<1>();
    const ssize_t vec_dim = vec_arr.shape(0);
    const ssize_t dim = dim_arg > 0 ? dim_arg : vec_dim;
    if (vec_dim != dim) {
        throw std::runtime_error("vector dimension does not match requested output dimension");
    }
    const ssize_t n_blocks = static_cast<ssize_t>(py::len(py_blocks));
    if (in_starts.shape(0) != n_blocks || out_starts.shape(0) != n_blocks) {
        throw std::runtime_error("block start arrays do not match block count");
    }
    std::vector<py::array_t<cdouble, py::array::c_style | py::array::forcecast>> owned_blocks;
    owned_blocks.reserve(static_cast<size_t>(n_blocks));
    std::vector<Block> blocks;
    blocks.reserve(static_cast<size_t>(n_blocks));
    for (ssize_t b = 0; b < n_blocks; ++b) {
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> arr =
            py::cast<py::array_t<cdouble, py::array::c_style | py::array::forcecast>>(py_blocks[b]);
        if (arr.ndim() != 2) {
            throw std::runtime_error("each block matrix must be rank-2");
        }
        auto info = arr.request();
        Block block;
        block.data = static_cast<const cdouble*>(info.ptr);
        block.rows = static_cast<ssize_t>(info.shape[0]);
        block.cols = static_cast<ssize_t>(info.shape[1]);
        block.row_stride = static_cast<ssize_t>(info.strides[0] / sizeof(cdouble));
        block.col_stride = static_cast<ssize_t>(info.strides[1] / sizeof(cdouble));
        block.in_start = static_cast<ssize_t>(in_starts(b));
        block.out_start = static_cast<ssize_t>(out_starts(b));
        if (block.in_start < 0 || block.out_start < 0 ||
            block.in_start + block.cols > dim || block.out_start + block.rows > dim) {
            throw std::runtime_error("block matrix outside matvec vector dimension");
        }
        owned_blocks.push_back(arr);
        blocks.push_back(block);
    }
    std::vector<cdouble> vec(static_cast<size_t>(dim));
    for (ssize_t i = 0; i < dim; ++i) {
        vec[static_cast<size_t>(i)] = vec_arr(i);
    }
    std::vector<cdouble> out = matvec_blocks(blocks, vec, dim);
    py::array_t<cdouble> py_out(dim);
    auto out_mut = py_out.mutable_unchecked<1>();
    for (ssize_t i = 0; i < dim; ++i) {
        out_mut(i) = out[static_cast<size_t>(i)];
    }
    return py_out;
}

py::array_t<cdouble> direct_left_stack(
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_e,
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_w1
) {
    if (py_e.ndim() != 3 || py_w1.ndim() != 4) {
        throw std::runtime_error("direct_left_stack expects rank-3 E and rank-4 W1");
    }
    auto e = py_e.unchecked<3>();
    auto w1 = py_w1.unchecked<4>();
    const ssize_t na = e.shape(0);
    const ssize_t ni = e.shape(1);
    const ssize_t nj = e.shape(2);
    if (w1.shape(0) != na) {
        throw std::runtime_error("direct_left_stack auxiliary dimensions differ");
    }
    const ssize_t nb = w1.shape(1);
    const ssize_t nu = w1.shape(2);
    const ssize_t nx = w1.shape(3);
    py::array_t<cdouble> out({nb, ni * nu, nj * nx});
    auto stack = out.mutable_unchecked<3>();
    for (ssize_t b = 0; b < nb; ++b) {
        for (ssize_t row = 0; row < ni * nu; ++row) {
            for (ssize_t col = 0; col < nj * nx; ++col) {
                stack(b, row, col) = cdouble(0.0, 0.0);
            }
        }
        }
    for (ssize_t a = 0; a < na; ++a) {
        for (ssize_t b = 0; b < nb; ++b) {
            for (ssize_t i = 0; i < ni; ++i) {
                for (ssize_t u = 0; u < nu; ++u) {
                    const ssize_t row = i * nu + u;
                    for (ssize_t j = 0; j < nj; ++j) {
                        const cdouble ev = e(a, i, j);
                        if (std::abs(ev) <= 0.0) {
                            continue;
                        }
                        for (ssize_t x = 0; x < nx; ++x) {
                            stack(b, row, j * nx + x) += ev * w1(a, b, u, x);
                        }
                    }
                }
            }
        }
    }
    return out;
}

static void direct_left_stack_into(
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_e,
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_w1,
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_out
) {
    if (py_e.ndim() != 3 || py_w1.ndim() != 4 || py_out.ndim() != 3) {
        throw std::runtime_error("direct_left_stack_into expects rank-3 E/out and rank-4 W1");
    }
    auto e = py_e.unchecked<3>();
    auto w1 = py_w1.unchecked<4>();
    auto stack = py_out.mutable_unchecked<3>();
    const ssize_t na = e.shape(0);
    const ssize_t ni = e.shape(1);
    const ssize_t nj = e.shape(2);
    if (w1.shape(0) != na) {
        throw std::runtime_error("direct_left_stack_into auxiliary dimensions differ");
    }
    const ssize_t nb = w1.shape(1);
    const ssize_t nu = w1.shape(2);
    const ssize_t nx = w1.shape(3);
    if (
        stack.shape(0) != nb
        || stack.shape(1) != ni * nu
        || stack.shape(2) != nj * nx
    ) {
        throw std::runtime_error("direct_left_stack_into output shape does not match input blocks");
    }
    for (ssize_t b = 0; b < nb; ++b) {
        for (ssize_t row = 0; row < ni * nu; ++row) {
            for (ssize_t col = 0; col < nj * nx; ++col) {
                stack(b, row, col) = cdouble(0.0, 0.0);
            }
        }
    }
    for (ssize_t a = 0; a < na; ++a) {
        for (ssize_t b = 0; b < nb; ++b) {
            for (ssize_t i = 0; i < ni; ++i) {
                for (ssize_t u = 0; u < nu; ++u) {
                    const ssize_t row = i * nu + u;
                    for (ssize_t j = 0; j < nj; ++j) {
                        const cdouble ev = e(a, i, j);
                        if (std::abs(ev) <= 0.0) {
                            continue;
                        }
                        for (ssize_t x = 0; x < nx; ++x) {
                            stack(b, row, j * nx + x) += ev * w1(a, b, u, x);
                        }
                    }
                }
            }
        }
    }
}

py::array_t<cdouble> direct_right_stack(
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_w2,
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_f
) {
    if (py_w2.ndim() != 4 || py_f.ndim() != 3) {
        throw std::runtime_error("direct_right_stack expects rank-4 W2 and rank-3 F");
    }
    auto w2 = py_w2.unchecked<4>();
    auto f = py_f.unchecked<3>();
    const ssize_t nb = w2.shape(0);
    const ssize_t nc = w2.shape(1);
    const ssize_t nv = w2.shape(2);
    const ssize_t ny = w2.shape(3);
    if (f.shape(0) != nc) {
        throw std::runtime_error("direct_right_stack auxiliary dimensions differ");
    }
    const ssize_t nl = f.shape(1);
    const ssize_t nk = f.shape(2);
    py::array_t<cdouble> out({nb, nk * ny, nl * nv});
    auto stack = out.mutable_unchecked<3>();
    for (ssize_t b = 0; b < nb; ++b) {
        for (ssize_t row = 0; row < nk * ny; ++row) {
            for (ssize_t col = 0; col < nl * nv; ++col) {
                stack(b, row, col) = cdouble(0.0, 0.0);
            }
        }
    }
    for (ssize_t b = 0; b < nb; ++b) {
        for (ssize_t c = 0; c < nc; ++c) {
            for (ssize_t k = 0; k < nk; ++k) {
                for (ssize_t y = 0; y < ny; ++y) {
                    const ssize_t row = k * ny + y;
                    for (ssize_t l = 0; l < nl; ++l) {
                        const cdouble fv = f(c, l, k);
                        if (std::abs(fv) <= 0.0) {
                            continue;
                        }
                        for (ssize_t v = 0; v < nv; ++v) {
                            stack(b, row, l * nv + v) += w2(b, c, v, y) * fv;
                        }
                    }
                }
            }
        }
    }
    return out;
}

py::array_t<cdouble> identity_channel_left_stack(
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_e,
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_w1
) {
    if (py_e.ndim() != 3 || py_w1.ndim() != 4) {
        throw std::runtime_error("identity channel left stack expects rank-3 E and rank-4 W1");
    }
    auto e = py_e.unchecked<3>();
    auto w1 = py_w1.unchecked<4>();
    const ssize_t na = e.shape(0);
    const ssize_t ni = e.shape(1);
    const ssize_t nj = e.shape(2);
    if (w1.shape(0) != na) {
        throw std::runtime_error("identity channel left stack auxiliary dimensions differ");
    }
    const ssize_t nb = w1.shape(1);
    const ssize_t nu = w1.shape(2);
    const ssize_t nx = w1.shape(3);
    if (nu != nx) {
        return direct_left_stack(py_e, py_w1);
    }
    if (na == 1 && nb == 1 && nu == 1 && nx == 1) {
        const cdouble wv = w1(0, 0, 0, 0);
        if (wv == cdouble(1.0, 0.0)) {
            return py_e;
        }
        py::array_t<cdouble> out({ssize_t(1), ni, nj});
        auto stack = out.mutable_unchecked<3>();
        for (ssize_t i = 0; i < ni; ++i) {
            for (ssize_t j = 0; j < nj; ++j) {
                stack(0, i, j) = e(0, i, j) * wv;
            }
        }
        return out;
    }
    py::array_t<cdouble> out({nb, ni * nu, nj * nx});
    auto stack = out.mutable_unchecked<3>();
    for (ssize_t b = 0; b < nb; ++b) {
        for (ssize_t row = 0; row < ni * nu; ++row) {
            for (ssize_t col = 0; col < nj * nx; ++col) {
                stack(b, row, col) = cdouble(0.0, 0.0);
            }
        }
    }
    for (ssize_t a = 0; a < na; ++a) {
        for (ssize_t b = 0; b < nb; ++b) {
            for (ssize_t x = 0; x < nx; ++x) {
                const cdouble wv = w1(a, b, x, x);
                if (std::abs(wv) <= 0.0) {
                    continue;
                }
                for (ssize_t i = 0; i < ni; ++i) {
                    for (ssize_t j = 0; j < nj; ++j) {
                        const cdouble ev = e(a, i, j);
                        if (std::abs(ev) <= 0.0) {
                            continue;
                        }
                        stack(b, i * nx + x, j * nx + x) += ev * wv;
                    }
                }
            }
        }
    }
    return out;
}

py::array_t<cdouble> identity_channel_right_stack(
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_w2,
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_f
) {
    if (py_w2.ndim() != 4 || py_f.ndim() != 3) {
        throw std::runtime_error("identity channel right stack expects rank-4 W2 and rank-3 F");
    }
    auto w2 = py_w2.unchecked<4>();
    auto f = py_f.unchecked<3>();
    const ssize_t nb = w2.shape(0);
    const ssize_t nc = w2.shape(1);
    const ssize_t nv = w2.shape(2);
    const ssize_t ny = w2.shape(3);
    if (f.shape(0) != nc) {
        throw std::runtime_error("identity channel right stack auxiliary dimensions differ");
    }
    const ssize_t nl = f.shape(1);
    const ssize_t nk = f.shape(2);
    if (nv != ny) {
        return direct_right_stack(py_w2, py_f);
    }
    if (nb == 1 && nc == 1 && nv == 1 && ny == 1) {
        const cdouble wv = w2(0, 0, 0, 0);
        py::array_t<cdouble> out({ssize_t(1), nk, nl});
        auto stack = out.mutable_unchecked<3>();
        for (ssize_t k = 0; k < nk; ++k) {
            for (ssize_t l = 0; l < nl; ++l) {
                stack(0, k, l) = wv * f(0, l, k);
            }
        }
        return out;
    }
    py::array_t<cdouble> out({nb, nk * ny, nl * nv});
    auto stack = out.mutable_unchecked<3>();
    for (ssize_t b = 0; b < nb; ++b) {
        for (ssize_t row = 0; row < nk * ny; ++row) {
            for (ssize_t col = 0; col < nl * nv; ++col) {
                stack(b, row, col) = cdouble(0.0, 0.0);
            }
        }
    }
    for (ssize_t b = 0; b < nb; ++b) {
        for (ssize_t c = 0; c < nc; ++c) {
            for (ssize_t y = 0; y < ny; ++y) {
                const cdouble wv = w2(b, c, y, y);
                if (std::abs(wv) <= 0.0) {
                    continue;
                }
                for (ssize_t k = 0; k < nk; ++k) {
                    for (ssize_t l = 0; l < nl; ++l) {
                        const cdouble fv = f(c, l, k);
                        if (std::abs(fv) <= 0.0) {
                            continue;
                        }
                        stack(b, k * ny + y, l * ny + y) += wv * fv;
                    }
                }
            }
        }
    }
    return out;
}

static void direct_right_stack_into(
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_w2,
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_f,
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_out
) {
    if (py_w2.ndim() != 4 || py_f.ndim() != 3 || py_out.ndim() != 3) {
        throw std::runtime_error("direct_right_stack_into expects rank-4 W2 and rank-3 F/out");
    }
    auto w2 = py_w2.unchecked<4>();
    auto f = py_f.unchecked<3>();
    auto stack = py_out.mutable_unchecked<3>();
    const ssize_t nb = w2.shape(0);
    const ssize_t nc = w2.shape(1);
    const ssize_t nv = w2.shape(2);
    const ssize_t ny = w2.shape(3);
    if (f.shape(0) != nc) {
        throw std::runtime_error("direct_right_stack_into auxiliary dimensions differ");
    }
    const ssize_t nl = f.shape(1);
    const ssize_t nk = f.shape(2);
    if (
        stack.shape(0) != nb
        || stack.shape(1) != nk * ny
        || stack.shape(2) != nl * nv
    ) {
        throw std::runtime_error("direct_right_stack_into output shape does not match input blocks");
    }
    for (ssize_t b = 0; b < nb; ++b) {
        for (ssize_t row = 0; row < nk * ny; ++row) {
            for (ssize_t col = 0; col < nl * nv; ++col) {
                stack(b, row, col) = cdouble(0.0, 0.0);
            }
        }
    }
    for (ssize_t b = 0; b < nb; ++b) {
        for (ssize_t c = 0; c < nc; ++c) {
            for (ssize_t k = 0; k < nk; ++k) {
                for (ssize_t y = 0; y < ny; ++y) {
                    const ssize_t row = k * ny + y;
                    for (ssize_t l = 0; l < nl; ++l) {
                        const cdouble fv = f(c, l, k);
                        if (std::abs(fv) <= 0.0) {
                            continue;
                        }
                        for (ssize_t v = 0; v < nv; ++v) {
                            stack(b, row, l * nv + v) += w2(b, c, v, y) * fv;
                        }
                    }
                }
            }
        }
    }
}

static std::vector<double> hermitian_to_real_symmetric(
    const std::vector<cdouble>& H,
    ssize_t n
) {
    const ssize_t n2 = 2 * n;
    std::vector<double> A(static_cast<size_t>(n2 * n2), 0.0);
    auto at = [&](ssize_t r, ssize_t c) -> double& {
        return A[static_cast<size_t>(r * n2 + c)];
    };
    for (ssize_t i = 0; i < n; ++i) {
        for (ssize_t j = 0; j < n; ++j) {
            const cdouble z = H[static_cast<size_t>(i * n + j)];
            at(i, j) = z.real();
            at(i, j + n) = -z.imag();
            at(i + n, j) = z.imag();
            at(i + n, j + n) = z.real();
        }
    }
    return A;
}

static std::pair<double, std::vector<double>> lowest_eigen_jacobi(
    std::vector<double> A,
    ssize_t n
) {
    std::vector<double> V(static_cast<size_t>(n * n), 0.0);
    for (ssize_t i = 0; i < n; ++i) {
        V[static_cast<size_t>(i * n + i)] = 1.0;
    }
    auto at = [&](ssize_t r, ssize_t c) -> double& {
        return A[static_cast<size_t>(r * n + c)];
    };
    auto vt = [&](ssize_t r, ssize_t c) -> double& {
        return V[static_cast<size_t>(r * n + c)];
    };
    const ssize_t max_sweeps = std::max<ssize_t>(32, 4 * n * n);
    for (ssize_t sweep = 0; sweep < max_sweeps; ++sweep) {
        ssize_t p = 0;
        ssize_t q = 1;
        double max_off = 0.0;
        for (ssize_t i = 0; i < n; ++i) {
            for (ssize_t j = i + 1; j < n; ++j) {
                const double v = std::abs(at(i, j));
                if (v > max_off) {
                    max_off = v;
                    p = i;
                    q = j;
                }
            }
        }
        if (max_off < 1.0e-12) {
            break;
        }
        const double app = at(p, p);
        const double aqq = at(q, q);
        const double apq = at(p, q);
        const double tau = (aqq - app) / (2.0 * apq);
        const double t = (tau >= 0.0 ? 1.0 : -1.0) /
                         (std::abs(tau) + std::sqrt(1.0 + tau * tau));
        const double c = 1.0 / std::sqrt(1.0 + t * t);
        const double s = t * c;
        for (ssize_t k = 0; k < n; ++k) {
            if (k == p || k == q) {
                continue;
            }
            const double aik = at(k, p);
            const double akq = at(k, q);
            at(k, p) = c * aik - s * akq;
            at(p, k) = at(k, p);
            at(k, q) = s * aik + c * akq;
            at(q, k) = at(k, q);
        }
        at(p, p) = c * c * app - 2.0 * s * c * apq + s * s * aqq;
        at(q, q) = s * s * app + 2.0 * s * c * apq + c * c * aqq;
        at(p, q) = 0.0;
        at(q, p) = 0.0;
        for (ssize_t k = 0; k < n; ++k) {
            const double vip = vt(k, p);
            const double viq = vt(k, q);
            vt(k, p) = c * vip - s * viq;
            vt(k, q) = s * vip + c * viq;
        }
    }
    ssize_t idx = 0;
    double eval = at(0, 0);
    for (ssize_t i = 1; i < n; ++i) {
        if (at(i, i) < eval) {
            eval = at(i, i);
            idx = i;
        }
    }
    std::vector<double> evec(static_cast<size_t>(n), 0.0);
    for (ssize_t i = 0; i < n; ++i) {
        evec[static_cast<size_t>(i)] = vt(i, idx);
    }
    return {eval, evec};
}

struct DavidsonWorkspace {
    std::vector<std::vector<cdouble>> V;
    std::vector<std::vector<cdouble>> HV;
    std::vector<cdouble> T;
    std::vector<cdouble> T_dense;
    std::vector<cdouble> coeff;
    std::vector<cdouble> ritz;
    std::vector<cdouble> hritz;
    std::vector<cdouble> resid;
    std::vector<cdouble> q;
    std::vector<cdouble> best_vec;
    ssize_t dim = 0;
    ssize_t max_basis = 0;
    bool initialized = false;

    void ensure(ssize_t dim_arg, ssize_t max_basis_arg) {
        if (dim_arg <= 0 || max_basis_arg <= 0) {
            throw std::runtime_error("DavidsonWorkspace dimensions must be positive");
        }
        const bool reuse = initialized && dim == dim_arg && max_basis >= max_basis_arg;
        if (!reuse) {
            dim = dim_arg;
            max_basis = max_basis_arg;
            V.resize(static_cast<size_t>(max_basis));
            HV.resize(static_cast<size_t>(max_basis));
            for (ssize_t i = 0; i < max_basis; ++i) {
                V[static_cast<size_t>(i)].resize(static_cast<size_t>(dim));
                HV[static_cast<size_t>(i)].resize(static_cast<size_t>(dim));
            }
            T.resize(static_cast<size_t>(max_basis * max_basis));
            T_dense.resize(static_cast<size_t>(max_basis * max_basis));
            coeff.resize(static_cast<size_t>(max_basis));
            ritz.resize(static_cast<size_t>(dim));
            hritz.resize(static_cast<size_t>(dim));
            resid.resize(static_cast<size_t>(dim));
            q.resize(static_cast<size_t>(dim));
            best_vec.resize(static_cast<size_t>(dim));
            initialized = true;
        }
    }
};

static py::dict davidson_core_workspace(
    ssize_t dim,
    const std::vector<cdouble>& diag,
    std::vector<cdouble> v,
    double tol,
    int max_iter,
    int restart_dim,
    bool accept_unconverged,
    DavidsonWorkspace& workspace,
    const std::function<std::vector<cdouble>(const std::vector<cdouble>&)>& matvec
) {
    double vn = norm2(v);
    if (vn < 1.0e-14) {
        throw std::runtime_error("initial Davidson vector has near-zero norm");
    }
    for (auto& x : v) {
        x /= vn;
    }

    const ssize_t requested_basis = static_cast<ssize_t>(
        restart_dim > 0 ? restart_dim : std::max(1, max_iter)
    );
    workspace.ensure(dim, std::max<ssize_t>(1, requested_basis));
    std::fill(workspace.T.begin(), workspace.T.end(), cdouble(0.0, 0.0));
    std::fill(workspace.best_vec.begin(), workspace.best_vec.end(), cdouble(0.0, 0.0));
    workspace.V[0] = std::move(v);
    ssize_t basis_size = 1;
    double best_energy = 0.0;
    double best_resid = std::numeric_limits<double>::infinity();
    bool converged = false;
    int restarts = 0;
    int iterations = 0;

    for (int it = 0; it < max_iter; ++it) {
        iterations = it + 1;
        const ssize_t newest = basis_size - 1;
        workspace.HV[static_cast<size_t>(newest)] =
            matvec(workspace.V[static_cast<size_t>(newest)]);
        const ssize_t m = basis_size;
        for (ssize_t i = 0; i < m; ++i) {
            cdouble el = dotc(
                workspace.V[static_cast<size_t>(i)],
                workspace.HV[static_cast<size_t>(newest)]
            );
            workspace.T[static_cast<size_t>(i * workspace.max_basis + newest)] = el;
            workspace.T[static_cast<size_t>(newest * workspace.max_basis + i)] =
                std::conj(el);
        }

        double imag_max = 0.0;
        for (ssize_t i = 0; i < m; ++i) {
            for (ssize_t j = 0; j < m; ++j) {
                const cdouble z =
                    workspace.T[static_cast<size_t>(i * workspace.max_basis + j)];
                workspace.T_dense[static_cast<size_t>(i * m + j)] = z;
                imag_max = std::max(imag_max, std::abs(z.imag()));
            }
        }
        if (imag_max < 1.0e-12) {
            std::vector<double> T_real(static_cast<size_t>(m * m), 0.0);
            for (ssize_t i = 0; i < m * m; ++i) {
                T_real[static_cast<size_t>(i)] =
                    workspace.T_dense[static_cast<size_t>(i)].real();
            }
            auto eig = lowest_eigen_jacobi(std::move(T_real), m);
            best_energy = eig.first;
            for (ssize_t i = 0; i < m; ++i) {
                workspace.coeff[static_cast<size_t>(i)] = cdouble(
                    eig.second[static_cast<size_t>(i)],
                    0.0
                );
            }
        } else {
            auto real_T = hermitian_to_real_symmetric(workspace.T_dense, m);
            auto eig = lowest_eigen_jacobi(std::move(real_T), 2 * m);
            best_energy = eig.first;
            for (ssize_t i = 0; i < m; ++i) {
                workspace.coeff[static_cast<size_t>(i)] = cdouble(
                    eig.second[static_cast<size_t>(i)],
                    eig.second[static_cast<size_t>(i + m)]
                );
            }
        }
        double cn = 0.0;
        for (ssize_t i = 0; i < m; ++i) {
            cn += std::norm(workspace.coeff[static_cast<size_t>(i)]);
        }
        cn = std::sqrt(cn);
        if (cn < 1.0e-14) {
            for (ssize_t i = 0; i < m; ++i) {
                workspace.coeff[static_cast<size_t>(i)] = cdouble(0.0, 0.0);
            }
            workspace.coeff[0] = 1.0;
        } else {
            for (ssize_t i = 0; i < m; ++i) {
                workspace.coeff[static_cast<size_t>(i)] /= cn;
            }
        }
        std::fill(workspace.ritz.begin(), workspace.ritz.end(), cdouble(0.0, 0.0));
        std::fill(workspace.hritz.begin(), workspace.hritz.end(), cdouble(0.0, 0.0));
        for (ssize_t i = 0; i < m; ++i) {
            axpy(
                workspace.ritz,
                workspace.coeff[static_cast<size_t>(i)],
                workspace.V[static_cast<size_t>(i)]
            );
            axpy(
                workspace.hritz,
                workspace.coeff[static_cast<size_t>(i)],
                workspace.HV[static_cast<size_t>(i)]
            );
        }
        workspace.resid = workspace.hritz;
        for (ssize_t i = 0; i < dim; ++i) {
            workspace.resid[static_cast<size_t>(i)] -=
                best_energy * workspace.ritz[static_cast<size_t>(i)];
        }
        best_resid = norm2(workspace.resid);
        workspace.best_vec = workspace.ritz;
        if (best_resid < tol) {
            converged = true;
            break;
        }
        if (restart_dim > 0 && static_cast<int>(basis_size) >= restart_dim) {
            double rn = norm2(workspace.ritz);
            if (rn < 1.0e-14) {
                break;
            }
            for (auto& x : workspace.ritz) {
                x /= rn;
            }
            workspace.V[0] = workspace.ritz;
            std::fill(workspace.T.begin(), workspace.T.end(), cdouble(0.0, 0.0));
            basis_size = 1;
            ++restarts;
            continue;
        }
        for (ssize_t i = 0; i < dim; ++i) {
            cdouble denom = best_energy - diag[static_cast<size_t>(i)];
            if (std::abs(denom) < 1.0e-8) {
                denom = cdouble(
                    (denom.real() >= 0.0 ? 1.0e-8 : -1.0e-8),
                    denom.imag()
                );
            }
            workspace.q[static_cast<size_t>(i)] =
                workspace.resid[static_cast<size_t>(i)] / denom;
        }
        for (int pass = 0; pass < 2; ++pass) {
            for (ssize_t ibasis = 0; ibasis < basis_size; ++ibasis) {
                const auto& basis = workspace.V[static_cast<size_t>(ibasis)];
                cdouble overlap = dotc(basis, workspace.q);
                for (ssize_t i = 0; i < dim; ++i) {
                    workspace.q[static_cast<size_t>(i)] -=
                        basis[static_cast<size_t>(i)] * overlap;
                }
            }
        }
        double qn = norm2(workspace.q);
        if (qn < 1.0e-10) {
            break;
        }
        for (auto& x : workspace.q) {
            x /= qn;
        }
        if (basis_size >= workspace.max_basis) {
            break;
        }
        workspace.V[static_cast<size_t>(basis_size)] = workspace.q;
        ++basis_size;
    }

    if (!converged && !accept_unconverged) {
        py::dict out;
        out["accepted"] = false;
        out["energy"] = best_energy;
        out["residual_norm"] = best_resid;
        out["iterations"] = iterations;
        out["basis_size"] = static_cast<int>(basis_size);
        out["restarts"] = restarts;
        out["converged"] = false;
        return out;
    }

    py::array_t<cdouble> py_vec(dim);
    auto vec_mut = py_vec.mutable_unchecked<1>();
    for (ssize_t i = 0; i < dim; ++i) {
        vec_mut(i) = workspace.best_vec[static_cast<size_t>(i)];
    }
    py::dict out;
    out["accepted"] = true;
    out["energy"] = best_energy;
    out["vector"] = py_vec;
    out["residual_norm"] = best_resid;
    out["iterations"] = iterations;
    out["basis_size"] = static_cast<int>(basis_size);
    out["restarts"] = restarts;
    out["converged"] = converged;
    return out;
}

static py::dict davidson_core(
    ssize_t dim,
    const std::vector<cdouble>& diag,
    std::vector<cdouble> v,
    double tol,
    int max_iter,
    int restart_dim,
    bool accept_unconverged,
    const std::function<std::vector<cdouble>(const std::vector<cdouble>&)>& matvec
) {
    DavidsonWorkspace workspace;
    return davidson_core_workspace(
        dim,
        diag,
        std::move(v),
        tol,
        max_iter,
        restart_dim,
        accept_unconverged,
        workspace,
        matvec
    );
}

py::dict block_table_davidson(
    py::sequence py_blocks,
    py::array_t<long long, py::array::c_style | py::array::forcecast> py_in_starts,
    py::array_t<long long, py::array::c_style | py::array::forcecast> py_out_starts,
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_diag,
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_v0,
    double tol,
    int max_iter,
    int restart_dim,
    bool accept_unconverged
) {
    auto in_starts = py_in_starts.unchecked<1>();
    auto out_starts = py_out_starts.unchecked<1>();
    auto diag_arr = py_diag.unchecked<1>();
    auto v0_arr = py_v0.unchecked<1>();
    const ssize_t dim = v0_arr.shape(0);
    if (diag_arr.shape(0) != dim) {
        throw std::runtime_error("diag and v0 dimensions differ");
    }
    const ssize_t n_blocks = static_cast<ssize_t>(py::len(py_blocks));
    if (in_starts.shape(0) != n_blocks || out_starts.shape(0) != n_blocks) {
        throw std::runtime_error("block start arrays do not match block count");
    }
    std::vector<py::array_t<cdouble, py::array::c_style | py::array::forcecast>> owned_blocks;
    owned_blocks.reserve(static_cast<size_t>(n_blocks));
    std::vector<Block> blocks;
    blocks.reserve(static_cast<size_t>(n_blocks));
    for (ssize_t b = 0; b < n_blocks; ++b) {
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> arr =
            py::cast<py::array_t<cdouble, py::array::c_style | py::array::forcecast>>(py_blocks[b]);
        if (arr.ndim() != 2) {
            throw std::runtime_error("each block matrix must be rank-2");
        }
        auto info = arr.request();
        Block block;
        block.data = static_cast<const cdouble*>(info.ptr);
        block.rows = static_cast<ssize_t>(info.shape[0]);
        block.cols = static_cast<ssize_t>(info.shape[1]);
        block.row_stride = static_cast<ssize_t>(info.strides[0] / sizeof(cdouble));
        block.col_stride = static_cast<ssize_t>(info.strides[1] / sizeof(cdouble));
        block.in_start = static_cast<ssize_t>(in_starts(b));
        block.out_start = static_cast<ssize_t>(out_starts(b));
        if (block.in_start < 0 || block.out_start < 0 ||
            block.in_start + block.cols > dim || block.out_start + block.rows > dim) {
            throw std::runtime_error("block matrix outside Davidson vector dimension");
        }
        owned_blocks.push_back(arr);
        blocks.push_back(block);
    }
    std::vector<cdouble> diag(static_cast<size_t>(dim));
    std::vector<cdouble> v(static_cast<size_t>(dim));
    for (ssize_t i = 0; i < dim; ++i) {
        diag[static_cast<size_t>(i)] = diag_arr(i);
        v[static_cast<size_t>(i)] = v0_arr(i);
    }
    double vn = norm2(v);
    if (vn < 1.0e-14) {
        throw std::runtime_error("initial Davidson vector has near-zero norm");
    }
    for (auto& x : v) {
        x /= vn;
    }

    std::vector<std::vector<cdouble>> V;
    std::vector<std::vector<cdouble>> HV;
    V.push_back(std::move(v));
    std::vector<cdouble> T;
    double best_energy = 0.0;
    double best_resid = std::numeric_limits<double>::infinity();
    std::vector<cdouble> best_vec(static_cast<size_t>(dim), 0.0);
    bool converged = false;
    int restarts = 0;
    int iterations = 0;

    for (int it = 0; it < max_iter; ++it) {
        iterations = it + 1;
        HV.push_back(matvec_blocks(blocks, V.back(), dim));
        const ssize_t m = static_cast<ssize_t>(V.size());
        std::vector<cdouble> T_new(static_cast<size_t>(m * m), 0.0);
        for (ssize_t i = 0; i < m - 1; ++i) {
            for (ssize_t j = 0; j < m - 1; ++j) {
                T_new[static_cast<size_t>(i * m + j)] = T[static_cast<size_t>(i * (m - 1) + j)];
            }
        }
        for (ssize_t i = 0; i < m; ++i) {
            cdouble el = dotc(V[static_cast<size_t>(i)], HV.back());
            T_new[static_cast<size_t>(i * m + (m - 1))] = el;
            T_new[static_cast<size_t>((m - 1) * m + i)] = std::conj(el);
        }
        T.swap(T_new);

        std::vector<cdouble> coeff(static_cast<size_t>(m));
        double imag_max = 0.0;
        for (const auto& z : T) {
            imag_max = std::max(imag_max, std::abs(z.imag()));
        }
        if (imag_max < 1.0e-12) {
            std::vector<double> T_real(static_cast<size_t>(m * m), 0.0);
            for (ssize_t i = 0; i < m * m; ++i) {
                T_real[static_cast<size_t>(i)] = T[static_cast<size_t>(i)].real();
            }
            auto eig = lowest_eigen_jacobi(std::move(T_real), m);
            best_energy = eig.first;
            for (ssize_t i = 0; i < m; ++i) {
                coeff[static_cast<size_t>(i)] = cdouble(
                    eig.second[static_cast<size_t>(i)],
                    0.0
                );
            }
        } else {
            auto real_T = hermitian_to_real_symmetric(T, m);
            auto eig = lowest_eigen_jacobi(std::move(real_T), 2 * m);
            best_energy = eig.first;
            for (ssize_t i = 0; i < m; ++i) {
                coeff[static_cast<size_t>(i)] = cdouble(
                    eig.second[static_cast<size_t>(i)],
                    eig.second[static_cast<size_t>(i + m)]
                );
            }
        }
        double cn = norm2(coeff);
        if (cn < 1.0e-14) {
            coeff.assign(static_cast<size_t>(m), cdouble(0.0, 0.0));
            coeff[0] = 1.0;
        } else {
            for (auto& c : coeff) {
                c /= cn;
            }
        }
        std::vector<cdouble> ritz(static_cast<size_t>(dim), 0.0);
        std::vector<cdouble> hritz(static_cast<size_t>(dim), 0.0);
        for (ssize_t i = 0; i < m; ++i) {
            axpy(ritz, coeff[static_cast<size_t>(i)], V[static_cast<size_t>(i)]);
            axpy(hritz, coeff[static_cast<size_t>(i)], HV[static_cast<size_t>(i)]);
        }
        std::vector<cdouble> resid = hritz;
        for (ssize_t i = 0; i < dim; ++i) {
            resid[static_cast<size_t>(i)] -= best_energy * ritz[static_cast<size_t>(i)];
        }
        best_resid = norm2(resid);
        best_vec = ritz;
        if (best_resid < tol) {
            converged = true;
            break;
        }
        if (restart_dim > 0 && static_cast<int>(V.size()) >= restart_dim) {
            double rn = norm2(ritz);
            if (rn < 1.0e-14) {
                break;
            }
            for (auto& x : ritz) {
                x /= rn;
            }
            V.clear();
            HV.clear();
            T.clear();
            V.push_back(std::move(ritz));
            ++restarts;
            continue;
        }
        std::vector<cdouble> q(static_cast<size_t>(dim));
        for (ssize_t i = 0; i < dim; ++i) {
            cdouble denom = best_energy - diag[static_cast<size_t>(i)];
            if (std::abs(denom) < 1.0e-8) {
                denom = cdouble((denom.real() >= 0.0 ? 1.0e-8 : -1.0e-8), denom.imag());
            }
            q[static_cast<size_t>(i)] = resid[static_cast<size_t>(i)] / denom;
        }
        for (int pass = 0; pass < 2; ++pass) {
            for (const auto& basis : V) {
                cdouble overlap = dotc(basis, q);
                for (ssize_t i = 0; i < dim; ++i) {
                    q[static_cast<size_t>(i)] -= basis[static_cast<size_t>(i)] * overlap;
                }
            }
        }
        double qn = norm2(q);
        if (qn < 1.0e-10) {
            break;
        }
        for (auto& x : q) {
            x /= qn;
        }
        V.push_back(std::move(q));
    }

    if (!converged && !accept_unconverged) {
        py::dict out;
        out["accepted"] = false;
        out["energy"] = best_energy;
        out["residual_norm"] = best_resid;
        out["iterations"] = iterations;
        out["basis_size"] = static_cast<int>(V.size());
        out["restarts"] = restarts;
        out["converged"] = false;
        return out;
    }
    py::array_t<cdouble> py_vec(dim);
    auto vec_mut = py_vec.mutable_unchecked<1>();
    for (ssize_t i = 0; i < dim; ++i) {
        vec_mut(i) = best_vec[static_cast<size_t>(i)];
    }
    py::dict out;
    out["accepted"] = true;
    out["energy"] = best_energy;
    out["vector"] = py_vec;
    out["residual_norm"] = best_resid;
    out["iterations"] = iterations;
    out["basis_size"] = static_cast<int>(V.size());
    out["restarts"] = restarts;
    out["converged"] = converged;
    return out;
}

class CppBlockTable {
public:
    std::vector<py::array_t<cdouble, py::array::c_style | py::array::forcecast>> owned_blocks;
    std::vector<Block> blocks;
    ssize_t dim;

    CppBlockTable(
        py::sequence py_blocks,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_in_starts,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_out_starts,
        ssize_t dim_arg
    ) : dim(dim_arg) {
        if (dim <= 0) {
            throw std::runtime_error("BlockTable dimension must be positive");
        }
        auto in_starts = py_in_starts.unchecked<1>();
        auto out_starts = py_out_starts.unchecked<1>();
        const ssize_t n_blocks = static_cast<ssize_t>(py::len(py_blocks));
        if (in_starts.shape(0) != n_blocks || out_starts.shape(0) != n_blocks) {
            throw std::runtime_error("block start arrays do not match block count");
        }
        owned_blocks.reserve(static_cast<size_t>(n_blocks));
        blocks.reserve(static_cast<size_t>(n_blocks));
        for (ssize_t b = 0; b < n_blocks; ++b) {
            py::array_t<cdouble, py::array::c_style | py::array::forcecast> arr =
                py::cast<py::array_t<cdouble, py::array::c_style | py::array::forcecast>>(py_blocks[b]);
            if (arr.ndim() != 2) {
                throw std::runtime_error("each block matrix must be rank-2");
            }
            auto info = arr.request();
            Block block;
            block.data = static_cast<const cdouble*>(info.ptr);
            block.rows = static_cast<ssize_t>(info.shape[0]);
            block.cols = static_cast<ssize_t>(info.shape[1]);
            block.row_stride = static_cast<ssize_t>(info.strides[0] / sizeof(cdouble));
            block.col_stride = static_cast<ssize_t>(info.strides[1] / sizeof(cdouble));
            block.in_start = static_cast<ssize_t>(in_starts(b));
            block.out_start = static_cast<ssize_t>(out_starts(b));
            if (block.in_start < 0 || block.out_start < 0 ||
                block.in_start + block.cols > dim || block.out_start + block.rows > dim) {
                throw std::runtime_error("block matrix outside vector dimension");
            }
            owned_blocks.push_back(arr);
            blocks.push_back(block);
        }
    }

    py::array_t<cdouble> matvec(
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_vec
    ) const {
        auto vec_arr = py_vec.unchecked<1>();
        if (vec_arr.shape(0) != dim) {
            throw std::runtime_error("vector dimension does not match BlockTable dimension");
        }
        std::vector<cdouble> vec(static_cast<size_t>(dim));
        for (ssize_t i = 0; i < dim; ++i) {
            vec[static_cast<size_t>(i)] = vec_arr(i);
        }
        std::vector<cdouble> out = matvec_blocks(blocks, vec, dim);
        py::array_t<cdouble> py_out(dim);
        auto out_mut = py_out.mutable_unchecked<1>();
        for (ssize_t i = 0; i < dim; ++i) {
            out_mut(i) = out[static_cast<size_t>(i)];
        }
        return py_out;
    }

    py::array_t<cdouble> diagonal() const {
        py::array_t<cdouble> py_diag(dim);
        auto diag_mut = py_diag.mutable_unchecked<1>();
        for (ssize_t i = 0; i < dim; ++i) {
            diag_mut(i) = cdouble(0.0, 0.0);
        }
        for (const auto& block : blocks) {
            const ssize_t first = std::max(block.in_start, block.out_start);
            const ssize_t last = std::min(
                block.in_start + block.cols,
                block.out_start + block.rows
            );
            for (ssize_t global = first; global < last; ++global) {
                const ssize_t row = global - block.out_start;
                const ssize_t col = global - block.in_start;
                diag_mut(global) += block.data[
                    row * block.row_stride + col * block.col_stride
                ];
            }
        }
        return py_diag;
    }

    py::dict davidson(
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_diag,
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_v0,
        double tol,
        int max_iter,
        int restart_dim,
        bool accept_unconverged
    ) const {
        auto diag_arr = py_diag.unchecked<1>();
        auto v0_arr = py_v0.unchecked<1>();
        if (diag_arr.shape(0) != dim || v0_arr.shape(0) != dim) {
            throw std::runtime_error("diag, v0, and BlockTable dimensions differ");
        }
        std::vector<cdouble> diag(static_cast<size_t>(dim));
        std::vector<cdouble> v(static_cast<size_t>(dim));
        for (ssize_t i = 0; i < dim; ++i) {
            diag[static_cast<size_t>(i)] = diag_arr(i);
            v[static_cast<size_t>(i)] = v0_arr(i);
        }
        double vn = norm2(v);
        if (vn < 1.0e-14) {
            throw std::runtime_error("initial Davidson vector has near-zero norm");
        }
        for (auto& x : v) {
            x /= vn;
        }

        std::vector<std::vector<cdouble>> V;
        std::vector<std::vector<cdouble>> HV;
        V.push_back(std::move(v));
        std::vector<cdouble> T;
        double best_energy = 0.0;
        double best_resid = std::numeric_limits<double>::infinity();
        std::vector<cdouble> best_vec(static_cast<size_t>(dim), 0.0);
        bool converged = false;
        int restarts = 0;
        int iterations = 0;

        for (int it = 0; it < max_iter; ++it) {
            iterations = it + 1;
            HV.push_back(matvec_blocks(blocks, V.back(), dim));
            const ssize_t m = static_cast<ssize_t>(V.size());
            std::vector<cdouble> T_new(static_cast<size_t>(m * m), 0.0);
            for (ssize_t i = 0; i < m - 1; ++i) {
                for (ssize_t j = 0; j < m - 1; ++j) {
                    T_new[static_cast<size_t>(i * m + j)] = T[static_cast<size_t>(i * (m - 1) + j)];
                }
            }
            for (ssize_t i = 0; i < m; ++i) {
                cdouble el = dotc(V[static_cast<size_t>(i)], HV.back());
                T_new[static_cast<size_t>(i * m + (m - 1))] = el;
                T_new[static_cast<size_t>((m - 1) * m + i)] = std::conj(el);
            }
            T.swap(T_new);

            std::vector<cdouble> coeff(static_cast<size_t>(m));
            double imag_max = 0.0;
            for (const auto& z : T) {
                imag_max = std::max(imag_max, std::abs(z.imag()));
            }
            if (imag_max < 1.0e-12) {
                std::vector<double> T_real(static_cast<size_t>(m * m), 0.0);
                for (ssize_t i = 0; i < m * m; ++i) {
                    T_real[static_cast<size_t>(i)] = T[static_cast<size_t>(i)].real();
                }
                auto eig = lowest_eigen_jacobi(std::move(T_real), m);
                best_energy = eig.first;
                for (ssize_t i = 0; i < m; ++i) {
                    coeff[static_cast<size_t>(i)] = cdouble(eig.second[static_cast<size_t>(i)], 0.0);
                }
            } else {
                auto real_T = hermitian_to_real_symmetric(T, m);
                auto eig = lowest_eigen_jacobi(std::move(real_T), 2 * m);
                best_energy = eig.first;
                for (ssize_t i = 0; i < m; ++i) {
                    coeff[static_cast<size_t>(i)] = cdouble(
                        eig.second[static_cast<size_t>(i)],
                        eig.second[static_cast<size_t>(i + m)]
                    );
                }
            }
            double cn = norm2(coeff);
            if (cn < 1.0e-14) {
                coeff.assign(static_cast<size_t>(m), cdouble(0.0, 0.0));
                coeff[0] = 1.0;
            } else {
                for (auto& c : coeff) {
                    c /= cn;
                }
            }
            std::vector<cdouble> ritz(static_cast<size_t>(dim), 0.0);
            std::vector<cdouble> hritz(static_cast<size_t>(dim), 0.0);
            for (ssize_t i = 0; i < m; ++i) {
                axpy(ritz, coeff[static_cast<size_t>(i)], V[static_cast<size_t>(i)]);
                axpy(hritz, coeff[static_cast<size_t>(i)], HV[static_cast<size_t>(i)]);
            }
            std::vector<cdouble> resid = hritz;
            for (ssize_t i = 0; i < dim; ++i) {
                resid[static_cast<size_t>(i)] -= best_energy * ritz[static_cast<size_t>(i)];
            }
            best_resid = norm2(resid);
            best_vec = ritz;
            if (best_resid < tol) {
                converged = true;
                break;
            }
            if (restart_dim > 0 && static_cast<int>(V.size()) >= restart_dim) {
                double rn = norm2(ritz);
                if (rn < 1.0e-14) {
                    break;
                }
                for (auto& x : ritz) {
                    x /= rn;
                }
                V.clear();
                HV.clear();
                T.clear();
                V.push_back(std::move(ritz));
                ++restarts;
                continue;
            }
            std::vector<cdouble> q(static_cast<size_t>(dim));
            for (ssize_t i = 0; i < dim; ++i) {
                cdouble denom = best_energy - diag[static_cast<size_t>(i)];
                if (std::abs(denom) < 1.0e-8) {
                    denom = cdouble((denom.real() >= 0.0 ? 1.0e-8 : -1.0e-8), denom.imag());
                }
                q[static_cast<size_t>(i)] = resid[static_cast<size_t>(i)] / denom;
            }
            for (int pass = 0; pass < 2; ++pass) {
                for (const auto& basis : V) {
                    cdouble overlap = dotc(basis, q);
                    for (ssize_t i = 0; i < dim; ++i) {
                        q[static_cast<size_t>(i)] -= basis[static_cast<size_t>(i)] * overlap;
                    }
                }
            }
            double qn = norm2(q);
            if (qn < 1.0e-10) {
                break;
            }
            for (auto& x : q) {
                x /= qn;
            }
            V.push_back(std::move(q));
        }

        if (!converged && !accept_unconverged) {
            py::dict out;
            out["accepted"] = false;
            out["energy"] = best_energy;
            out["residual_norm"] = best_resid;
            out["iterations"] = iterations;
            out["basis_size"] = static_cast<int>(V.size());
            out["restarts"] = restarts;
            out["converged"] = false;
            return out;
        }
        py::array_t<cdouble> py_vec(dim);
        auto vec_mut = py_vec.mutable_unchecked<1>();
        for (ssize_t i = 0; i < dim; ++i) {
            vec_mut(i) = best_vec[static_cast<size_t>(i)];
        }
        py::dict out;
        out["accepted"] = true;
        out["energy"] = best_energy;
        out["vector"] = py_vec;
        out["residual_norm"] = best_resid;
        out["iterations"] = iterations;
        out["basis_size"] = static_cast<int>(V.size());
        out["restarts"] = restarts;
        out["converged"] = converged;
        return out;
    }
};

static std::vector<ssize_t> copy_int_array(
    py::array_t<long long, py::array::c_style | py::array::forcecast> arr
) {
    auto view = arr.unchecked<1>();
    std::vector<ssize_t> out(static_cast<size_t>(view.shape(0)));
    for (ssize_t i = 0; i < view.shape(0); ++i) {
        out[static_cast<size_t>(i)] = static_cast<ssize_t>(view(i));
    }
    return out;
}

struct CompactStageSpec {
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> owned_stack;
    const cdouble* stack = nullptr;
    std::vector<ssize_t> stack_shape;
    ssize_t input_group = 0;
    ssize_t output_group = 0;
    std::vector<ssize_t> input_pos;
    std::vector<ssize_t> output_pos;
    std::vector<ssize_t> shape_info;
};

static void parse_stage_spec_metadata(CompactStageSpec& spec, py::handle spec_obj) {
    py::tuple item = py::cast<py::tuple>(spec_obj);
    if (item.size() < 5) {
        throw std::runtime_error("compact plan spec must have five fields");
    }
    spec.input_group = py::cast<ssize_t>(item[0]);
    spec.input_pos = copy_int_array(
        py::cast<py::array_t<long long, py::array::c_style | py::array::forcecast>>(item[1])
    );
    spec.output_group = py::cast<ssize_t>(item[2]);
    spec.output_pos = copy_int_array(
        py::cast<py::array_t<long long, py::array::c_style | py::array::forcecast>>(item[3])
    );
    spec.shape_info = copy_int_array(
        py::cast<py::array_t<long long, py::array::c_style | py::array::forcecast>>(item[4])
    );
}

static std::vector<CompactStageSpec> parse_stage_specs(
    py::sequence stacks,
    py::sequence specs,
    ssize_t expected_stack_ndim
) {
    const ssize_t n = static_cast<ssize_t>(py::len(specs));
    if (static_cast<ssize_t>(py::len(stacks)) != n) {
        throw std::runtime_error("compact plan stack/spec count mismatch");
    }
    std::vector<CompactStageSpec> out;
    out.reserve(static_cast<size_t>(n));
    for (ssize_t i = 0; i < n; ++i) {
        CompactStageSpec spec;
        spec.owned_stack = py::cast<
            py::array_t<cdouble, py::array::c_style | py::array::forcecast>
        >(stacks[i]);
        if (spec.owned_stack.ndim() != expected_stack_ndim) {
            throw std::runtime_error("compact plan stack rank mismatch");
        }
        auto stack_info = spec.owned_stack.request();
        spec.stack = static_cast<const cdouble*>(stack_info.ptr);
        for (auto dim : stack_info.shape) {
            spec.stack_shape.push_back(static_cast<ssize_t>(dim));
        }

        parse_stage_spec_metadata(spec, specs[i]);
        const ssize_t batch = spec.stack_shape.empty() ? 0 : spec.stack_shape[0];
        if (
            static_cast<ssize_t>(spec.input_pos.size()) != batch ||
            static_cast<ssize_t>(spec.output_pos.size()) != batch
        ) {
            throw std::runtime_error("compact plan spec positions do not match batch size");
        }
        out.push_back(std::move(spec));
    }
    return out;
}

static py::array_t<cdouble> build_stage_stack_from_blocks(
    py::sequence blocks,
    py::array_t<long long, py::array::c_style | py::array::forcecast> entries,
    ssize_t source_column,
    ssize_t expected_block_ndim
) {
    if (entries.ndim() != 2) {
        throw std::runtime_error("compact plan entry group must be rank-2");
    }
    auto entry_view = entries.unchecked<2>();
    const ssize_t batch = entry_view.shape(0);
    if (source_column < 0 || source_column >= entry_view.shape(1)) {
        throw std::runtime_error("compact plan source column is invalid");
    }
    if (batch <= 0) {
        throw std::runtime_error("compact plan entry group is empty");
    }
    const ssize_t first_block_index = static_cast<ssize_t>(entry_view(0, source_column));
    if (first_block_index < 0 || first_block_index >= static_cast<ssize_t>(py::len(blocks))) {
        throw std::runtime_error("compact plan source block index out of range");
    }
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> first_block =
        py::cast<py::array_t<cdouble, py::array::c_style | py::array::forcecast>>(
            blocks[first_block_index]
        );
    if (first_block.ndim() != expected_block_ndim) {
        throw std::runtime_error("compact plan source block rank mismatch");
    }
    auto first_info = first_block.request();
    std::vector<ssize_t> stack_shape;
    stack_shape.reserve(static_cast<size_t>(expected_block_ndim + 1));
    stack_shape.push_back(batch);
    ssize_t block_size = 1;
    for (ssize_t axis = 0; axis < expected_block_ndim; ++axis) {
        const ssize_t dim = static_cast<ssize_t>(first_info.shape[static_cast<size_t>(axis)]);
        stack_shape.push_back(dim);
        block_size *= dim;
    }
    py::array_t<cdouble> stack(stack_shape);
    auto stack_info = stack.request();
    cdouble* stack_ptr = static_cast<cdouble*>(stack_info.ptr);
    for (ssize_t entry = 0; entry < batch; ++entry) {
        const ssize_t block_index = static_cast<ssize_t>(entry_view(entry, source_column));
        if (block_index < 0 || block_index >= static_cast<ssize_t>(py::len(blocks))) {
            throw std::runtime_error("compact plan source block index out of range");
        }
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> block =
            py::cast<py::array_t<cdouble, py::array::c_style | py::array::forcecast>>(
                blocks[block_index]
            );
        if (block.ndim() != expected_block_ndim) {
            throw std::runtime_error("compact plan source block rank changed");
        }
        auto block_info = block.request();
        ssize_t block_elements = 1;
        for (ssize_t axis = 0; axis < expected_block_ndim; ++axis) {
            const ssize_t dim = static_cast<ssize_t>(
                block_info.shape[static_cast<size_t>(axis)]
            );
            if (dim != stack_shape[static_cast<size_t>(axis + 1)]) {
                throw std::runtime_error("compact plan source block shape changed");
            }
            block_elements *= dim;
        }
        if (block_elements != block_size) {
            throw std::runtime_error("compact plan source block size changed");
        }
        const cdouble* src = static_cast<const cdouble*>(block_info.ptr);
        std::copy(src, src + block_size, stack_ptr + entry * block_size);
    }
    return stack;
}

static std::vector<CompactStageSpec> parse_stage_specs_from_blocks(
    py::sequence blocks,
    py::sequence entry_groups,
    py::sequence specs,
    ssize_t source_column,
    ssize_t expected_block_ndim
) {
    const ssize_t n = static_cast<ssize_t>(py::len(specs));
    if (static_cast<ssize_t>(py::len(entry_groups)) != n) {
        throw std::runtime_error("compact plan entry/spec count mismatch");
    }
    std::vector<CompactStageSpec> out;
    out.reserve(static_cast<size_t>(n));
    for (ssize_t i = 0; i < n; ++i) {
        CompactStageSpec spec;
        py::array_t<long long, py::array::c_style | py::array::forcecast> entries =
            py::cast<py::array_t<long long, py::array::c_style | py::array::forcecast>>(
                entry_groups[i]
            );
        spec.owned_stack = build_stage_stack_from_blocks(
            blocks,
            entries,
            source_column,
            expected_block_ndim
        );
        auto stack_info = spec.owned_stack.request();
        spec.stack = static_cast<const cdouble*>(stack_info.ptr);
        for (auto dim : stack_info.shape) {
            spec.stack_shape.push_back(static_cast<ssize_t>(dim));
        }
        parse_stage_spec_metadata(spec, specs[i]);
        const ssize_t batch = spec.stack_shape.empty() ? 0 : spec.stack_shape[0];
        if (
            static_cast<ssize_t>(spec.input_pos.size()) != batch ||
            static_cast<ssize_t>(spec.output_pos.size()) != batch
        ) {
            throw std::runtime_error("compact plan spec positions do not match batch size");
        }
        out.push_back(std::move(spec));
    }
    return out;
}

static void update_stage_stacks(
    std::vector<CompactStageSpec>& specs,
    py::sequence stacks,
    ssize_t expected_stack_ndim
) {
    const ssize_t n = static_cast<ssize_t>(py::len(stacks));
    if (n != static_cast<ssize_t>(specs.size())) {
        throw std::runtime_error("compact plan stack count changed");
    }
    for (ssize_t i = 0; i < n; ++i) {
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> owned_stack =
            py::cast<py::array_t<cdouble, py::array::c_style | py::array::forcecast>>(stacks[i]);
        if (owned_stack.ndim() != expected_stack_ndim) {
            throw std::runtime_error("compact plan refreshed stack rank mismatch");
        }
        auto stack_info = owned_stack.request();
        const CompactStageSpec& old_spec = specs[static_cast<size_t>(i)];
        if (static_cast<ssize_t>(stack_info.shape.size()) != static_cast<ssize_t>(old_spec.stack_shape.size())) {
            throw std::runtime_error("compact plan refreshed stack shape rank changed");
        }
        for (ssize_t axis = 0; axis < static_cast<ssize_t>(old_spec.stack_shape.size()); ++axis) {
            if (static_cast<ssize_t>(stack_info.shape[static_cast<size_t>(axis)]) != old_spec.stack_shape[static_cast<size_t>(axis)]) {
                throw std::runtime_error("compact plan refreshed stack shape changed");
            }
        }
        specs[static_cast<size_t>(i)].owned_stack = owned_stack;
        auto refreshed_info = specs[static_cast<size_t>(i)].owned_stack.request();
        specs[static_cast<size_t>(i)].stack = static_cast<const cdouble*>(refreshed_info.ptr);
    }
}

static void update_stage_stacks_from_blocks(
    std::vector<CompactStageSpec>& specs,
    py::sequence blocks,
    py::sequence entry_groups,
    ssize_t source_column,
    ssize_t expected_block_ndim
) {
    const ssize_t n = static_cast<ssize_t>(py::len(entry_groups));
    if (n != static_cast<ssize_t>(specs.size())) {
        throw std::runtime_error("compact plan entry-group count changed");
    }
    for (ssize_t group_index = 0; group_index < n; ++group_index) {
        CompactStageSpec& spec = specs[static_cast<size_t>(group_index)];
        py::array_t<long long, py::array::c_style | py::array::forcecast> entries =
            py::cast<py::array_t<long long, py::array::c_style | py::array::forcecast>>(
                entry_groups[group_index]
            );
        if (entries.ndim() != 2) {
            throw std::runtime_error("compact plan entry group must be rank-2");
        }
        auto entry_view = entries.unchecked<2>();
        const ssize_t batch = entry_view.shape(0);
        if (source_column < 0 || source_column >= entry_view.shape(1)) {
            throw std::runtime_error("compact plan refresh source column is invalid");
        }
        if (spec.stack_shape.empty() || batch != spec.stack_shape[0]) {
            throw std::runtime_error("compact plan refreshed entry batch changed");
        }
        if (static_cast<ssize_t>(spec.stack_shape.size()) != expected_block_ndim + 1) {
            throw std::runtime_error("compact plan refreshed stack rank mismatch");
        }
        auto stack_info = spec.owned_stack.request();
        cdouble* stack = static_cast<cdouble*>(stack_info.ptr);
        ssize_t block_size = 1;
        for (ssize_t axis = 1; axis < static_cast<ssize_t>(spec.stack_shape.size()); ++axis) {
            block_size *= spec.stack_shape[static_cast<size_t>(axis)];
        }
        for (ssize_t entry = 0; entry < batch; ++entry) {
            const ssize_t block_index = static_cast<ssize_t>(
                entry_view(entry, source_column)
            );
            if (block_index < 0 || block_index >= static_cast<ssize_t>(py::len(blocks))) {
                throw std::runtime_error("compact plan refreshed source block index out of range");
            }
            py::array_t<cdouble, py::array::c_style | py::array::forcecast> block =
                py::cast<py::array_t<cdouble, py::array::c_style | py::array::forcecast>>(
                    blocks[block_index]
                );
            if (block.ndim() != expected_block_ndim) {
                throw std::runtime_error("compact plan refreshed source block rank changed");
            }
            auto block_info = block.request();
            ssize_t block_elements = 1;
            for (ssize_t axis = 0; axis < expected_block_ndim; ++axis) {
                const ssize_t dim = static_cast<ssize_t>(
                    block_info.shape[static_cast<size_t>(axis)]
                );
                if (dim != spec.stack_shape[static_cast<size_t>(axis + 1)]) {
                    throw std::runtime_error("compact plan refreshed source block shape changed");
                }
                block_elements *= dim;
            }
            if (block_elements != block_size) {
                throw std::runtime_error("compact plan refreshed source block size changed");
            }
            const cdouble* src = static_cast<const cdouble*>(block_info.ptr);
            cdouble* dst = stack + entry * block_size;
            std::copy(src, src + block_size, dst);
        }
        spec.stack = static_cast<const cdouble*>(spec.owned_stack.request().ptr);
    }
}

class CppCompactPlan {
public:
    ssize_t dim;
    std::vector<CompactStageSpec> r_specs;
    std::vector<CompactStageSpec> t2_specs;
    std::vector<CompactStageSpec> t3_specs;
    std::vector<CompactStageSpec> out_specs;
    std::vector<ssize_t> a_offsets;
    std::vector<ssize_t> a_sizes;
    std::vector<ssize_t> r_offsets;
    std::vector<ssize_t> r_sizes;
    std::vector<ssize_t> t2_offsets;
    std::vector<ssize_t> t2_sizes;
    std::vector<ssize_t> t3_offsets;
    std::vector<ssize_t> t3_sizes;
    std::vector<ssize_t> out_offsets;
    std::vector<ssize_t> out_sizes;
    ssize_t a_total;
    ssize_t r_total;
    ssize_t t2_total;
    ssize_t t3_total;
    ssize_t out_total;
    std::vector<ssize_t> a_block_group;
    std::vector<ssize_t> a_block_pos;
    std::vector<ssize_t> a_flat_start;
    std::vector<ssize_t> a_flat_size;
    std::vector<ssize_t> out_block_group;
    std::vector<ssize_t> out_block_pos;
    std::vector<ssize_t> out_flat_start;
    std::vector<ssize_t> out_flat_size;
    std::vector<cdouble> scratch_a_arena;
    std::vector<cdouble> scratch_r_arena;
    std::vector<cdouble> scratch_t2_arena;
    std::vector<cdouble> scratch_t3_arena;
    std::vector<cdouble> scratch_out_arena;
    std::vector<cdouble> scratch_out;

    CppCompactPlan(
        py::sequence py_r_stacks,
        py::sequence py_t2_stacks,
        py::sequence py_t3_stacks,
        py::sequence py_out_stacks,
        py::sequence py_r_specs,
        py::sequence py_t2_specs,
        py::sequence py_t3_specs,
        py::sequence py_out_specs,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_a_offsets,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_a_sizes,
        ssize_t py_a_total,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_r_offsets,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_r_sizes,
        ssize_t py_r_total,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_t2_offsets,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_t2_sizes,
        ssize_t py_t2_total,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_t3_offsets,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_t3_sizes,
        ssize_t py_t3_total,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_out_offsets,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_out_sizes,
        ssize_t py_out_total,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_a_block_group,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_a_block_pos,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_a_flat_start,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_a_flat_size,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_out_block_group,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_out_block_pos,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_out_flat_start,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_out_flat_size,
        ssize_t dim_arg
    ) :
        dim(dim_arg),
        r_specs(parse_stage_specs(py_r_stacks, py_r_specs, 4)),
        t2_specs(parse_stage_specs(py_t2_stacks, py_t2_specs, 5)),
        t3_specs(parse_stage_specs(py_t3_stacks, py_t3_specs, 5)),
        out_specs(parse_stage_specs(py_out_stacks, py_out_specs, 4)),
        a_offsets(copy_int_array(py_a_offsets)),
        a_sizes(copy_int_array(py_a_sizes)),
        r_offsets(copy_int_array(py_r_offsets)),
        r_sizes(copy_int_array(py_r_sizes)),
        t2_offsets(copy_int_array(py_t2_offsets)),
        t2_sizes(copy_int_array(py_t2_sizes)),
        t3_offsets(copy_int_array(py_t3_offsets)),
        t3_sizes(copy_int_array(py_t3_sizes)),
        out_offsets(copy_int_array(py_out_offsets)),
        out_sizes(copy_int_array(py_out_sizes)),
        a_total(py_a_total),
        r_total(py_r_total),
        t2_total(py_t2_total),
        t3_total(py_t3_total),
        out_total(py_out_total),
        a_block_group(copy_int_array(py_a_block_group)),
        a_block_pos(copy_int_array(py_a_block_pos)),
        a_flat_start(copy_int_array(py_a_flat_start)),
        a_flat_size(copy_int_array(py_a_flat_size)),
        out_block_group(copy_int_array(py_out_block_group)),
        out_block_pos(copy_int_array(py_out_block_pos)),
        out_flat_start(copy_int_array(py_out_flat_start)),
        out_flat_size(copy_int_array(py_out_flat_size))
    {
        initialize_storage();
    }

    CppCompactPlan(
        py::sequence py_e_blocks,
        py::sequence py_r_entry_groups,
        py::sequence py_w1_blocks,
        py::sequence py_t2_entry_groups,
        py::sequence py_w2_blocks,
        py::sequence py_t3_entry_groups,
        py::sequence py_f_blocks,
        py::sequence py_out_entry_groups,
        py::sequence py_r_specs,
        py::sequence py_t2_specs,
        py::sequence py_t3_specs,
        py::sequence py_out_specs,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_a_offsets,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_a_sizes,
        ssize_t py_a_total,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_r_offsets,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_r_sizes,
        ssize_t py_r_total,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_t2_offsets,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_t2_sizes,
        ssize_t py_t2_total,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_t3_offsets,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_t3_sizes,
        ssize_t py_t3_total,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_out_offsets,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_out_sizes,
        ssize_t py_out_total,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_a_block_group,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_a_block_pos,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_a_flat_start,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_a_flat_size,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_out_block_group,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_out_block_pos,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_out_flat_start,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_out_flat_size,
        ssize_t dim_arg
    ) :
        dim(dim_arg),
        r_specs(parse_stage_specs_from_blocks(py_e_blocks, py_r_entry_groups, py_r_specs, 0, 3)),
        t2_specs(parse_stage_specs_from_blocks(py_w1_blocks, py_t2_entry_groups, py_t2_specs, 1, 4)),
        t3_specs(parse_stage_specs_from_blocks(py_w2_blocks, py_t3_entry_groups, py_t3_specs, 1, 4)),
        out_specs(parse_stage_specs_from_blocks(py_f_blocks, py_out_entry_groups, py_out_specs, 1, 3)),
        a_offsets(copy_int_array(py_a_offsets)),
        a_sizes(copy_int_array(py_a_sizes)),
        r_offsets(copy_int_array(py_r_offsets)),
        r_sizes(copy_int_array(py_r_sizes)),
        t2_offsets(copy_int_array(py_t2_offsets)),
        t2_sizes(copy_int_array(py_t2_sizes)),
        t3_offsets(copy_int_array(py_t3_offsets)),
        t3_sizes(copy_int_array(py_t3_sizes)),
        out_offsets(copy_int_array(py_out_offsets)),
        out_sizes(copy_int_array(py_out_sizes)),
        a_total(py_a_total),
        r_total(py_r_total),
        t2_total(py_t2_total),
        t3_total(py_t3_total),
        out_total(py_out_total),
        a_block_group(copy_int_array(py_a_block_group)),
        a_block_pos(copy_int_array(py_a_block_pos)),
        a_flat_start(copy_int_array(py_a_flat_start)),
        a_flat_size(copy_int_array(py_a_flat_size)),
        out_block_group(copy_int_array(py_out_block_group)),
        out_block_pos(copy_int_array(py_out_block_pos)),
        out_flat_start(copy_int_array(py_out_flat_start)),
        out_flat_size(copy_int_array(py_out_flat_size))
    {
        initialize_storage();
    }

    void initialize_storage() {
        if (dim <= 0) {
            throw std::runtime_error("CompactPlan dimension must be positive");
        }
        if (
            a_block_group.size() != a_block_pos.size() ||
            a_block_group.size() != a_flat_start.size() ||
            a_block_group.size() != a_flat_size.size() ||
            out_block_group.size() != out_block_pos.size() ||
            out_block_group.size() != out_flat_start.size() ||
            out_block_group.size() != out_flat_size.size()
        ) {
            throw std::runtime_error("compact plan block mapping arrays differ in length");
        }
        scratch_a_arena.resize(static_cast<size_t>(a_total));
        scratch_r_arena.resize(static_cast<size_t>(r_total));
        scratch_t2_arena.resize(static_cast<size_t>(t2_total));
        scratch_t3_arena.resize(static_cast<size_t>(t3_total));
        scratch_out_arena.resize(static_cast<size_t>(out_total));
        scratch_out.resize(static_cast<size_t>(dim));
    }

    void update_stacks(
        py::sequence py_r_stacks,
        py::sequence py_t2_stacks,
        py::sequence py_t3_stacks,
        py::sequence py_out_stacks
    ) {
        update_stage_stacks(r_specs, py_r_stacks, 4);
        update_stage_stacks(t2_specs, py_t2_stacks, 5);
        update_stage_stacks(t3_specs, py_t3_stacks, 5);
        update_stage_stacks(out_specs, py_out_stacks, 4);
    }

    void update_stacks_from_blocks(
        py::sequence py_e_blocks,
        py::sequence py_r_entries,
        py::sequence py_w1_blocks,
        py::sequence py_t2_entries,
        py::sequence py_w2_blocks,
        py::sequence py_t3_entries,
        py::sequence py_f_blocks,
        py::sequence py_out_entries
    ) {
        update_stage_stacks_from_blocks(r_specs, py_e_blocks, py_r_entries, 0, 3);
        update_stage_stacks_from_blocks(t2_specs, py_w1_blocks, py_t2_entries, 1, 4);
        update_stage_stacks_from_blocks(t3_specs, py_w2_blocks, py_t3_entries, 1, 4);
        update_stage_stacks_from_blocks(out_specs, py_f_blocks, py_out_entries, 1, 3);
    }

    const std::vector<cdouble>& matvec_ptr(const cdouble* vec, ssize_t vec_dim) {
        if (vec_dim != dim) {
            throw std::runtime_error("vector dimension does not match CompactPlan dimension");
        }
        std::fill(scratch_a_arena.begin(), scratch_a_arena.end(), cdouble(0.0, 0.0));
        std::fill(scratch_r_arena.begin(), scratch_r_arena.end(), cdouble(0.0, 0.0));
        std::fill(scratch_t2_arena.begin(), scratch_t2_arena.end(), cdouble(0.0, 0.0));
        std::fill(scratch_t3_arena.begin(), scratch_t3_arena.end(), cdouble(0.0, 0.0));
        std::fill(scratch_out_arena.begin(), scratch_out_arena.end(), cdouble(0.0, 0.0));
        std::fill(scratch_out.begin(), scratch_out.end(), cdouble(0.0, 0.0));

        for (ssize_t block = 0; block < static_cast<ssize_t>(a_block_group.size()); ++block) {
            const ssize_t group = a_block_group[static_cast<size_t>(block)];
            const ssize_t pos = a_block_pos[static_cast<size_t>(block)];
            const ssize_t start = a_flat_start[static_cast<size_t>(block)];
            const ssize_t n = a_flat_size[static_cast<size_t>(block)];
            if (
                group < 0 || group >= static_cast<ssize_t>(a_offsets.size()) ||
                start < 0 || start + n > dim ||
                n > a_sizes[static_cast<size_t>(group)]
            ) {
                throw std::runtime_error("compact plan input block mapping is invalid");
            }
            const ssize_t base = a_offsets[static_cast<size_t>(group)] +
                                 pos * a_sizes[static_cast<size_t>(group)];
            std::copy(
                vec + start,
                vec + start + n,
                scratch_a_arena.begin() + base
            );
        }

        apply_r_stage(scratch_a_arena, scratch_r_arena);
        apply_t2_stage(scratch_r_arena, scratch_t2_arena);
        apply_t3_stage(scratch_t2_arena, scratch_t3_arena);
        apply_out_stage(scratch_t3_arena, scratch_out_arena);

        for (ssize_t block = 0; block < static_cast<ssize_t>(out_block_group.size()); ++block) {
            const ssize_t group = out_block_group[static_cast<size_t>(block)];
            const ssize_t pos = out_block_pos[static_cast<size_t>(block)];
            const ssize_t start = out_flat_start[static_cast<size_t>(block)];
            const ssize_t n = out_flat_size[static_cast<size_t>(block)];
            if (
                group < 0 || group >= static_cast<ssize_t>(out_offsets.size()) ||
                start < 0 || start + n > dim ||
                n > out_sizes[static_cast<size_t>(group)]
            ) {
                throw std::runtime_error("compact plan output block mapping is invalid");
            }
            const ssize_t base = out_offsets[static_cast<size_t>(group)] +
                                 pos * out_sizes[static_cast<size_t>(group)];
            std::copy(
                scratch_out_arena.begin() + base,
                scratch_out_arena.begin() + base + n,
                scratch_out.begin() + start
            );
        }
        return scratch_out;
    }

    std::vector<cdouble> matvec_vector(const std::vector<cdouble>& vec) {
        const std::vector<cdouble>& out = matvec_ptr(
            vec.data(),
            static_cast<ssize_t>(vec.size())
        );
        return out;
    }

    py::array_t<cdouble> matvec(
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_vec
    ) {
        auto vec_arr = py_vec.unchecked<1>();
        if (vec_arr.shape(0) != dim) {
            throw std::runtime_error("vector dimension does not match CompactPlan dimension");
        }
        auto info = py_vec.request();
        const cdouble* vec_ptr = static_cast<const cdouble*>(info.ptr);
        const std::vector<cdouble>& result = matvec_ptr(vec_ptr, vec_arr.shape(0));
        py::array_t<cdouble> py_out(dim);
        auto out_mut = py_out.mutable_unchecked<1>();
        for (ssize_t i = 0; i < dim; ++i) {
            out_mut(i) = result[static_cast<size_t>(i)];
        }
        return py_out;
    }

    py::array_t<cdouble> diagonal_from_routes(
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_routes
    ) {
        if (py_routes.ndim() != 2) {
            throw std::runtime_error("compact diagonal routes must be rank-2");
        }
        auto routes = py_routes.unchecked<2>();
        if (routes.shape(1) < 13) {
            throw std::runtime_error("compact diagonal route table is too narrow");
        }
        py::array_t<cdouble> py_diag(dim);
        auto diag = py_diag.mutable_unchecked<1>();
        for (ssize_t index = 0; index < dim; ++index) {
            diag(index) = cdouble(0.0, 0.0);
        }
        for (ssize_t route = 0; route < routes.shape(0); ++route) {
            const ssize_t r_group = routes(route, 0);
            const ssize_t r_entry = routes(route, 1);
            const ssize_t t2_group = routes(route, 2);
            const ssize_t t2_entry = routes(route, 3);
            const ssize_t t3_group = routes(route, 4);
            const ssize_t t3_entry = routes(route, 5);
            const ssize_t out_group = routes(route, 6);
            const ssize_t out_entry = routes(route, 7);
            const ssize_t flat_start = routes(route, 8);
            const ssize_t ni = routes(route, 9);
            const ssize_t nk = routes(route, 10);
            const ssize_t nu = routes(route, 11);
            const ssize_t nv = routes(route, 12);
            if (
                r_group < 0 || r_group >= static_cast<ssize_t>(r_specs.size()) ||
                t2_group < 0 || t2_group >= static_cast<ssize_t>(t2_specs.size()) ||
                t3_group < 0 || t3_group >= static_cast<ssize_t>(t3_specs.size()) ||
                out_group < 0 || out_group >= static_cast<ssize_t>(out_specs.size()) ||
                flat_start < 0 || flat_start + ni * nk * nu * nv > dim
            ) {
                throw std::runtime_error("compact diagonal route is invalid");
            }
            const CompactStageSpec& r_spec = r_specs[static_cast<size_t>(r_group)];
            const CompactStageSpec& t2_spec = t2_specs[static_cast<size_t>(t2_group)];
            const CompactStageSpec& t3_spec = t3_specs[static_cast<size_t>(t3_group)];
            const CompactStageSpec& out_spec = out_specs[static_cast<size_t>(out_group)];
            if (
                r_entry < 0 || r_entry >= r_spec.stack_shape[0] ||
                t2_entry < 0 || t2_entry >= t2_spec.stack_shape[0] ||
                t3_entry < 0 || t3_entry >= t3_spec.stack_shape[0] ||
                out_entry < 0 || out_entry >= out_spec.stack_shape[0]
            ) {
                throw std::runtime_error("compact diagonal route entry is invalid");
            }
            if (
                r_spec.stack_shape.size() != 4 ||
                t2_spec.stack_shape.size() != 5 ||
                t3_spec.stack_shape.size() != 5 ||
                out_spec.stack_shape.size() != 4
            ) {
                throw std::runtime_error("compact diagonal route stack rank mismatch");
            }
            const ssize_t na = r_spec.stack_shape[1];
            const ssize_t e_ni = r_spec.stack_shape[2];
            const ssize_t e_nj = r_spec.stack_shape[3];
            const ssize_t w1_na = t2_spec.stack_shape[1];
            const ssize_t nb = t2_spec.stack_shape[2];
            const ssize_t w1_nu = t2_spec.stack_shape[3];
            const ssize_t w1_nx = t2_spec.stack_shape[4];
            const ssize_t w2_nb = t3_spec.stack_shape[1];
            const ssize_t nc = t3_spec.stack_shape[2];
            const ssize_t w2_nv = t3_spec.stack_shape[3];
            const ssize_t w2_ny = t3_spec.stack_shape[4];
            const ssize_t f_nc = out_spec.stack_shape[1];
            const ssize_t f_nl = out_spec.stack_shape[2];
            const ssize_t f_nk = out_spec.stack_shape[3];
            if (
                e_ni != ni || e_nj != ni ||
                w1_na != na || w1_nu != nu || w1_nx != nu ||
                w2_nb != nb || w2_nv != nv || w2_ny != nv ||
                f_nc != nc || f_nl != nk || f_nk != nk
            ) {
                continue;
            }
            const ssize_t e_stride = prod_tail(r_spec.stack_shape, 1, 4);
            const ssize_t w1_stride = prod_tail(t2_spec.stack_shape, 1, 5);
            const ssize_t w2_stride = prod_tail(t3_spec.stack_shape, 1, 5);
            const ssize_t f_stride = prod_tail(out_spec.stack_shape, 1, 4);
            const cdouble* e = r_spec.stack + r_entry * e_stride;
            const cdouble* w1 = t2_spec.stack + t2_entry * w1_stride;
            const cdouble* w2 = t3_spec.stack + t3_entry * w2_stride;
            const cdouble* f = out_spec.stack + out_entry * f_stride;
            for (ssize_t i = 0; i < ni; ++i) {
                for (ssize_t k = 0; k < nk; ++k) {
                    for (ssize_t u = 0; u < nu; ++u) {
                        for (ssize_t v = 0; v < nv; ++v) {
                            cdouble total = 0.0;
                            for (ssize_t a = 0; a < na; ++a) {
                                const cdouble e_diag = e[(a * ni + i) * ni + i];
                                for (ssize_t b = 0; b < nb; ++b) {
                                    const cdouble w1_diag =
                                        w1[((a * nb + b) * nu + u) * nu + u];
                                    for (ssize_t c = 0; c < nc; ++c) {
                                        const cdouble w2_diag =
                                            w2[((b * nc + c) * nv + v) * nv + v];
                                        const cdouble f_diag =
                                            f[(c * nk + k) * nk + k];
                                        total += e_diag * w1_diag * w2_diag * f_diag;
                                    }
                                }
                            }
                            const ssize_t flat =
                                flat_start + (((i * nk + k) * nu + u) * nv + v);
                            diag(flat) += total;
                        }
                    }
                }
            }
        }
        return py_diag;
    }

    py::dict davidson(
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_diag,
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_v0,
        double tol,
        int max_iter,
        int restart_dim,
        bool accept_unconverged
    ) {
        auto diag_arr = py_diag.unchecked<1>();
        auto v0_arr = py_v0.unchecked<1>();
        if (diag_arr.shape(0) != dim || v0_arr.shape(0) != dim) {
            throw std::runtime_error("diag, v0, and CompactPlan dimensions differ");
        }
        std::vector<cdouble> diag(static_cast<size_t>(dim));
        std::vector<cdouble> v(static_cast<size_t>(dim));
        for (ssize_t i = 0; i < dim; ++i) {
            diag[static_cast<size_t>(i)] = diag_arr(i);
            v[static_cast<size_t>(i)] = v0_arr(i);
        }
        return davidson_core(
            dim,
            diag,
            std::move(v),
            tol,
            max_iter,
            restart_dim,
            accept_unconverged,
            [this](const std::vector<cdouble>& x) { return this->matvec_vector(x); }
        );
    }

private:
    static const cdouble* arena_ptr(
        const std::vector<cdouble>& arena,
        const std::vector<ssize_t>& offsets,
        const std::vector<ssize_t>& sizes,
        ssize_t group,
        ssize_t pos
    ) {
        const ssize_t base = offsets[static_cast<size_t>(group)] +
                             pos * sizes[static_cast<size_t>(group)];
        return arena.data() + base;
    }

    static cdouble* arena_mut_ptr(
        std::vector<cdouble>& arena,
        const std::vector<ssize_t>& offsets,
        const std::vector<ssize_t>& sizes,
        ssize_t group,
        ssize_t pos
    ) {
        const ssize_t base = offsets[static_cast<size_t>(group)] +
                             pos * sizes[static_cast<size_t>(group)];
        return arena.data() + base;
    }

    static ssize_t prod_tail(const std::vector<ssize_t>& values, ssize_t first, ssize_t last) {
        ssize_t out = 1;
        for (ssize_t i = first; i < last; ++i) {
            out *= values[static_cast<size_t>(i)];
        }
        return out;
    }

    void apply_r_stage(
        const std::vector<cdouble>& a_arena,
        std::vector<cdouble>& r_arena
    ) {
        for (const auto& spec : r_specs) {
            if (spec.shape_info.size() != 9 || spec.stack_shape.size() != 4) {
                throw std::runtime_error("compact R-stage shape metadata mismatch");
            }
            const ssize_t nj = spec.shape_info[0];
            const ssize_t nk = spec.shape_info[1];
            const ssize_t nx = spec.shape_info[2];
            const ssize_t ny = spec.shape_info[3];
            const ssize_t na = spec.shape_info[4];
            const ssize_t ni = spec.shape_info[5];
            const ssize_t batch = spec.stack_shape[0];
            const ssize_t e_stride = prod_tail(spec.stack_shape, 1, 4);
            for (ssize_t entry = 0; entry < batch; ++entry) {
                const cdouble* e = spec.stack + entry * e_stride;
                const cdouble* a = arena_ptr(
                    a_arena, a_offsets, a_sizes, spec.input_group,
                    spec.input_pos[static_cast<size_t>(entry)]
                );
                cdouble* r = arena_mut_ptr(
                    r_arena, r_offsets, r_sizes, spec.output_group,
                    spec.output_pos[static_cast<size_t>(entry)]
                );
                for (ssize_t alpha = 0; alpha < na; ++alpha) {
                    for (ssize_t i = 0; i < ni; ++i) {
                        for (ssize_t k = 0; k < nk; ++k) {
                            for (ssize_t x = 0; x < nx; ++x) {
                                for (ssize_t y = 0; y < ny; ++y) {
                                    cdouble total = 0.0;
                                    for (ssize_t j = 0; j < nj; ++j) {
                                        const ssize_t e_idx = (alpha * ni + i) * nj + j;
                                        const ssize_t a_idx = ((j * nk + k) * nx + x) * ny + y;
                                        total += e[e_idx] * a[a_idx];
                                    }
                                    const ssize_t r_idx =
                                        ((((alpha * ni + i) * nk + k) * nx + x) * ny + y);
                                    r[r_idx] += total;
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    void apply_t2_stage(
        const std::vector<cdouble>& r_arena,
        std::vector<cdouble>& t2_arena
    ) {
        for (const auto& spec : t2_specs) {
            if (spec.shape_info.size() != 10 || spec.stack_shape.size() != 5) {
                throw std::runtime_error("compact T2-stage shape metadata mismatch");
            }
            const ssize_t na = spec.shape_info[0];
            const ssize_t ni = spec.shape_info[1];
            const ssize_t nk = spec.shape_info[2];
            const ssize_t nx = spec.shape_info[3];
            const ssize_t ny = spec.shape_info[4];
            const ssize_t nb = spec.shape_info[8];
            const ssize_t nu = spec.shape_info[9];
            const ssize_t batch = spec.stack_shape[0];
            const ssize_t w_stride = prod_tail(spec.stack_shape, 1, 5);
            for (ssize_t entry = 0; entry < batch; ++entry) {
                const cdouble* r = arena_ptr(
                    r_arena, r_offsets, r_sizes, spec.input_group,
                    spec.input_pos[static_cast<size_t>(entry)]
                );
                const cdouble* w = spec.stack + entry * w_stride;
                cdouble* t2 = arena_mut_ptr(
                    t2_arena, t2_offsets, t2_sizes, spec.output_group,
                    spec.output_pos[static_cast<size_t>(entry)]
                );
                for (ssize_t i = 0; i < ni; ++i) {
                    for (ssize_t k = 0; k < nk; ++k) {
                        for (ssize_t y = 0; y < ny; ++y) {
                            for (ssize_t b = 0; b < nb; ++b) {
                                for (ssize_t u = 0; u < nu; ++u) {
                                    cdouble total = 0.0;
                                    for (ssize_t alpha = 0; alpha < na; ++alpha) {
                                        for (ssize_t x = 0; x < nx; ++x) {
                                            const ssize_t r_idx =
                                                ((((alpha * ni + i) * nk + k) * nx + x) * ny + y);
                                            const ssize_t w_idx =
                                                (((alpha * nb + b) * nu + u) * nx + x);
                                            total += r[r_idx] * w[w_idx];
                                        }
                                    }
                                    const ssize_t t2_idx =
                                        ((((i * nk + k) * ny + y) * nb + b) * nu + u);
                                    t2[t2_idx] += total;
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    void apply_t3_stage(
        const std::vector<cdouble>& t2_arena,
        std::vector<cdouble>& t3_arena
    ) {
        for (const auto& spec : t3_specs) {
            if (spec.shape_info.size() != 10 || spec.stack_shape.size() != 5) {
                throw std::runtime_error("compact T3-stage shape metadata mismatch");
            }
            const ssize_t ni = spec.shape_info[0];
            const ssize_t nk = spec.shape_info[1];
            const ssize_t ny = spec.shape_info[2];
            const ssize_t nb = spec.shape_info[3];
            const ssize_t nu = spec.shape_info[4];
            const ssize_t nc = spec.shape_info[8];
            const ssize_t nv = spec.shape_info[9];
            const ssize_t batch = spec.stack_shape[0];
            const ssize_t w_stride = prod_tail(spec.stack_shape, 1, 5);
            for (ssize_t entry = 0; entry < batch; ++entry) {
                const cdouble* t2 = arena_ptr(
                    t2_arena, t2_offsets, t2_sizes, spec.input_group,
                    spec.input_pos[static_cast<size_t>(entry)]
                );
                const cdouble* w = spec.stack + entry * w_stride;
                cdouble* t3 = arena_mut_ptr(
                    t3_arena, t3_offsets, t3_sizes, spec.output_group,
                    spec.output_pos[static_cast<size_t>(entry)]
                );
                for (ssize_t i = 0; i < ni; ++i) {
                    for (ssize_t k = 0; k < nk; ++k) {
                        for (ssize_t u = 0; u < nu; ++u) {
                            for (ssize_t c = 0; c < nc; ++c) {
                                for (ssize_t v = 0; v < nv; ++v) {
                                    cdouble total = 0.0;
                                    for (ssize_t b = 0; b < nb; ++b) {
                                        for (ssize_t y = 0; y < ny; ++y) {
                                            const ssize_t t2_idx =
                                                ((((i * nk + k) * ny + y) * nb + b) * nu + u);
                                            const ssize_t w_idx =
                                                (((b * nc + c) * nv + v) * ny + y);
                                            total += t2[t2_idx] * w[w_idx];
                                        }
                                    }
                                    const ssize_t t3_idx =
                                        ((((i * nk + k) * nu + u) * nc + c) * nv + v);
                                    t3[t3_idx] += total;
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    void apply_out_stage(
        const std::vector<cdouble>& t3_arena,
        std::vector<cdouble>& out_arena
    ) {
        for (const auto& spec : out_specs) {
            if (spec.shape_info.size() != 9 || spec.stack_shape.size() != 4) {
                throw std::runtime_error("compact output-stage shape metadata mismatch");
            }
            const ssize_t ni = spec.shape_info[0];
            const ssize_t nk = spec.shape_info[1];
            const ssize_t nu = spec.shape_info[2];
            const ssize_t nc = spec.shape_info[3];
            const ssize_t nv = spec.shape_info[4];
            const ssize_t nl = spec.shape_info[6];
            const ssize_t batch = spec.stack_shape[0];
            const ssize_t f_stride = prod_tail(spec.stack_shape, 1, 4);
            for (ssize_t entry = 0; entry < batch; ++entry) {
                const cdouble* t3 = arena_ptr(
                    t3_arena, t3_offsets, t3_sizes, spec.input_group,
                    spec.input_pos[static_cast<size_t>(entry)]
                );
                const cdouble* f = spec.stack + entry * f_stride;
                cdouble* out = arena_mut_ptr(
                    out_arena, out_offsets, out_sizes, spec.output_group,
                    spec.output_pos[static_cast<size_t>(entry)]
                );
                for (ssize_t i = 0; i < ni; ++i) {
                    for (ssize_t l = 0; l < nl; ++l) {
                        for (ssize_t u = 0; u < nu; ++u) {
                            for (ssize_t v = 0; v < nv; ++v) {
                                cdouble total = 0.0;
                                for (ssize_t c = 0; c < nc; ++c) {
                                    for (ssize_t k = 0; k < nk; ++k) {
                                        const ssize_t t3_idx =
                                            ((((i * nk + k) * nu + u) * nc + c) * nv + v);
                                        const ssize_t f_idx = ((c * nl + l) * nk + k);
                                        total += t3[t3_idx] * f[f_idx];
                                    }
                                }
                                const ssize_t out_idx =
                                    (((i * nl + l) * nu + u) * nv + v);
                                out[out_idx] += total;
                            }
                        }
                    }
                }
            }
        }
    }
};

