    py::list sweep_bonds(
        ssize_t n_sites,
        const std::string& direction,
        ssize_t center_i = -1,
        ssize_t last_i = -1
    ) {
        py::list out;
        try {
            if (n_sites < 2) {
                throw std::runtime_error("MovingEnvironment sweep cursor requires at least two sites");
            }
            if (direction == "lr") {
                for (ssize_t i = 0; i < n_sites - 2; ++i) {
                    out.append(py::int_(i));
                }
                ++sweep_cursor_lr_calls;
            } else if (direction == "rl") {
                for (ssize_t i = n_sites - 2; i > 0; --i) {
                    out.append(py::int_(i));
                }
                ++sweep_cursor_rl_calls;
            } else if (direction == "recenter_left") {
                if (center_i < 0) {
                    center_i = n_sites / 2 - 1;
                }
                for (ssize_t i = n_sites - 2; i >= center_i; --i) {
                    out.append(py::int_(i));
                    if (i == 0) {
                        break;
                    }
                }
                ++sweep_cursor_recenter_calls;
            } else if (direction == "recenter_right") {
                if (center_i < 0) {
                    center_i = n_sites / 2 - 1;
                }
                for (ssize_t i = 0; i <= center_i; ++i) {
                    out.append(py::int_(i));
                }
                ++sweep_cursor_recenter_calls;
            } else {
                throw std::runtime_error("unknown MovingEnvironment sweep cursor direction");
            }
            const ssize_t n_steps = static_cast<ssize_t>(py::len(out));
            ++sweep_cursor_plan_calls;
            sweep_cursor_steps += n_steps;
            sweep_cursor_last_n_sites = n_sites;
            sweep_cursor_last_steps = n_steps;
            sweep_cursor_last_direction = direction;
            (void)last_i;
            return out;
        } catch (const std::exception& exc) {
            sweep_cursor_last_error = exc.what();
            throw;
        }
    }

    void set_environment_stack(const std::string& key, py::sequence values) {
        EnvironmentStackRecord record;
        const ssize_t n = static_cast<ssize_t>(py::len(values));
        record.values.reserve(static_cast<size_t>(n));
        for (ssize_t i = 0; i < n; ++i) {
            record.values.push_back(py::reinterpret_borrow<py::object>(values[i]));
        }
        environment_stack_last_depth = n;
        environment_stacks[key] = std::move(record);
        ++environment_stack_resets;
    }

    void environment_stack_push(const std::string& key, py::object value) {
        auto& record = environment_stacks[key];
        record.values.push_back(value);
        environment_stack_last_depth =
            static_cast<ssize_t>(record.values.size());
        ++environment_stack_pushes;
    }

    py::object environment_stack_pop(const std::string& key) {
        auto it = environment_stacks.find(key);
        if (it == environment_stacks.end() || it->second.values.empty()) {
            ++environment_stack_failures;
            environment_stack_last_error = "MovingEnvironment environment stack is empty";
            throw std::runtime_error(environment_stack_last_error);
        }
        py::object value = it->second.values.back();
        it->second.values.pop_back();
        environment_stack_last_depth =
            static_cast<ssize_t>(it->second.values.size());
        ++environment_stack_pops;
        return value;
    }

    py::tuple environment_stack_apply(
        const std::string& key,
        const std::string& action,
        py::object values = py::none(),
        py::object value = py::none()
    ) {
        ++environment_stack_apply_calls;
        bool did_sync = false;
        bool did_push = false;
        bool did_pop = false;
        bool did_replace = false;
        py::object popped = py::none();
        try {
            if (action == "sync" || action == "push" || action == "pop") {
                if (!values.is_none()) {
                    py::sequence seq = values.cast<py::sequence>();
                    const ssize_t requested =
                        static_cast<ssize_t>(py::len(seq));
                    if (environment_stack_depth(key) != requested) {
                        set_environment_stack(key, seq);
                        did_sync = true;
                        ++environment_stack_apply_syncs;
                    }
                }
            }
            if (action == "sync") {
                return py::make_tuple(
                    py::bool_(did_sync),
                    py::bool_(false),
                    py::bool_(false),
                    py::bool_(false),
                    py::int_(environment_stack_depth(key)),
                    popped
                );
            }
            if (action == "push") {
                environment_stack_push(key, value);
                did_push = true;
                ++environment_stack_apply_pushes;
            } else if (action == "pop") {
                popped = environment_stack_pop(key);
                did_pop = true;
                ++environment_stack_apply_pops;
            } else if (action == "replace") {
                py::tuple single = py::make_tuple(value);
                set_environment_stack(key, single);
                did_replace = true;
                ++environment_stack_apply_replaces;
            } else {
                throw std::runtime_error(
                    "unknown MovingEnvironment environment stack action"
                );
            }
            return py::make_tuple(
                py::bool_(did_sync),
                py::bool_(did_push),
                py::bool_(did_pop),
                py::bool_(did_replace),
                py::int_(environment_stack_depth(key)),
                popped
            );
        } catch (const std::exception& exc) {
            ++environment_stack_apply_failures;
            environment_stack_last_error = exc.what();
            throw;
        }
    }

    ssize_t environment_stack_depth(const std::string& key) const {
        auto it = environment_stacks.find(key);
        if (it == environment_stacks.end()) {
            return 0;
        }
        return static_cast<ssize_t>(it->second.values.size());
    }

