    static py::object component_E(const DirectComponentItem& item) {
        return item.fields ? item.fields->E : item.component.attr("E");
    }

    static py::object component_W_left(const DirectComponentItem& item) {
        return item.fields ? item.fields->W_left : item.component.attr("W_left");
    }

    static py::object component_W_right(const DirectComponentItem& item) {
        return item.fields ? item.fields->W_right : item.component.attr("W_right");
    }

    static py::object component_F(const DirectComponentItem& item) {
        return item.fields ? item.fields->F : item.component.attr("F");
    }

    static std::string component_source(const DirectComponentItem& item) {
        if (item.fields) {
            return item.fields->source;
        }
        try {
            return py::str(item.component.attr("source")).cast<std::string>();
        } catch (const py::error_already_set&) {
            return "";
        } catch (const py::cast_error&) {
            return "";
        }
    }

    static bool is_identity_local_channel(const DirectComponentItem& item) {
        if (item.kind != "packed_local_generator") {
            return false;
        }
        const std::string source = component_source(item);
        return source.find("identity_local_csr") != std::string::npos;
    }

    struct BlockIndexCacheKey {
        PyObject* tensor_ptr;
        ssize_t axis0;
        ssize_t axis1;

        bool operator==(const BlockIndexCacheKey& other) const {
            return tensor_ptr == other.tensor_ptr
                && axis0 == other.axis0
                && axis1 == other.axis1;
        }
    };

    struct BlockIndexCacheKeyHash {
        size_t operator()(const BlockIndexCacheKey& key) const {
            size_t value = std::hash<void*>{}(static_cast<void*>(key.tensor_ptr));
            value ^= std::hash<ssize_t>{}(key.axis0)
                + 0x9e3779b97f4a7c15ULL
                + (value << 6)
                + (value >> 2);
            value ^= std::hash<ssize_t>{}(key.axis1)
                + 0x9e3779b97f4a7c15ULL
                + (value << 6)
                + (value >> 2);
            return value;
        }
    };

    struct PairStackKey {
        PyObject* first;
        PyObject* second;
        ssize_t local_dim;

        bool operator==(const PairStackKey& other) const {
            return first == other.first
                && second == other.second
                && local_dim == other.local_dim;
        }
    };

    struct PairStackKeyHash {
        size_t operator()(const PairStackKey& key) const {
            size_t value = std::hash<void*>{}(static_cast<void*>(key.first));
            value ^= std::hash<void*>{}(static_cast<void*>(key.second))
                + 0x9e3779b97f4a7c15ULL
                + (value << 6)
                + (value >> 2);
            value ^= std::hash<ssize_t>{}(key.local_dim)
                + 0x9e3779b97f4a7c15ULL
                + (value << 6)
                + (value >> 2);
            return value;
        }
    };

    struct DirectPayloadContext {
        std::unordered_map<
            BlockIndexCacheKey,
            std::unordered_map<std::string, std::vector<TensorBlock>>,
            BlockIndexCacheKeyHash
        > block_indices;
        std::unordered_map<
            PairStackKey,
            py::array_t<cdouble>,
            PairStackKeyHash
        > left_stacks;
        std::unordered_map<
            PairStackKey,
            py::array_t<cdouble>,
            PairStackKeyHash
        > right_stacks;
        std::unordered_map<
            PairStackKey,
            py::array_t<cdouble>,
            PairStackKeyHash
        > identity_left_stacks;
        std::unordered_map<
            PairStackKey,
            py::array_t<cdouble>,
            PairStackKeyHash
        > identity_right_stacks;
        ssize_t left_stack_hits = 0;
        ssize_t left_stack_builds = 0;
        ssize_t right_stack_hits = 0;
        ssize_t right_stack_builds = 0;
        ssize_t identity_left_stack_hits = 0;
        ssize_t identity_left_stack_builds = 0;
        ssize_t identity_right_stack_hits = 0;
        ssize_t identity_right_stack_builds = 0;
        ssize_t direct_w1_misses = 0;
        ssize_t direct_active_misses = 0;
        ssize_t direct_w2_ptr_misses = 0;
        ssize_t direct_w2_pair_misses = 0;
        ssize_t direct_f_ptr_misses = 0;
        ssize_t direct_f_pair_misses = 0;
        ssize_t direct_layout_ptr_misses = 0;
        ssize_t direct_layout_pair_misses = 0;
        ssize_t identity_f_ptr_misses = 0;
        ssize_t identity_f_pair_misses = 0;
        ssize_t identity_layout_ptr_misses = 0;
        ssize_t identity_layout_pair_misses = 0;
        double left_stack_seconds = 0.0;
        double right_stack_seconds = 0.0;
        double identity_left_stack_seconds = 0.0;
        double identity_right_stack_seconds = 0.0;

        const std::unordered_map<std::string, std::vector<TensorBlock>>&
        index_tensor(py::object tensor, ssize_t axis0, ssize_t axis1 = -1) {
            BlockIndexCacheKey key{tensor.ptr(), axis0, axis1};
            auto found = block_indices.find(key);
            if (found != block_indices.end()) {
                return found->second;
            }
            auto inserted = block_indices.emplace(
                key,
                block_index(tensor, axis0, axis1)
            );
            return inserted.first->second;
        }

        py::array_t<cdouble> left_stack(const TensorBlock& e, const TensorBlock& w1) {
            PairStackKey key{e.data_ptr, w1.data_ptr, -1};
            auto found = left_stacks.find(key);
            if (found != left_stacks.end()) {
                ++left_stack_hits;
                return found->second;
            }
            const double start = wall_seconds();
            py::array_t<cdouble> stack = direct_left_stack(e.data, w1.data);
            left_stack_seconds += wall_seconds() - start;
            ++left_stack_builds;
            left_stacks.emplace(key, stack);
            return stack;
        }

        py::array_t<cdouble> right_stack(const TensorBlock& w2, const TensorBlock& f) {
            PairStackKey key{w2.data_ptr, f.data_ptr, -1};
            auto found = right_stacks.find(key);
            if (found != right_stacks.end()) {
                ++right_stack_hits;
                return found->second;
            }
            const double start = wall_seconds();
            py::array_t<cdouble> stack = direct_right_stack(w2.data, f.data);
            right_stack_seconds += wall_seconds() - start;
            ++right_stack_builds;
            right_stacks.emplace(key, stack);
            return stack;
        }

        py::array_t<cdouble> identity_channel_left_stack(
            const TensorBlock& e,
            const TensorBlock& w1
        ) {
            PairStackKey key{e.data_ptr, w1.data_ptr, -2};
            auto found = left_stacks.find(key);
            if (found != left_stacks.end()) {
                ++left_stack_hits;
                return found->second;
            }
            const double start = wall_seconds();
            py::array_t<cdouble> stack = ::identity_channel_left_stack(
                e.data,
                w1.data
            );
            left_stack_seconds += wall_seconds() - start;
            ++left_stack_builds;
            left_stacks.emplace(key, stack);
            return stack;
        }

        py::array_t<cdouble> identity_channel_right_stack(
            const TensorBlock& w2,
            const TensorBlock& f
        ) {
            PairStackKey key{w2.data_ptr, f.data_ptr, -2};
            auto found = right_stacks.find(key);
            if (found != right_stacks.end()) {
                ++right_stack_hits;
                return found->second;
            }
            const double start = wall_seconds();
            py::array_t<cdouble> stack = ::identity_channel_right_stack(
                w2.data,
                f.data
            );
            right_stack_seconds += wall_seconds() - start;
            ++right_stack_builds;
            right_stacks.emplace(key, stack);
            return stack;
        }

        py::array_t<cdouble> identity_left_stack_cached(
            const TensorBlock& e,
            ssize_t nx
        ) {
            PairStackKey key{e.data_ptr, nullptr, nx};
            auto found = identity_left_stacks.find(key);
            if (found != identity_left_stacks.end()) {
                ++identity_left_stack_hits;
                return found->second;
            }
            const double start = wall_seconds();
            py::array_t<cdouble> stack = identity_left_stack(e.data, nx);
            identity_left_stack_seconds += wall_seconds() - start;
            ++identity_left_stack_builds;
            identity_left_stacks.emplace(key, stack);
            return stack;
        }

        py::array_t<cdouble> identity_right_stack_cached(
            const TensorBlock& f,
            ssize_t ny
        ) {
            PairStackKey key{f.data_ptr, nullptr, ny};
            auto found = identity_right_stacks.find(key);
            if (found != identity_right_stacks.end()) {
                ++identity_right_stack_hits;
                return found->second;
            }
            const double start = wall_seconds();
            py::array_t<cdouble> stack = identity_right_stack(f.data, ny);
            identity_right_stack_seconds += wall_seconds() - start;
            ++identity_right_stack_builds;
            identity_right_stacks.emplace(key, stack);
            return stack;
        }

        void copy_stats_to(CppRawPayloadBuilder& builder) const {
            builder.stats_left_stack_hits += left_stack_hits;
            builder.stats_left_stack_builds += left_stack_builds;
            builder.stats_right_stack_hits += right_stack_hits;
            builder.stats_right_stack_builds += right_stack_builds;
            builder.stats_identity_left_stack_hits += identity_left_stack_hits;
            builder.stats_identity_left_stack_builds += identity_left_stack_builds;
            builder.stats_identity_right_stack_hits += identity_right_stack_hits;
            builder.stats_identity_right_stack_builds += identity_right_stack_builds;
            builder.stats_direct_w1_misses += direct_w1_misses;
            builder.stats_direct_active_misses += direct_active_misses;
            builder.stats_direct_w2_ptr_misses += direct_w2_ptr_misses;
            builder.stats_direct_w2_pair_misses += direct_w2_pair_misses;
            builder.stats_direct_f_ptr_misses += direct_f_ptr_misses;
            builder.stats_direct_f_pair_misses += direct_f_pair_misses;
            builder.stats_direct_layout_ptr_misses += direct_layout_ptr_misses;
            builder.stats_direct_layout_pair_misses += direct_layout_pair_misses;
            builder.stats_identity_f_ptr_misses += identity_f_ptr_misses;
            builder.stats_identity_f_pair_misses += identity_f_pair_misses;
            builder.stats_identity_layout_ptr_misses += identity_layout_ptr_misses;
            builder.stats_identity_layout_pair_misses += identity_layout_pair_misses;
            builder.stats_left_stack_seconds += left_stack_seconds;
            builder.stats_right_stack_seconds += right_stack_seconds;
            builder.stats_identity_left_stack_seconds += identity_left_stack_seconds;
            builder.stats_identity_right_stack_seconds += identity_right_stack_seconds;
        }

        void reset_counters() {
            left_stack_hits = 0;
            left_stack_builds = 0;
            right_stack_hits = 0;
            right_stack_builds = 0;
            identity_left_stack_hits = 0;
            identity_left_stack_builds = 0;
            identity_right_stack_hits = 0;
            identity_right_stack_builds = 0;
            direct_w1_misses = 0;
            direct_active_misses = 0;
            direct_w2_ptr_misses = 0;
            direct_w2_pair_misses = 0;
            direct_f_ptr_misses = 0;
            direct_f_pair_misses = 0;
            direct_layout_ptr_misses = 0;
            direct_layout_pair_misses = 0;
            identity_f_ptr_misses = 0;
            identity_f_pair_misses = 0;
            identity_layout_ptr_misses = 0;
            identity_layout_pair_misses = 0;
            left_stack_seconds = 0.0;
            right_stack_seconds = 0.0;
            identity_left_stack_seconds = 0.0;
            identity_right_stack_seconds = 0.0;
        }
    };

    struct PyObjectKey {
        py::object object;
        Py_hash_t hash;
    };

    struct PyObjectKeyHash {
        size_t operator()(const PyObjectKey& key) const {
            return static_cast<size_t>(key.hash);
        }
    };

    struct PyObjectKeyEq {
        bool operator()(const PyObjectKey& left, const PyObjectKey& right) const {
            if (left.hash != right.hash) {
                return false;
            }
            int eq = PyObject_RichCompareBool(
                left.object.ptr(),
                right.object.ptr(),
                Py_EQ
            );
            if (eq < 0) {
                throw py::error_already_set();
            }
            return eq == 1;
        }
    };

    struct PyPairKey {
        py::object first;
        py::object second;
        Py_hash_t first_hash;
        Py_hash_t second_hash;
    };

    struct PyPairKeyHash {
        size_t operator()(const PyPairKey& key) const {
            size_t seed = static_cast<size_t>(key.first_hash);
            seed ^= static_cast<size_t>(key.second_hash)
                + 0x9e3779b97f4a7c15ULL
                + (seed << 6)
                + (seed >> 2);
            return seed;
        }
    };

    struct PyPairKeyEq {
        bool operator()(const PyPairKey& left, const PyPairKey& right) const {
            if (
                left.first_hash != right.first_hash
                || left.second_hash != right.second_hash
            ) {
                return false;
            }
            int first_eq = PyObject_RichCompareBool(
                left.first.ptr(),
                right.first.ptr(),
                Py_EQ
            );
            if (first_eq < 0) {
                throw py::error_already_set();
            }
            if (first_eq != 1) {
                return false;
            }
            int second_eq = PyObject_RichCompareBool(
                left.second.ptr(),
                right.second.ptr(),
                Py_EQ
            );
            if (second_eq < 0) {
                throw py::error_already_set();
            }
            return second_eq == 1;
        }
    };

    struct PyQuadKey {
        py::object q0;
        py::object q1;
        py::object q2;
        py::object q3;
        std::array<Py_hash_t, 4> hashes;
    };

    struct PyQuadKeyHash {
        size_t operator()(const PyQuadKey& key) const {
            size_t seed = static_cast<size_t>(key.hashes[0]);
            for (size_t index = 1; index < key.hashes.size(); ++index) {
                seed ^= static_cast<size_t>(key.hashes[index])
                    + 0x9e3779b97f4a7c15ULL
                    + (seed << 6)
                    + (seed >> 2);
            }
            return seed;
        }
    };

    struct PyQuadKeyEq {
        bool operator()(const PyQuadKey& left, const PyQuadKey& right) const {
            if (left.hashes != right.hashes) {
                return false;
            }
            const PyObject* left_objs[4] = {
                left.q0.ptr(),
                left.q1.ptr(),
                left.q2.ptr(),
                left.q3.ptr(),
            };
            const PyObject* right_objs[4] = {
                right.q0.ptr(),
                right.q1.ptr(),
                right.q2.ptr(),
                right.q3.ptr(),
            };
            for (size_t index = 0; index < 4; ++index) {
                int eq = PyObject_RichCompareBool(
                    const_cast<PyObject*>(left_objs[index]),
                    const_cast<PyObject*>(right_objs[index]),
                    Py_EQ
                );
                if (eq < 0) {
                    throw py::error_already_set();
                }
                if (eq != 1) {
                    return false;
                }
            }
            return true;
        }
    };

