static py::int_ dict_put_many_values(
    py::dict entries,
    py::sequence keys,
    py::sequence values,
    py::object family_counts = py::none(),
    py::object family_name = py::none()
) {
    const ssize_t n_keys = static_cast<ssize_t>(py::len(keys));
    const ssize_t n_values = static_cast<ssize_t>(py::len(values));
    const ssize_t n_items = std::min(n_keys, n_values);
    ssize_t stored = 0;
    const bool count_family = !family_counts.is_none() && !family_name.is_none();
    std::string family;
    py::dict family_dict;
    if (count_family) {
        family = py::str(family_name).cast<std::string>();
        family_dict = family_counts.cast<py::dict>();
    }
    for (ssize_t idx = 0; idx < n_items; ++idx) {
        py::object key = py::reinterpret_borrow<py::object>(keys[idx]);
        py::object value = py::reinterpret_borrow<py::object>(values[idx]);
        const bool is_new = !entries.contains(key);
        entries[key] = value;
        if (!is_new) {
            continue;
        }
        ++stored;
        if (count_family) {
            ssize_t current = 0;
            py::str family_key(family);
            if (family_dict.contains(family_key)) {
                current = py::cast<ssize_t>(family_dict[family_key]);
            }
            family_dict[family_key] = py::int_(current + 1);
        }
    }
    return py::int_(stored);
}

static py::tuple dict_put_many_packed(
    py::dict entries,
    py::dict ids,
    py::list payloads,
    py::sequence keys,
    py::sequence values,
    bool require_contextual_pair,
    bool count_stored_on_change_only,
    py::object family_counts = py::none(),
    py::object family_name = py::none()
) {
    const ssize_t n_keys = static_cast<ssize_t>(py::len(keys));
    const ssize_t n_values = static_cast<ssize_t>(py::len(values));
    const ssize_t n_items = std::min(n_keys, n_values);
    ssize_t stored = 0;
    ssize_t puts = 0;
    ssize_t block_delta = 0;
    const bool count_family = !family_counts.is_none() && !family_name.is_none();
    std::string family;
    py::dict family_dict;
    if (count_family) {
        family = py::str(family_name).cast<std::string>();
        family_dict = family_counts.cast<py::dict>();
    }
    for (ssize_t idx = 0; idx < n_items; ++idx) {
        py::object key = py::reinterpret_borrow<py::object>(keys[idx]);
        py::object value = py::reinterpret_borrow<py::object>(values[idx]);
        if (value.is_none()) {
            continue;
        }
        if (require_contextual_pair && !is_contextual_packed_pair(value)) {
            continue;
        }
        py::object previous = py::none();
        const bool had_previous = entries.contains(key);
        if (had_previous) {
            previous = py::reinterpret_borrow<py::object>(entries[key]);
            block_delta -= packed_payload_block_count(previous);
        }
        ssize_t table_id = -1;
        if (had_previous) {
            table_id = py::cast<ssize_t>(ids[key]);
        } else if (ids.contains(key)) {
            table_id = py::cast<ssize_t>(ids[key]);
            while (static_cast<ssize_t>(py::len(payloads)) <= table_id) {
                payloads.append(py::none());
            }
        } else {
            table_id = static_cast<ssize_t>(py::len(payloads));
            ids[key] = py::int_(table_id);
            payloads.append(py::none());
        }
        payloads[py::int_(table_id)] = value;
        entries[key] = value;
        block_delta += packed_payload_block_count(value);
        ++puts;
        if (count_stored_on_change_only) {
            if (!had_previous || previous.ptr() != value.ptr()) {
                ++stored;
            }
        } else {
            ++stored;
        }
        if (!had_previous && count_family) {
            ssize_t current = 0;
            py::str family_key(family);
            if (family_dict.contains(family_key)) {
                current = py::cast<ssize_t>(family_dict[family_key]);
            }
            family_dict[family_key] = py::int_(current + 1);
        }
    }
    return py::make_tuple(
        py::int_(stored),
        py::int_(block_delta),
        py::int_(puts)
    );
}

