static py::tuple contextual_left_finalize_batch(
    py::dict pattern_items,
    py::list results,
    py::dict prefix_cache,
    py::object shared_prefix_key_fn,
    ssize_t revision,
    py::object token,
    ssize_t bond,
    py::object zero_qn,
    py::object site_operator_fn,
    py::object initial_fn,
    py::object pack_result_fn,
    py::dict env_cache,
    py::list table_put_keys,
    py::list table_put_values
) {
    ssize_t built_results = 0;
    ssize_t shared_hits = 0;
    for (auto item : pattern_items) {
        py::object pattern = py::reinterpret_borrow<py::object>(item.first);
        py::sequence rows = py::reinterpret_borrow<py::sequence>(item.second);
        py::object env = py::none();
        py::object qns = py::make_tuple(zero_qn);
        if (bond != 0) {
            py::object prefix_key = py::make_tuple(py::int_(revision), token, pattern);
            py::object entry = py::none();
            if (prefix_cache.contains(prefix_key)) {
                entry = py::reinterpret_borrow<py::object>(prefix_cache[prefix_key]);
            } else {
                py::object shared_key = contextual_left_shared_prefix_key(
                    shared_prefix_key_fn,
                    pattern,
                    revision
                );
                if (prefix_cache.contains(shared_key)) {
                    entry = py::reinterpret_borrow<py::object>(prefix_cache[shared_key]);
                    prefix_cache[prefix_key] = entry;
                    ++shared_hits;
                }
            }
            if (entry.is_none()) {
                continue;
            }
            py::sequence entry_seq = entry.cast<py::sequence>();
            env = py::reinterpret_borrow<py::object>(entry_seq[1]);
            qns = py::reinterpret_borrow<py::object>(entry_seq[2]);
        }
        const ssize_t n_rows = static_cast<ssize_t>(py::len(rows));
        for (ssize_t ridx = 0; ridx < n_rows; ++ridx) {
            py::sequence row = py::reinterpret_borrow<py::sequence>(rows[ridx]);
            const ssize_t out_idx = py::cast<ssize_t>(row[0]);
            py::object local_piece = py::reinterpret_borrow<py::object>(row[1]);
            py::object cache_key = py::reinterpret_borrow<py::object>(row[2]);
            py::object table_key = py::reinterpret_borrow<py::object>(row[3]);
            py::object w_local = site_operator_fn(local_piece, py::int_(bond), qns);
            if (w_local.is_none()) {
                continue;
            }
            py::object pair;
            if (env.is_none()) {
                py::object initial = initial_fn(w_local);
                pair = py::make_tuple(initial, w_local);
            } else {
                pair = py::make_tuple(env, w_local);
            }
            py::object result = pack_result_fn(pair);
            env_cache[cache_key] = result;
            table_put_keys.append(table_key);
            table_put_values.append(result);
            results[py::int_(out_idx)] = result;
            ++built_results;
        }
    }
    return py::make_tuple(py::int_(built_results), py::int_(shared_hits));
}

static py::object tuple_from_sequence_object(const py::object& value) {
    PyObject* tuple = PySequence_Tuple(value.ptr());
    if (tuple == nullptr) {
        throw py::error_already_set();
    }
    return py::reinterpret_steal<py::object>(tuple);
}

static py::object sequence_slice_tuple(const py::object& value, ssize_t start, ssize_t stop) {
    PyObject* sliced = PySequence_GetSlice(value.ptr(), start, stop);
    if (sliced == nullptr) {
        throw py::error_already_set();
    }
    py::object sliced_obj = py::reinterpret_steal<py::object>(sliced);
    return tuple_from_sequence_object(sliced_obj);
}

static py::object contextual_left_shared_prefix_key(
    const py::object& key_spec,
    const py::object& pattern,
    ssize_t revision
) {
    if (PyCallable_Check(key_spec.ptr())) {
        return key_spec(pattern);
    }
    py::object site_revisions = tuple_from_sequence_object(key_spec);
    const ssize_t n = static_cast<ssize_t>(py::len(pattern));
    return py::make_tuple(
        py::str("shared_left_prefix"),
        py::int_(revision),
        pattern,
        sequence_slice_tuple(site_revisions, 0, n)
    );
}

static py::object contextual_right_shared_suffix_key(
    const py::object& key_spec,
    const py::object& suffix,
    ssize_t revision
) {
    if (PyCallable_Check(key_spec.ptr())) {
        return key_spec(suffix);
    }
    py::sequence spec = key_spec.cast<py::sequence>();
    py::object site_revisions = py::reinterpret_borrow<py::object>(spec[0]);
    py::object target = py::int_(0);
    if (static_cast<ssize_t>(py::len(spec)) > 1) {
        target = py::reinterpret_borrow<py::object>(spec[1]);
    }
    const ssize_t n_sites = static_cast<ssize_t>(py::len(site_revisions));
    const ssize_t n = static_cast<ssize_t>(py::len(suffix));
    const ssize_t start = std::max<ssize_t>(0, n_sites - n);
    return py::make_tuple(
        py::str("shared_right_suffix"),
        py::int_(revision),
        suffix,
        sequence_slice_tuple(site_revisions, start, n_sites),
        target
    );
}

static py::tuple contextual_probe_local_table_cache(
    py::sequence local_rows,
    py::dict cache,
    const std::string& side,
    py::object target = py::none()
) {
    py::dict local_table;
    py::list missing_rows;
    ssize_t hits = 0;
    ssize_t misses = 0;
    ssize_t duplicates = 0;
    const bool is_right = side == "right";
    const ssize_t n_rows = static_cast<ssize_t>(py::len(local_rows));
    for (ssize_t idx = 0; idx < n_rows; ++idx) {
        py::sequence row = py::reinterpret_borrow<py::sequence>(local_rows[idx]);
        py::object local_key = py::reinterpret_borrow<py::object>(row[0]);
        if (local_table.contains(local_key)) {
            ++duplicates;
            continue;
        }
        py::object local_piece = py::reinterpret_borrow<py::object>(row[1]);
        ssize_t site = py::cast<ssize_t>(row[2]);
        py::object qns = tuple_from_sequence_object(
            py::reinterpret_borrow<py::object>(row[3])
        );
        py::object cache_key;
        if (is_right) {
            cache_key = py::make_tuple(
                py::str("right"),
                py::str(local_piece),
                py::int_(site),
                qns,
                target
            );
        } else {
            cache_key = py::make_tuple(
                py::str("left"),
                py::str(local_piece),
                py::int_(site),
                qns
            );
        }
        if (cache.contains(cache_key)) {
            local_table[local_key] =
                py::reinterpret_borrow<py::object>(cache[cache_key]);
            ++hits;
            continue;
        }
        missing_rows.append(row);
        ++misses;
    }
    return py::make_tuple(
        local_table,
        tuple_from_sequence_object(missing_rows),
        py::int_(hits),
        py::int_(misses),
        py::int_(duplicates)
    );
}

static py::tuple contextual_fill_local_table_cache_misses(
    py::sequence local_rows,
    py::dict cache,
    py::dict local_table,
    const std::string& side,
    py::object site_operator_fn,
    py::object initial_fn,
    py::object target = py::none()
) {
    ssize_t hits = 0;
    ssize_t builds = 0;
    ssize_t skipped = 0;
    bool complete = true;
    const bool is_right = side == "right";
    const ssize_t n_rows = static_cast<ssize_t>(py::len(local_rows));
    for (ssize_t idx = 0; idx < n_rows; ++idx) {
        py::sequence row = py::reinterpret_borrow<py::sequence>(local_rows[idx]);
        py::object local_key = py::reinterpret_borrow<py::object>(row[0]);
        if (local_table.contains(local_key)) {
            ++skipped;
            continue;
        }
        py::object local_piece = py::reinterpret_borrow<py::object>(row[1]);
        ssize_t site = py::cast<ssize_t>(row[2]);
        py::object qns = tuple_from_sequence_object(
            py::reinterpret_borrow<py::object>(row[3])
        );
        py::object cache_key;
        if (is_right) {
            cache_key = py::make_tuple(
                py::str("right"),
                py::str(local_piece),
                py::int_(site),
                qns,
                target
            );
        } else {
            cache_key = py::make_tuple(
                py::str("left"),
                py::str(local_piece),
                py::int_(site),
                qns
            );
        }
        if (cache.contains(cache_key)) {
            local_table[local_key] =
                py::reinterpret_borrow<py::object>(cache[cache_key]);
            ++hits;
            continue;
        }
        py::object w_local = site_operator_fn(local_piece, py::int_(site), qns);
        if (w_local.is_none()) {
            complete = false;
            break;
        }
        py::object cached_local = py::make_tuple(w_local, initial_fn(w_local));
        cache[cache_key] = cached_local;
        local_table[local_key] = cached_local;
        ++builds;
    }
    return py::make_tuple(
        local_table,
        py::bool_(complete),
        py::int_(hits),
        py::int_(builds),
        py::int_(skipped)
    );
}

static py::tuple contextual_partition_pending_rows(
    py::sequence pending_rows,
    py::dict env_cache,
    py::list results,
    py::dict pattern_items,
    py::list advance_rows,
    py::list table_put_keys,
    py::list table_put_values,
    const std::string& side,
    ssize_t revision,
    py::object token,
    bool has_previous_table,
    bool emit_table_puts
) {
    ssize_t env_hits = 0;
    ssize_t advance_candidates = 0;
    ssize_t pattern_rows = 0;
    const bool is_right = side == "right";
    const ssize_t n_rows = static_cast<ssize_t>(py::len(pending_rows));
    for (ssize_t ridx = 0; ridx < n_rows; ++ridx) {
        py::sequence row = py::reinterpret_borrow<py::sequence>(pending_rows[ridx]);
        ssize_t out_idx = py::cast<ssize_t>(row[0]);
        py::object pattern = py::reinterpret_borrow<py::object>(row[1]);
        py::object local_piece = py::reinterpret_borrow<py::object>(row[2]);
        py::object table_key = py::make_tuple(pattern, local_piece);
        py::object cache_key = py::make_tuple(
            py::int_(revision),
            token,
            pattern,
            local_piece
        );
        if (env_cache.contains(cache_key)) {
            py::object cached = py::reinterpret_borrow<py::object>(
                env_cache[cache_key]
            );
            results[py::int_(out_idx)] = cached;
            if (emit_table_puts) {
                table_put_keys.append(table_key);
                table_put_values.append(cached);
            }
            ++env_hits;
            continue;
        }
        const ssize_t pattern_len = static_cast<ssize_t>(py::len(pattern));
        if (has_previous_table && pattern_len > 0) {
            py::sequence pattern_seq = py::reinterpret_borrow<py::sequence>(pattern);
            py::object parent_key;
            if (is_right) {
                parent_key = py::make_tuple(
                    sequence_slice_tuple(pattern, 1, pattern_len),
                    py::str(pattern_seq[0])
                );
            } else {
                parent_key = py::make_tuple(
                    sequence_slice_tuple(pattern, 0, pattern_len - 1),
                    py::str(pattern_seq[pattern_len - 1])
                );
            }
            advance_rows.append(py::make_tuple(
                py::int_(out_idx),
                pattern,
                local_piece,
                cache_key,
                table_key,
                parent_key
            ));
            ++advance_candidates;
            continue;
        }
        if (!pattern_items.contains(pattern)) {
            pattern_items[pattern] = py::list();
        }
        py::object bucket_obj = py::reinterpret_borrow<py::object>(
            pattern_items[pattern]
        );
        bucket_obj.attr("append")(py::make_tuple(
            py::int_(out_idx),
            local_piece,
            cache_key,
            table_key
        ));
        ++pattern_rows;
    }
    return py::make_tuple(
        py::int_(env_hits),
        py::int_(advance_candidates),
        py::int_(pattern_rows),
        py::int_(py::len(pattern_items))
    );
}

static py::array_t<cdouble> scalar_block4(cdouble coeff) {
    py::array_t<cdouble> block({1, 1, 1, 1});
    auto r = block.mutable_unchecked<4>();
    r(0, 0, 0, 0) = coeff;
    return block;
}

static py::array_t<cdouble> scalar_block3(cdouble coeff) {
    py::array_t<cdouble> block({1, 1, 1});
    auto r = block.mutable_unchecked<3>();
    r(0, 0, 0) = coeff;
    return block;
}

static py::object py_number_add(const py::object& lhs, const py::object& rhs) {
    PyObject* raw = PyNumber_Add(lhs.ptr(), rhs.ptr());
    if (raw == nullptr) {
        throw py::error_already_set();
    }
    return py::reinterpret_steal<py::object>(raw);
}

static py::object py_number_subtract(const py::object& lhs, const py::object& rhs) {
    PyObject* raw = PyNumber_Subtract(lhs.ptr(), rhs.ptr());
    if (raw == nullptr) {
        throw py::error_already_set();
    }
    return py::reinterpret_steal<py::object>(raw);
}

static py::tuple packed_site_operator_from_left_payload(
    py::sequence local_entries,
    py::sequence phys_qns,
    py::sequence left_qns
) {
    py::list keys;
    py::list blocks;
    py::set right_qns;
    const ssize_t n_left = static_cast<ssize_t>(py::len(left_qns));
    const ssize_t n_entries = static_cast<ssize_t>(py::len(local_entries));
    for (ssize_t il = 0; il < n_left; ++il) {
        py::object q_left = py::reinterpret_borrow<py::object>(left_qns[il]);
        for (ssize_t ie = 0; ie < n_entries; ++ie) {
            py::sequence entry = py::reinterpret_borrow<py::sequence>(local_entries[ie]);
            py::object q_out = py::reinterpret_borrow<py::object>(entry[0]);
            py::object q_in = py::reinterpret_borrow<py::object>(entry[1]);
            py::object flux = py::reinterpret_borrow<py::object>(entry[2]);
            cdouble coeff = py::cast<cdouble>(entry[3]);
            py::object q_right = py_number_subtract(q_left, flux);
            right_qns.add(q_right);
            keys.append(py::make_tuple(q_left, q_right, q_out, q_in));
            blocks.append(scalar_block4(coeff));
        }
    }
    if (py::len(keys) == 0) {
        return py::make_tuple(py::none(), py::none(), py::none(), py::none());
    }
    py::object sorted_right_qns = py::module_::import("builtins").attr("sorted")(right_qns);
    py::list qns;
    qns.append(tuple_from_sequence_object(left_qns));
    qns.append(sorted_right_qns);
    qns.append(tuple_from_sequence_object(phys_qns));
    qns.append(tuple_from_sequence_object(phys_qns));
    py::list dirs;
    dirs.append(py::int_(-1));
    dirs.append(py::int_(1));
    dirs.append(py::int_(1));
    dirs.append(py::int_(-1));
    return py::make_tuple(
        tuple_from_sequence_object(keys),
        tuple_from_sequence_object(blocks),
        qns,
        dirs
    );
}

static py::tuple packed_site_operator_from_right_payload(
    py::sequence local_entries,
    py::sequence phys_qns,
    py::sequence right_qns
) {
    py::list keys;
    py::list blocks;
    py::set left_qns;
    const ssize_t n_right = static_cast<ssize_t>(py::len(right_qns));
    const ssize_t n_entries = static_cast<ssize_t>(py::len(local_entries));
    for (ssize_t ir = 0; ir < n_right; ++ir) {
        py::object q_right = py::reinterpret_borrow<py::object>(right_qns[ir]);
        for (ssize_t ie = 0; ie < n_entries; ++ie) {
            py::sequence entry = py::reinterpret_borrow<py::sequence>(local_entries[ie]);
            py::object q_out = py::reinterpret_borrow<py::object>(entry[0]);
            py::object q_in = py::reinterpret_borrow<py::object>(entry[1]);
            py::object flux = py::reinterpret_borrow<py::object>(entry[2]);
            cdouble coeff = py::cast<cdouble>(entry[3]);
            py::object q_left = py_number_add(q_right, flux);
            left_qns.add(q_left);
            keys.append(py::make_tuple(q_left, q_right, q_out, q_in));
            blocks.append(scalar_block4(coeff));
        }
    }
    if (py::len(keys) == 0) {
        return py::make_tuple(py::none(), py::none(), py::none(), py::none());
    }
    py::object sorted_left_qns = py::module_::import("builtins").attr("sorted")(left_qns);
    py::list qns;
    qns.append(sorted_left_qns);
    qns.append(tuple_from_sequence_object(right_qns));
    qns.append(tuple_from_sequence_object(phys_qns));
    qns.append(tuple_from_sequence_object(phys_qns));
    py::list dirs;
    dirs.append(py::int_(-1));
    dirs.append(py::int_(1));
    dirs.append(py::int_(1));
    dirs.append(py::int_(-1));
    return py::make_tuple(
        tuple_from_sequence_object(keys),
        tuple_from_sequence_object(blocks),
        qns,
        dirs
    );
}

static py::tuple packed_initial_left_environment_payload(py::object zero_qn) {
    py::list qns;
    qns.append(py::make_tuple(zero_qn));
    qns.append(py::make_tuple(zero_qn));
    qns.append(py::make_tuple(zero_qn));
    py::list dirs;
    dirs.append(py::int_(1));
    dirs.append(py::int_(-1));
    dirs.append(py::int_(1));
    return py::make_tuple(
        py::make_tuple(py::make_tuple(zero_qn, zero_qn, zero_qn)),
        py::make_tuple(scalar_block3(cdouble(1.0, 0.0))),
        qns,
        dirs
    );
}

static py::tuple packed_initial_right_environment_payload(py::object zero_qn, py::object target_qn) {
    py::list qns;
    qns.append(py::make_tuple(zero_qn));
    qns.append(py::make_tuple(target_qn));
    qns.append(py::make_tuple(target_qn));
    py::list dirs;
    dirs.append(py::int_(-1));
    dirs.append(py::int_(1));
    dirs.append(py::int_(-1));
    return py::make_tuple(
        py::make_tuple(py::make_tuple(zero_qn, target_qn, target_qn)),
        py::make_tuple(scalar_block3(cdouble(1.0, 0.0))),
        qns,
        dirs
    );
}

static py::tuple contextual_left_prefix_closure(py::sequence patterns) {
    ssize_t max_len = 0;
    const ssize_t n_patterns = static_cast<ssize_t>(py::len(patterns));
    for (ssize_t i = 0; i < n_patterns; ++i) {
        py::object pattern = py::reinterpret_borrow<py::object>(patterns[i]);
        max_len = std::max(max_len, static_cast<ssize_t>(py::len(pattern)));
    }
    std::vector<py::dict> levels;
    levels.reserve(static_cast<size_t>(max_len + 1));
    for (ssize_t i = 0; i <= max_len; ++i) {
        levels.emplace_back();
    }
    for (ssize_t i = 0; i < n_patterns; ++i) {
        py::object pattern = py::reinterpret_borrow<py::object>(patterns[i]);
        const ssize_t n = static_cast<ssize_t>(py::len(pattern));
        for (ssize_t length = 1; length <= n; ++length) {
            py::object prefix = sequence_slice_tuple(pattern, 0, length);
            levels[static_cast<size_t>(length)][prefix] = py::none();
        }
    }
    py::list out;
    for (ssize_t length = 1; length <= max_len; ++length) {
        for (auto item : levels[static_cast<size_t>(length)]) {
            out.append(py::reinterpret_borrow<py::object>(item.first));
        }
    }
    return tuple_from_sequence_object(out).cast<py::tuple>();
}

static py::tuple contextual_right_suffix_closure(py::sequence patterns) {
    ssize_t max_len = 0;
    const ssize_t n_patterns = static_cast<ssize_t>(py::len(patterns));
    for (ssize_t i = 0; i < n_patterns; ++i) {
        py::object pattern = py::reinterpret_borrow<py::object>(patterns[i]);
        max_len = std::max(max_len, static_cast<ssize_t>(py::len(pattern)));
    }
    std::vector<py::dict> levels;
    levels.reserve(static_cast<size_t>(max_len + 1));
    for (ssize_t i = 0; i <= max_len; ++i) {
        levels.emplace_back();
    }
    for (ssize_t i = 0; i < n_patterns; ++i) {
        py::object pattern = py::reinterpret_borrow<py::object>(patterns[i]);
        const ssize_t n = static_cast<ssize_t>(py::len(pattern));
        for (ssize_t length = 1; length <= n; ++length) {
            py::object suffix = sequence_slice_tuple(pattern, n - length, n);
            levels[static_cast<size_t>(length)][suffix] = py::none();
        }
    }
    py::list out;
    for (ssize_t length = 1; length <= max_len; ++length) {
        for (auto item : levels[static_cast<size_t>(length)]) {
            out.append(py::reinterpret_borrow<py::object>(item.first));
        }
    }
    return tuple_from_sequence_object(out).cast<py::tuple>();
}

static bool set_contains_object(py::set values, const py::object& key) {
    const int result = PySet_Contains(values.ptr(), key.ptr());
    if (result < 0) {
        throw py::error_already_set();
    }
    return result != 0;
}

static void set_add_object(py::set values, const py::object& key) {
    if (PySet_Add(values.ptr(), key.ptr()) < 0) {
        throw py::error_already_set();
    }
}

static py::tuple contextual_prepare_boundary_build_wave(
    py::sequence patterns,
    py::dict boundary_cache,
    py::object shared_key_spec,
    ssize_t revision,
    py::object token,
    py::set failed_boundaries,
    const std::string& side,
    ssize_t n_sites,
    ssize_t suffix_start = 0
) {
    const bool is_right = side == "right";
    py::tuple closure = is_right
        ? contextual_right_suffix_closure(patterns)
        : contextual_left_prefix_closure(patterns);
    py::list rows;
    ssize_t shared_hits = 0;
    ssize_t cached = 0;
    ssize_t deferred = 0;
    ssize_t inherited_failures = 0;
    ssize_t site_skips = 0;
    ssize_t failed_skips = 0;
    const ssize_t n_closure = static_cast<ssize_t>(py::len(closure));
    for (ssize_t idx = 0; idx < n_closure; ++idx) {
        py::object boundary = py::reinterpret_borrow<py::object>(closure[idx]);
        if (set_contains_object(failed_boundaries, boundary)) {
            ++failed_skips;
            continue;
        }
        py::object boundary_key = py::make_tuple(py::int_(revision), token, boundary);
        if (boundary_cache.contains(boundary_key)) {
            ++cached;
            continue;
        }
        py::object shared_key = is_right
            ? contextual_right_shared_suffix_key(shared_key_spec, boundary, revision)
            : contextual_left_shared_prefix_key(shared_key_spec, boundary, revision);
        if (boundary_cache.contains(shared_key)) {
            boundary_cache[boundary_key] =
                py::reinterpret_borrow<py::object>(boundary_cache[shared_key]);
            ++shared_hits;
            continue;
        }
        const ssize_t n = static_cast<ssize_t>(py::len(boundary));
        py::sequence boundary_seq = py::reinterpret_borrow<py::sequence>(boundary);
        py::object parent = is_right
            ? sequence_slice_tuple(boundary, 1, n)
            : sequence_slice_tuple(boundary, 0, n - 1);
        if (set_contains_object(failed_boundaries, parent)) {
            set_add_object(failed_boundaries, boundary);
            ++inherited_failures;
            continue;
        }
        py::object parent_key = py::make_tuple(py::int_(revision), token, parent);
        if (!boundary_cache.contains(parent_key)) {
            ++deferred;
            continue;
        }
        const ssize_t site = is_right ? n_sites - n : n - 1;
        if (is_right && site < suffix_start) {
            set_add_object(failed_boundaries, boundary);
            ++site_skips;
            continue;
        }
        py::object piece = is_right
            ? py::reinterpret_borrow<py::object>(boundary_seq[0])
            : py::reinterpret_borrow<py::object>(boundary_seq[n - 1]);
        rows.append(py::make_tuple(
            boundary,
            boundary_key,
            shared_key,
            parent,
            py::reinterpret_borrow<py::object>(boundary_cache[parent_key]),
            py::int_(site),
            piece
        ));
    }
    return py::make_tuple(
        tuple_from_sequence_object(rows),
        py::int_(shared_hits),
        py::int_(cached),
        py::int_(deferred),
        py::int_(inherited_failures),
        py::int_(site_skips),
        py::int_(failed_skips),
        py::int_(n_closure)
    );
}

static py::tuple contextual_execute_boundary_build_wave(
    py::sequence rows,
    py::dict boundary_cache,
    py::set failed_boundaries,
    const std::string& side,
    py::object zero_qn,
    py::object identity_advance_fn,
    py::object site_operator_fn,
    py::object initial_fn,
    py::object contract_fn
) {
    const bool is_right = side == "right";
    ssize_t built = 0;
    ssize_t identity_built = 0;
    ssize_t generic_built = 0;
    ssize_t failures = 0;
    const ssize_t n_rows = static_cast<ssize_t>(py::len(rows));
    for (ssize_t idx = 0; idx < n_rows; ++idx) {
        py::sequence row = py::reinterpret_borrow<py::sequence>(rows[idx]);
        py::object boundary = py::reinterpret_borrow<py::object>(row[0]);
        py::object boundary_key = py::reinterpret_borrow<py::object>(row[1]);
        py::object shared_key = py::reinterpret_borrow<py::object>(row[2]);
        py::sequence parent_entry = py::reinterpret_borrow<py::sequence>(row[4]);
        ssize_t site = py::cast<ssize_t>(row[5]);
        py::object piece = py::reinterpret_borrow<py::object>(row[6]);
        py::object env = py::reinterpret_borrow<py::object>(parent_entry[1]);
        py::object qns = py::make_tuple(zero_qn);
        if (!env.is_none()) {
            qns = tuple_from_sequence_object(
                py::reinterpret_borrow<py::object>(parent_entry[2])
            );
        }
        try {
            if (!env.is_none() && py::str(piece).cast<std::string>() == "I") {
                py::object env_next = identity_advance_fn(py::int_(site), env);
                if (!env_next.is_none()) {
                    py::object next_qns = get_axis_item(env_next.attr("qns"), 0);
                    py::object entry = is_right
                        ? py::make_tuple(py::int_(site), env_next, next_qns)
                        : py::make_tuple(py::int_(site + 1), env_next, next_qns);
                    boundary_cache[boundary_key] = entry;
                    boundary_cache[shared_key] = entry;
                    ++built;
                    ++identity_built;
                    continue;
                }
            }
            py::object w_local = site_operator_fn(piece, py::int_(site), qns);
            if (w_local.is_none()) {
                set_add_object(failed_boundaries, boundary);
                ++failures;
                continue;
            }
            py::object env_in = env.is_none() ? initial_fn(w_local) : env;
            py::object env_next = contract_fn(w_local, py::int_(site), env_in);
            if (env_next.is_none()) {
                set_add_object(failed_boundaries, boundary);
                ++failures;
                continue;
            }
            py::object next_qns = get_axis_item(env_next.attr("qns"), 0);
            py::object entry = is_right
                ? py::make_tuple(py::int_(site), env_next, next_qns)
                : py::make_tuple(py::int_(site + 1), env_next, next_qns);
            boundary_cache[boundary_key] = entry;
            boundary_cache[shared_key] = entry;
            ++built;
            ++generic_built;
        } catch (const py::error_already_set&) {
            PyErr_Clear();
            set_add_object(failed_boundaries, boundary);
            ++failures;
        } catch (const std::exception&) {
            set_add_object(failed_boundaries, boundary);
            ++failures;
        }
    }
    return py::make_tuple(
        py::int_(built),
        py::int_(identity_built),
        py::int_(generic_built),
        py::int_(failures),
        py::int_(n_rows)
    );
}

static py::object packed_tensor_from_payload(
    py::object tensor_cls,
    py::tuple payload,
    const std::string& source
) {
    py::sequence seq = payload.cast<py::sequence>();
    py::object keys = py::reinterpret_borrow<py::object>(seq[0]);
    if (keys.is_none()) {
        return py::none();
    }
    py::object blocks = py::reinterpret_borrow<py::object>(seq[1]);
    py::object qns = py::reinterpret_borrow<py::object>(seq[2]);
    py::object dirs = py::reinterpret_borrow<py::object>(seq[3]);
    return tensor_cls(
        keys,
        blocks,
        py::arg("dirs") = dirs,
        py::arg("qns") = qns,
        py::arg("source") = py::str(source),
        py::arg("assume_unique") = true
    );
}

static py::object first_axis_qn_or(
    py::object tensor,
    ssize_t axis,
    py::object fallback
) {
    try {
        py::object qns = py::getattr(tensor, "qns", py::none());
        if (!qns.is_none()) {
            py::sequence axes = qns.cast<py::sequence>();
            if (axis >= 0 && axis < static_cast<ssize_t>(py::len(axes))) {
                py::object axis_qns = py::reinterpret_borrow<py::object>(axes[axis]);
                if (!axis_qns.is_none() && static_cast<ssize_t>(py::len(axis_qns)) > 0) {
                    py::sequence axis_seq = axis_qns.cast<py::sequence>();
                    return py::reinterpret_borrow<py::object>(axis_seq[0]);
                }
            }
        }
    } catch (const py::error_already_set&) {
        PyErr_Clear();
    }
    return fallback;
}

static py::tuple contextual_execute_boundary_build_wave_packed(
    py::sequence rows,
    py::dict boundary_cache,
    py::set failed_boundaries,
    const std::string& side,
    py::object zero_qn,
    py::object target_qn,
    py::dict site_operator_cache,
    py::dict local_entries_cache,
    py::object tensor_cls,
    py::sequence site_a_conj,
    py::sequence site_b,
    py::object zero_like_fn = py::none()
) {
    const bool is_right = side == "right";
    const ssize_t n_rows = static_cast<ssize_t>(py::len(rows));
    ssize_t unsupported = 0;
    for (ssize_t idx = 0; idx < n_rows; ++idx) {
        py::sequence row = py::reinterpret_borrow<py::sequence>(rows[idx]);
        py::sequence parent_entry = py::reinterpret_borrow<py::sequence>(row[4]);
        ssize_t site = py::cast<ssize_t>(row[5]);
        py::object piece = py::reinterpret_borrow<py::object>(row[6]);
        py::object env = py::reinterpret_borrow<py::object>(parent_entry[1]);
        if (site < 0 || site >= static_cast<ssize_t>(py::len(site_a_conj)) ||
            site >= static_cast<ssize_t>(py::len(site_b))) {
            ++unsupported;
            continue;
        }
        if (env.is_none() || py::str(piece).cast<std::string>() != "I") {
            py::object entries_key = py::make_tuple(py::str(piece), py::int_(site));
            if (!local_entries_cache.contains(entries_key)) {
                ++unsupported;
            }
        }
    }
    if (unsupported != 0) {
        return py::make_tuple(
            py::int_(0),
            py::int_(0),
            py::int_(0),
            py::int_(0),
            py::int_(n_rows),
            py::int_(unsupported),
            py::int_(0),
            py::int_(0)
        );
    }

    ssize_t built = 0;
    ssize_t identity_built = 0;
    ssize_t generic_built = 0;
    ssize_t failures = 0;
    ssize_t op_cache_hits = 0;
    ssize_t op_cache_builds = 0;
    const std::string op_source = is_right
        ? "direct_family_site_operator_right"
        : "direct_family_site_operator_left";
    const std::string env_source = is_right
        ? "contextual_native_wave_right_environment"
        : "contextual_native_wave_left_environment";
    for (ssize_t idx = 0; idx < n_rows; ++idx) {
        py::sequence row = py::reinterpret_borrow<py::sequence>(rows[idx]);
        py::object boundary = py::reinterpret_borrow<py::object>(row[0]);
        py::object boundary_key = py::reinterpret_borrow<py::object>(row[1]);
        py::object shared_key = py::reinterpret_borrow<py::object>(row[2]);
        py::sequence parent_entry = py::reinterpret_borrow<py::sequence>(row[4]);
        ssize_t site = py::cast<ssize_t>(row[5]);
        py::object piece = py::reinterpret_borrow<py::object>(row[6]);
        py::object env = py::reinterpret_borrow<py::object>(parent_entry[1]);
        py::object qns = py::make_tuple(zero_qn);
        if (!env.is_none()) {
            qns = tuple_from_sequence_object(
                py::reinterpret_borrow<py::object>(parent_entry[2])
            );
        }
        py::object A_conj = py::reinterpret_borrow<py::object>(site_a_conj[site]);
        py::object B = py::reinterpret_borrow<py::object>(site_b[site]);
        try {
            if (!env.is_none() && py::str(piece).cast<std::string>() == "I") {
                py::tuple payload = is_right
                    ? packed_right_identity_boundary_advance_payload(A_conj, env, B)
                    : packed_left_identity_boundary_advance_payload(A_conj, env, B);
                py::object env_next = packed_tensor_from_payload(
                    tensor_cls,
                    payload,
                    env_source
                );
                if (env_next.is_none()) {
                    set_add_object(failed_boundaries, boundary);
                    ++failures;
                    continue;
                }
                py::object next_qns = get_axis_item(env_next.attr("qns"), 0);
                py::object entry = is_right
                    ? py::make_tuple(py::int_(site), env_next, next_qns)
                    : py::make_tuple(py::int_(site + 1), env_next, next_qns);
                boundary_cache[boundary_key] = entry;
                boundary_cache[shared_key] = entry;
                ++built;
                ++identity_built;
                continue;
            }

            py::object qns_tuple = tuple_from_sequence_object(qns);
            py::object op_key = is_right
                ? py::make_tuple(
                    py::str("packed_right"),
                    py::str(piece),
                    py::int_(site),
                    qns_tuple,
                    py::str(op_source)
                )
                : py::make_tuple(
                    py::str("packed_left"),
                    py::str(piece),
                    py::int_(site),
                    qns_tuple,
                    py::str(op_source)
                );
            py::object w_local = py::none();
            if (site_operator_cache.contains(op_key)) {
                w_local = py::reinterpret_borrow<py::object>(
                    site_operator_cache[op_key]
                );
                ++op_cache_hits;
            } else {
                py::object entries_key = py::make_tuple(py::str(piece), py::int_(site));
                py::sequence entry_data = py::reinterpret_borrow<py::object>(
                    local_entries_cache[entries_key]
                ).cast<py::sequence>();
                py::object local_entries = py::reinterpret_borrow<py::object>(
                    entry_data[0]
                );
                py::object phys_qns = py::reinterpret_borrow<py::object>(entry_data[1]);
                py::tuple payload = is_right
                    ? packed_site_operator_from_right_payload(
                        local_entries,
                        phys_qns,
                        qns_tuple
                    )
                    : packed_site_operator_from_left_payload(
                        local_entries,
                        phys_qns,
                        qns_tuple
                    );
                w_local = packed_tensor_from_payload(tensor_cls, payload, op_source);
                if (w_local.is_none()) {
                    set_add_object(failed_boundaries, boundary);
                    ++failures;
                    continue;
                }
                site_operator_cache[op_key] = w_local;
                ++op_cache_builds;
            }
            py::object env_in = env;
            if (env.is_none()) {
                py::object sample = first_axis_qn_or(
                    w_local,
                    is_right ? 1 : 0,
                    zero_qn
                );
                py::object zero_like = zero_qn;
                if (!zero_like_fn.is_none() && PyCallable_Check(zero_like_fn.ptr())) {
                    zero_like = zero_like_fn(sample);
                }
                py::tuple init_payload = is_right
                    ? packed_initial_right_environment_payload(zero_like, target_qn)
                    : packed_initial_left_environment_payload(zero_like);
                env_in = packed_tensor_from_payload(
                    tensor_cls,
                    init_payload,
                    is_right ? "direct_family_initial_F" : "direct_family_initial_E"
                );
            }
            py::tuple payload = is_right
                ? packed_right_boundary_advance_payload(w_local, A_conj, env_in, B)
                : packed_left_boundary_advance_payload(w_local, A_conj, env_in, B);
            py::object env_next = packed_tensor_from_payload(
                tensor_cls,
                payload,
                env_source
            );
            if (env_next.is_none()) {
                set_add_object(failed_boundaries, boundary);
                ++failures;
                continue;
            }
            py::object next_qns = get_axis_item(env_next.attr("qns"), 0);
            py::object entry = is_right
                ? py::make_tuple(py::int_(site), env_next, next_qns)
                : py::make_tuple(py::int_(site + 1), env_next, next_qns);
            boundary_cache[boundary_key] = entry;
            boundary_cache[shared_key] = entry;
            ++built;
            ++generic_built;
        } catch (const py::error_already_set&) {
            PyErr_Clear();
            set_add_object(failed_boundaries, boundary);
            ++failures;
        } catch (const std::exception&) {
            set_add_object(failed_boundaries, boundary);
            ++failures;
        }
    }
    return py::make_tuple(
        py::int_(built),
        py::int_(identity_built),
        py::int_(generic_built),
        py::int_(failures),
        py::int_(n_rows),
        py::int_(0),
        py::int_(op_cache_hits),
        py::int_(op_cache_builds)
    );
}

