static py::tuple contextual_left_prepare_local_table_batch(
    py::dict pattern_items,
    py::dict prefix_cache,
    py::object shared_prefix_key_fn,
    ssize_t revision,
    py::object token,
    ssize_t bond,
    py::object zero_qn
) {
    py::dict seen;
    py::list rows_out;
    ssize_t shared_hits = 0;
    ssize_t missing_env_rows = 0;
    for (auto item : pattern_items) {
        py::object pattern = py::reinterpret_borrow<py::object>(item.first);
        py::sequence rows = py::reinterpret_borrow<py::sequence>(item.second);
        py::object qns = py::make_tuple(zero_qn);
        if (bond != 0) {
            py::object prefix_key = py::make_tuple(py::int_(revision), token, pattern);
            py::object entry = py::none();
            if (prefix_cache.contains(prefix_key)) {
                entry = py::reinterpret_borrow<py::object>(prefix_cache[prefix_key]);
            } else {
                py::object shared_key = contextual_left_shared_prefix_key(
                    shared_prefix_key_fn,
                    pattern,
                    revision
                );
                if (prefix_cache.contains(shared_key)) {
                    entry = py::reinterpret_borrow<py::object>(prefix_cache[shared_key]);
                    prefix_cache[prefix_key] = entry;
                    ++shared_hits;
                }
            }
            if (entry.is_none()) {
                missing_env_rows += static_cast<ssize_t>(py::len(rows));
                continue;
            }
            py::sequence entry_seq = entry.cast<py::sequence>();
            qns = py::reinterpret_borrow<py::object>(entry_seq[2]);
        }
        py::object qns_key = tuple_from_sequence_object(qns);
        const ssize_t n_rows = static_cast<ssize_t>(py::len(rows));
        for (ssize_t ridx = 0; ridx < n_rows; ++ridx) {
            py::sequence row = py::reinterpret_borrow<py::sequence>(rows[ridx]);
            py::object local_piece = py::reinterpret_borrow<py::object>(row[1]);
            py::object local_key = py::make_tuple(py::str(local_piece), py::int_(bond), qns_key);
            if (seen.contains(local_key)) {
                continue;
            }
            seen[local_key] = py::none();
            rows_out.append(py::make_tuple(local_key, local_piece, py::int_(bond), qns_key));
        }
    }
    return py::make_tuple(
        rows_out,
        py::int_(shared_hits),
        py::int_(missing_env_rows),
        py::int_(py::len(rows_out))
    );
}

static py::tuple contextual_left_finalize_prebuilt_batch(
    py::dict pattern_items,
    py::list results,
    py::dict prefix_cache,
    py::object shared_prefix_key_fn,
    ssize_t revision,
    py::object token,
    ssize_t bond,
    py::object zero_qn,
    py::dict local_table,
    py::dict env_cache,
    py::list table_put_keys,
    py::list table_put_values
) {
    ssize_t built_results = 0;
    ssize_t shared_hits = 0;
    ssize_t local_hits = 0;
    ssize_t local_misses = 0;
    for (auto item : pattern_items) {
        py::object pattern = py::reinterpret_borrow<py::object>(item.first);
        py::sequence rows = py::reinterpret_borrow<py::sequence>(item.second);
        py::object env = py::none();
        py::object qns = py::make_tuple(zero_qn);
        if (bond != 0) {
            py::object prefix_key = py::make_tuple(py::int_(revision), token, pattern);
            py::object entry = py::none();
            if (prefix_cache.contains(prefix_key)) {
                entry = py::reinterpret_borrow<py::object>(prefix_cache[prefix_key]);
            } else {
                py::object shared_key = contextual_left_shared_prefix_key(
                    shared_prefix_key_fn,
                    pattern,
                    revision
                );
                if (prefix_cache.contains(shared_key)) {
                    entry = py::reinterpret_borrow<py::object>(prefix_cache[shared_key]);
                    prefix_cache[prefix_key] = entry;
                    ++shared_hits;
                }
            }
            if (entry.is_none()) {
                continue;
            }
            py::sequence entry_seq = entry.cast<py::sequence>();
            env = py::reinterpret_borrow<py::object>(entry_seq[1]);
            qns = py::reinterpret_borrow<py::object>(entry_seq[2]);
        }
        py::object qns_key = tuple_from_sequence_object(qns);
        const ssize_t n_rows = static_cast<ssize_t>(py::len(rows));
        for (ssize_t ridx = 0; ridx < n_rows; ++ridx) {
            py::sequence row = py::reinterpret_borrow<py::sequence>(rows[ridx]);
            const ssize_t out_idx = py::cast<ssize_t>(row[0]);
            py::object local_piece = py::reinterpret_borrow<py::object>(row[1]);
            py::object cache_key = py::reinterpret_borrow<py::object>(row[2]);
            py::object table_key = py::reinterpret_borrow<py::object>(row[3]);
            py::object local_key = py::make_tuple(py::str(local_piece), py::int_(bond), qns_key);
            if (!local_table.contains(local_key)) {
                ++local_misses;
                continue;
            }
            py::sequence local_entry = py::reinterpret_borrow<py::object>(local_table[local_key]).cast<py::sequence>();
            py::object w_local = py::reinterpret_borrow<py::object>(local_entry[0]);
            py::object initial = py::reinterpret_borrow<py::object>(local_entry[1]);
            py::object result = env.is_none()
                ? py::make_tuple(initial, w_local)
                : py::make_tuple(env, w_local);
            env_cache[cache_key] = result;
            table_put_keys.append(table_key);
            table_put_values.append(result);
            results[py::int_(out_idx)] = result;
            ++built_results;
            ++local_hits;
        }
    }
    return py::make_tuple(
        py::int_(built_results),
        py::int_(shared_hits),
        py::int_(local_hits),
        py::int_(local_misses)
    );
}

static py::tuple contextual_right_finalize_batch(
    py::dict pattern_items,
    py::list results,
    py::dict suffix_cache,
    py::object shared_suffix_key_fn,
    ssize_t revision,
    py::object token,
    ssize_t local_site,
    py::object zero_qn,
    py::object site_operator_fn,
    py::object initial_fn,
    py::object pack_result_fn,
    py::dict env_cache,
    py::list table_put_keys,
    py::list table_put_values
) {
    ssize_t built_results = 0;
    ssize_t shared_hits = 0;
    for (auto item : pattern_items) {
        py::object pattern = py::reinterpret_borrow<py::object>(item.first);
        py::sequence rows = py::reinterpret_borrow<py::sequence>(item.second);
        py::object env = py::none();
        py::object qns = py::make_tuple(zero_qn);
        if (static_cast<ssize_t>(py::len(pattern)) != 0) {
            py::object suffix_key = py::make_tuple(py::int_(revision), token, pattern);
            py::object entry = py::none();
            if (suffix_cache.contains(suffix_key)) {
                entry = py::reinterpret_borrow<py::object>(suffix_cache[suffix_key]);
            } else {
                py::object shared_key = contextual_right_shared_suffix_key(
                    shared_suffix_key_fn,
                    pattern,
                    revision
                );
                if (suffix_cache.contains(shared_key)) {
                    entry = py::reinterpret_borrow<py::object>(suffix_cache[shared_key]);
                    suffix_cache[suffix_key] = entry;
                    ++shared_hits;
                }
            }
            if (entry.is_none()) {
                continue;
            }
            py::sequence entry_seq = entry.cast<py::sequence>();
            env = py::reinterpret_borrow<py::object>(entry_seq[1]);
            qns = py::reinterpret_borrow<py::object>(entry_seq[2]);
        }
        const ssize_t n_rows = static_cast<ssize_t>(py::len(rows));
        for (ssize_t ridx = 0; ridx < n_rows; ++ridx) {
            py::sequence row = py::reinterpret_borrow<py::sequence>(rows[ridx]);
            const ssize_t out_idx = py::cast<ssize_t>(row[0]);
            py::object local_piece = py::reinterpret_borrow<py::object>(row[1]);
            py::object cache_key = py::reinterpret_borrow<py::object>(row[2]);
            py::object table_key = py::reinterpret_borrow<py::object>(row[3]);
            py::object w_local = site_operator_fn(local_piece, py::int_(local_site), qns);
            if (w_local.is_none()) {
                continue;
            }
            py::object pair;
            if (env.is_none()) {
                py::object initial = initial_fn(w_local);
                pair = py::make_tuple(w_local, initial);
            } else {
                pair = py::make_tuple(w_local, env);
            }
            py::object result = pack_result_fn(pair);
            env_cache[cache_key] = result;
            table_put_keys.append(table_key);
            table_put_values.append(result);
            results[py::int_(out_idx)] = result;
            ++built_results;
        }
    }
    return py::make_tuple(py::int_(built_results), py::int_(shared_hits));
}

static py::tuple contextual_right_finalize_prebuilt_batch(
    py::dict pattern_items,
    py::list results,
    py::dict suffix_cache,
    py::object shared_suffix_key_fn,
    ssize_t revision,
    py::object token,
    ssize_t local_site,
    py::object zero_qn,
    py::dict local_table,
    py::dict env_cache,
    py::list table_put_keys,
    py::list table_put_values
) {
    ssize_t built_results = 0;
    ssize_t shared_hits = 0;
    ssize_t local_hits = 0;
    ssize_t local_misses = 0;
    for (auto item : pattern_items) {
        py::object pattern = py::reinterpret_borrow<py::object>(item.first);
        py::sequence rows = py::reinterpret_borrow<py::sequence>(item.second);
        py::object env = py::none();
        py::object qns = py::make_tuple(zero_qn);
        if (static_cast<ssize_t>(py::len(pattern)) != 0) {
            py::object suffix_key = py::make_tuple(py::int_(revision), token, pattern);
            py::object entry = py::none();
            if (suffix_cache.contains(suffix_key)) {
                entry = py::reinterpret_borrow<py::object>(suffix_cache[suffix_key]);
            } else {
                py::object shared_key = contextual_right_shared_suffix_key(
                    shared_suffix_key_fn,
                    pattern,
                    revision
                );
                if (suffix_cache.contains(shared_key)) {
                    entry = py::reinterpret_borrow<py::object>(suffix_cache[shared_key]);
                    suffix_cache[suffix_key] = entry;
                    ++shared_hits;
                }
            }
            if (entry.is_none()) {
                continue;
            }
            py::sequence entry_seq = entry.cast<py::sequence>();
            env = py::reinterpret_borrow<py::object>(entry_seq[1]);
            qns = py::reinterpret_borrow<py::object>(entry_seq[2]);
        }
        py::object qns_key = tuple_from_sequence_object(qns);
        const ssize_t n_rows = static_cast<ssize_t>(py::len(rows));
        for (ssize_t ridx = 0; ridx < n_rows; ++ridx) {
            py::sequence row = py::reinterpret_borrow<py::sequence>(rows[ridx]);
            const ssize_t out_idx = py::cast<ssize_t>(row[0]);
            py::object local_piece = py::reinterpret_borrow<py::object>(row[1]);
            py::object cache_key = py::reinterpret_borrow<py::object>(row[2]);
            py::object table_key = py::reinterpret_borrow<py::object>(row[3]);
            py::object local_key = py::make_tuple(py::str(local_piece), py::int_(local_site), qns_key);
            if (!local_table.contains(local_key)) {
                ++local_misses;
                continue;
            }
            py::sequence local_entry = py::reinterpret_borrow<py::object>(local_table[local_key]).cast<py::sequence>();
            py::object w_local = py::reinterpret_borrow<py::object>(local_entry[0]);
            py::object initial = py::reinterpret_borrow<py::object>(local_entry[1]);
            py::object result = env.is_none()
                ? py::make_tuple(w_local, initial)
                : py::make_tuple(w_local, env);
            env_cache[cache_key] = result;
            table_put_keys.append(table_key);
            table_put_values.append(result);
            results[py::int_(out_idx)] = result;
            ++built_results;
            ++local_hits;
        }
    }
    return py::make_tuple(
        py::int_(built_results),
        py::int_(shared_hits),
        py::int_(local_hits),
        py::int_(local_misses)
    );
}

static py::tuple contextual_right_prepare_local_table_batch(
    py::dict pattern_items,
    py::dict suffix_cache,
    py::object shared_suffix_key_fn,
    ssize_t revision,
    py::object token,
    ssize_t local_site,
    py::object zero_qn
) {
    py::dict seen;
    py::list rows_out;
    ssize_t shared_hits = 0;
    ssize_t missing_env_rows = 0;
    for (auto item : pattern_items) {
        py::object pattern = py::reinterpret_borrow<py::object>(item.first);
        py::sequence rows = py::reinterpret_borrow<py::sequence>(item.second);
        py::object qns = py::make_tuple(zero_qn);
        if (static_cast<ssize_t>(py::len(pattern)) != 0) {
            py::object suffix_key = py::make_tuple(py::int_(revision), token, pattern);
            py::object entry = py::none();
            if (suffix_cache.contains(suffix_key)) {
                entry = py::reinterpret_borrow<py::object>(suffix_cache[suffix_key]);
            } else {
                py::object shared_key = contextual_right_shared_suffix_key(
                    shared_suffix_key_fn,
                    pattern,
                    revision
                );
                if (suffix_cache.contains(shared_key)) {
                    entry = py::reinterpret_borrow<py::object>(suffix_cache[shared_key]);
                    suffix_cache[suffix_key] = entry;
                    ++shared_hits;
                }
            }
            if (entry.is_none()) {
                missing_env_rows += static_cast<ssize_t>(py::len(rows));
                continue;
            }
            py::sequence entry_seq = entry.cast<py::sequence>();
            qns = py::reinterpret_borrow<py::object>(entry_seq[2]);
        }
        py::object qns_key = tuple_from_sequence_object(qns);
        const ssize_t n_rows = static_cast<ssize_t>(py::len(rows));
        for (ssize_t ridx = 0; ridx < n_rows; ++ridx) {
            py::sequence row = py::reinterpret_borrow<py::sequence>(rows[ridx]);
            py::object local_piece = py::reinterpret_borrow<py::object>(row[1]);
            py::object local_key = py::make_tuple(py::str(local_piece), py::int_(local_site), qns_key);
            if (seen.contains(local_key)) {
                continue;
            }
            seen[local_key] = py::none();
            rows_out.append(py::make_tuple(local_key, local_piece, py::int_(local_site), qns_key));
        }
    }
    return py::make_tuple(
        rows_out,
        py::int_(shared_hits),
        py::int_(missing_env_rows),
        py::int_(py::len(rows_out))
    );
}

